function PMS(r){try{var t=window.top;if(t!==window&&t.PortalMusic&&t.PortalMusic.sfx)return t.PortalMusic.sfx(new URL(r,location.href).href);}catch(e){}return new Audio(r);}
const $ = (s, el = document) => el.querySelector(s);
const app = $('#game-container');

const audio = {
  muted: localStorage.getItem('auroraMuted') === '1', unlocked: false,
  music: (function(){try{var t=window.top;if(t!==window&&t.PortalMusic)return t.PortalMusic.proxy;}catch(e){}return null;})() || new Audio('/assets/audio/musica-portal.mp3'),
  tap: PMS('assets/audio/toque-estelar.mp3'),
  reveal: PMS('assets/audio/revelacion-cristalina.mp3')
};
audio.music.loop = true; audio.music.volume = .18; audio.tap.volume = .3; audio.reveal.volume = .35;
function unlockAudio(){ if(audio.unlocked) return; audio.unlocked=true; if(!audio.muted) audio.music.play().catch(()=>{}); }
function sound(kind='tap'){ unlockAudio(); if(audio.muted)return; const a=audio[kind]; a.currentTime=0; a.play().catch(()=>{}); }

document.addEventListener('pointerdown', unlockAudio, {once:true});
const glyphs = {dream:'☾',esp:'✦',ritual:'✧',zodiac:'♊',chinese:'◉',angels:'✺',guardian:'☥'};
const tools = [
  ['dream','Significado de sueños','Descifra los símbolos de tu mundo onírico','#9470e5'],
  ['esp','Percepción extrasensorial','Pon a prueba tu intuición en 5 rondas','#f0ca69'],
  ['ritual','Hechizos y rituales','Prácticas sencillas para enfocar tu intención','#d573b9'],
  ['zodiac','Compatibilidad de signos','Explora la energía entre dos signos','#58bde8'],
  ['chinese','Padres e hijos','Afinidad según el horóscopo chino','#e39c5c'],
  ['angels','Mensajes angelicales','Explora coros, símbolos y mensajes para tu día','#e8b9ff'],
  ['guardian','Tu ángel de la guarda','Descubre cuál de los 72 ángeles te protege','#f6e3a1']
];
const state={screen:'home', espRound:0, espHits:0, espTarget:null, ritual:'proteccion', angelChoir:'Querubines'};

function shell(content, home=false, hideMute=false){
  // Vuelve a "armar" la protección de navegación en cada cambio de pantalla, para que el botón/gesto
  // "atrás" del navegador o del celular siempre tenga un paso interno que consumir antes de salir de la app.
  // Se aplica en el siguiente "tick" (no de forma síncrona) porque algunas versiones de Safari en iPhone
  // ignoran un pushState llamado de forma síncrona dentro del propio evento "atrás" (popstate).
  setTimeout(()=>{try{window.history.pushState({app:true},'',location.href)}catch(e){}},0);
  app.innerHTML=`<div class="app"><header class="topbar">${home?'<span class="spacer"></span>':'<button class="back" aria-label="Volver">‹</button>'}<div class="brand"></div>${hideMute?'<span class="spacer"></span>':'<button class="icon-btn" id="mute" aria-label="Sonido">'+(audio.muted?'♩':'♫')+'</button>'}</header><main class="viewport">${content}</main><div class="toast"></div></div>`;
  if(!hideMute) $('#mute').onclick=()=>{audio.muted=!audio.muted; localStorage.setItem('auroraMuted',audio.muted?'1':'0'); if(audio.muted)audio.music.pause();else {unlockAudio();audio.music.play().catch(()=>{});} $('#mute').textContent=audio.muted?'♩':'♫'};
  if(!home) $('.back').onclick=()=>{sound(); renderHome()};
}
function head(icon,title,sub){return `<div class="screen-head"><div class="screen-glyph">${icon}</div><h1 class="screen-title">${title}</h1><p class="subtitle">${sub}</p></div>`}
function toast(msg){const t=$('.toast');t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),1600)}
function log(name,data={}){window.ProgressLogger?.logProgress(name,data)}

function renderHome(){state.screen='home';shell(`<section class="hero"><img class="oracle" src="assets/oraculo-cristal.webp" alt="Oráculo de cristal"><p class="eyebrow">Tu espacio de intuición</p><h1>Escucha las señales</h1><p>Siete caminos para explorar símbolos, vínculos y percepción.</p><span class="daily">✦ Mensaje del día: confía en lo sutil</span></section><section class="tool-grid">${tools.map(([id,n,d,c])=>`<button class="tool-card" data-tool="${id}" style="--accent:${c}"><span class="tool-icon">${glyphs[id]}</span><b>${n}</b><small>${d}</small></button>`).join('')}</section>`,true);
  document.querySelectorAll('[data-tool]').forEach(b=>b.onclick=()=>{sound();log('open_tool',{tool:b.dataset.tool}); routes[b.dataset.tool]()});
}

// Diccionario de símbolos de sueños, construido combinando tres fuentes reconocidas:
// 1) la psicología junguiana (los sueños como mensajes del inconsciente y arquetipos compartidos),
// 2) los diccionarios de símbolos de sueños más consultados (p. ej. el de Tony Crisp, "Dream Dictionary from A to Z"),
// 3) la visión moderna de la ciencia del sueño (los sueños como procesamiento emocional y de memoria, no profecías).
// Cada símbolo trae: título, significado consensuado, una capa psicológica más profunda, y una pregunta de reflexión propia (no genérica).
const dreams={
  agua:['Agua','El agua es, en casi toda tradición de símbolos, el espejo del mundo emocional. Clara y en calma habla de serenidad; turbia o agitada señala sentimientos que todavía no has procesado.','Jung consideraba el agua una de las imágenes más antiguas del inconsciente: no la razón, sino lo que sientes sin poder nombrarlo todavía.','¿Qué emoción llevas dentro desde hace días sin haberle puesto palabras?'],
  mar:['Mar','El mar representa lo emocional en su versión más vasta: lo que escapa a tu control. Verlo tranquilo desde la orilla habla de aceptación; estar dentro de él, de sentirte a merced de algo más grande.','A diferencia del agua de un vaso o un río, el mar no se puede contener. Suele aparecer cuando una situación de tu vida se siente más grande que tu capacidad actual de manejarla.','¿Qué parte de tu vida sientes que no puedes controlar del todo ahora mismo?'],
  nadar:['Nadar','Nadar con soltura simboliza que estás manejando bien tus emociones, aunque el entorno sea exigente. Nadar con esfuerzo habla de estar sosteniendo algo a pulso.','El esfuerzo del movimiento es la clave: si avanzabas con facilidad, tu energía está alineada con el reto actual; si te costaba, puede ser momento de pedir ayuda.','¿Estás intentando resolver algo solo que en realidad admite compañía?'],
  serpiente:['Serpiente','La serpiente es uno de los símbolos más antiguos y ambivalentes: representa transformación, sanación e instinto, pero también amenaza o traición, según cómo se comportaba.','En la tradición junguiana la serpiente está ligada al proceso de renovación —como la piel que muda— y a la energía vital que el consciente aún no ha integrado del todo.','¿Qué parte de ti está cambiando de forma, aunque todavía te resulte incómoda o desconocida?'],
  araña:['Araña','La araña suele vincularse con la sensación de estar atrapado en una red de obligaciones, o con una figura femenina (real o interna) que se percibe como controladora o tejedora de situaciones.','En algunas lecturas también representa paciencia y creatividad: la araña construye con precisión lo que necesita para sobrevivir, sin prisa.','¿Sientes que alguien —o tú mismo— está tejiendo una situación de la que te cuesta salir?'],
  lobo:['Lobo','El lobo combina instinto, independencia y la tensión entre pertenecer a un grupo y seguir el propio camino. Puede representar una amenaza percibida o una parte salvaje de ti que pides permiso para expresar.','Es un símbolo de alerta pero también de lealtad: los lobos cuidan su manada. El contexto (si atacaba o acompañaba) cambia completamente la lectura.','¿Qué instinto tuyo llevas tiempo silenciando por encajar en lo que se espera de ti?'],
  gato:['Gato','El gato simboliza independencia, intuición y un control sutil sobre el propio espacio. A diferencia del perro, no busca aprobación: representa una parte tuya que confía en su propio criterio.','Muchas lecturas lo asocian también con el misterio femenino y con una sensibilidad que percibe cosas antes de poder explicarlas con lógica.','¿Qué decisión reciente tomaste más por intuición que por análisis?'],
  perro:['Perro','El perro es, casi universalmente, símbolo de lealtad, protección y vínculos de confianza. Un perro amistoso habla de apoyo disponible; uno agresivo, de una lealtad que se siente amenazada o puesta a prueba.','Soñar con perros suele activarse en periodos donde la confianza —propia o ajena— está en el centro de alguna relación importante.','¿En qué vínculo necesitas sentir (o demostrar) más lealtad en este momento?'],
  caballo:['Caballo','El caballo representa energía vital, impulso y libertad de movimiento. Un caballo desbocado habla de fuerza sin dirección; uno guiado con calma, de poder personal bien encauzado.','Es un símbolo recurrente en momentos de cambio de ritmo vital: nuevos proyectos, mudanzas o decisiones que exigen avanzar con decisión.','¿Dónde necesitas más impulso, y dónde necesitas más riendas?'],
  pájaro:['Pájaro / ave','Las aves simbolizan perspectiva, libertad y mensajes que llegan desde una parte más elevada de ti mismo. Volar alto habla de visión de conjunto; un ave herida, de un mensaje que cuesta escuchar.','En muchas culturas los pájaros son mensajeros entre mundos; en clave psicológica, suelen representar pensamientos o intuiciones que "llegan de pronto".','¿Qué idea o intuición reciente mereces tomar más en serio?'],
  volar:['Volar','Volar en sueños suele asociarse con libertad, perspectiva y el deseo de superar un límite que sientes en la vida despierta. También puede señalar una confianza creciente en tus propias capacidades.','Es uno de los llamados "sueños lúcidos" más estudiados: aparece con más frecuencia cuando una persona está atravesando una etapa de mayor autonomía o logro personal.','¿Qué límite sientes que estás a punto de superar?'],
  caer:['Caer','Caer es, según los estudios de sueño, una de las imágenes más comunes del mundo: suele expresar pérdida de control, inseguridad o el miedo a fallar en algo que sientes importante.','Con frecuencia aparece justo antes de despertar, coincidiendo con un cambio real en la postura del cuerpo; eso no le resta significado emocional, pero explica por qué es tan recurrente.','¿En qué situación sientes que estás perdiendo el equilibrio o el control?'],
  volcan:['Volcán','El volcán representa emociones intensas —sobre todo enojo o frustración— que se han contenido durante demasiado tiempo y buscan una salida.','A diferencia del fuego cotidiano, el volcán sugiere algo acumulado desde hace tiempo, no una reacción puntual.','¿Qué llevas conteniendo por evitar un conflicto, y a qué costo?'],
  fuego:['Fuego','El fuego es energía de cambio, pasión y transformación. Controlado, el fuego ilumina y purifica; descontrolado, advierte que una emoción intensa necesita un cauce.','Muchas tradiciones lo asocian con la pasión creativa o sexual, además de con la ira. El tono emocional del sueño —miedo o fascinación— ayuda a distinguir cuál era.','¿Qué pasión o enojo necesita más espacio del que le estás dando ahora?'],
  casa:['Casa','La casa representa tu mundo interior y tu sentido de identidad. Cada habitación suele simbolizar una faceta distinta: el sótano, lo que reprimes; el ático, tus ideales; la cocina, el cuidado de ti mismo.','Encontrar habitaciones desconocidas en una casa familiar es un símbolo muy estudiado: suele señalar partes de ti mismo que aún no has explorado conscientemente.','¿Qué parte de ti mismo sientes que todavía no conoces del todo?'],
  puerta:['Puerta','Una puerta representa una decisión o una transición disponible. Abierta, invita a avanzar; cerrada o atascada, refleja una oportunidad que sientes bloqueada.','El detalle de si la cruzabas con miedo o con curiosidad suele decir más que la puerta misma sobre cómo te sientes frente al cambio.','¿Qué decisión tienes frente a ti que llevas tiempo posponiendo?'],
  ventana:['Ventana','La ventana simboliza perspectiva: la forma en que miras tu vida desde dentro, o cómo el mundo exterior te observa a ti. Una ventana rota o sucia habla de una visión distorsionada por el estrés o el miedo.','A diferencia de la puerta, la ventana no implica cruzar, solo observar: suele aparecer cuando necesitas claridad antes de decidir, no acción inmediata.','¿Qué situación necesitas mirar con más distancia antes de actuar?'],
  escalera:['Escalera','Subir una escalera representa progreso, ambición y esfuerzo sostenido hacia una meta. Bajarla puede hablar de introspección o de un retroceso que, lejos de ser negativo, es necesario para avanzar después.','Una escalera que no termina de subirse es un símbolo clásico de objetivos que se sienten siempre un paso fuera de alcance.','¿Qué meta sientes que avanzas sin terminar nunca de alcanzar?'],
  espejo:['Espejo','El espejo representa autoimagen y autoconocimiento. Ver un reflejo distinto al tuyo es una de las imágenes oníricas más estudiadas: suele señalar una discrepancia entre cómo te ves y cómo te sientes por dentro.','Romper un espejo se asocia tradicionalmente con un cambio brusco de identidad, no necesariamente negativo: algo de cómo te definías está dejando de ser cierto.','¿Hay alguna forma en que te ves a ti mismo que ya no coincide con quién eres ahora?'],
  dientes:['Dientes','Soñar que se caen los dientes es, según varios estudios, uno de los sueños más comunes a nivel mundial. Suele vincularse con la autoimagen, el miedo a envejecer, o la ansiedad por cómo te perciben los demás al hablar.','También puede señalar una sensación de pérdida de poder o de "mordida": una situación donde sientes que ya no puedes defender tu postura con firmeza.','¿En qué conversación o relación sientes que has perdido fuerza para expresarte?'],
  desnudo:['Estar desnudo','Soñar que estás desnudo en público expresa, casi siempre, miedo a ser juzgado o a que descubran algo que preferías mantener privado.','La reacción de la gente alrededor en el sueño es la clave: si nadie lo notaba, el miedo puede ser más interno que real; si se burlaban, hay una herida de vergüenza activa.','¿Qué parte de ti temes que los demás descubran si te conocieran mejor?'],
  examen:['Examen / prueba','Soñar con un examen para el que no estudiaste refleja, casi siempre, la sensación de estar siendo evaluado en la vida real —en el trabajo, una relación o una meta personal— sin sentirte del todo preparado.','Es uno de los llamados "sueños de ansiedad de desempeño": aparece más en personas exigentes consigo mismas, incluso cuando objetivamente están bien preparadas.','¿En qué área de tu vida sientes que te están evaluando, aunque nadie lo diga en voz alta?'],
  perseguir:['Ser perseguido','Ser perseguido en un sueño suele representar una preocupación, responsabilidad o emoción que evitas enfrentar directamente en la vida despierta.','Quien o qué te persigue es la pista central: a menudo representa justo aquello de lo que huyes estando despierto. Detenerse a mirarlo de frente, en terapia del sueño, se asocia con resolución del conflicto.','Si dejaras de correr y te dieras vuelta a mirar, ¿qué crees que encontrarías?'],
  bebe:['Bebé','Un bebé en sueños suele simbolizar un comienzo: un proyecto, una idea o una parte de ti mismo que es nueva y todavía frágil. Si el sueño generaba ternura, el comienzo se siente bienvenido; si generaba ansiedad, da miedo la responsabilidad que implica.','No necesariamente está relacionado con la maternidad o paternidad literal: la psicología del sueño lo lee más como símbolo de potencial en desarrollo.','¿Qué proyecto o idea tuya es todavía demasiado nuevo como para mostrarlo al mundo?'],
  embarazo:['Embarazo','Soñar con un embarazo —propio o ajeno— simboliza tradicionalmente que algo nuevo se está gestando en tu vida: una idea, un cambio de etapa o una versión de ti mismo todavía en formación.','La ansiedad o ilusión que acompañaba el sueño suele reflejar cómo te sientes frente a ese proceso de gestación, más que un anuncio literal.','¿Qué parte de tu vida está "en gestación" todavía, sin estar lista para mostrarse?'],
  boda:['Boda','Una boda representa un compromiso o una unión importante: entre dos personas, pero también entre dos partes de ti mismo que buscan integrarse.','Dudar o sentir pánico en la boda soñada es más frecuente de lo que parece y no necesariamente anticipa arrepentimiento: suele reflejar el peso natural de comprometerse con algo grande.','¿Con qué decisión o compromiso sientes que estás a punto de "casarte" en tu vida?'],
  muerte:['Muerte','La muerte en sueños rara vez es literal. En la enorme mayoría de los casos representa el cierre de una etapa, una transformación profunda o el final de una forma de ser que ya no te representa.','Es, junto con caer y los dientes, uno de los símbolos más universales y menos literales del repertorio onírico: casi todas las tradiciones coinciden en leerlo como cambio, no como advertencia.','¿Qué etapa, hábito o relación sientes que está llegando a su fin de forma natural?'],
  fantasma:['Fantasma','Un fantasma suele representar algo del pasado —una relación, una culpa, un recuerdo— que no ha sido resuelto del todo y todavía influye en tu presente.','A diferencia de la muerte como símbolo de cierre, el fantasma indica justamente lo contrario: algo que debería haberse cerrado y sigue presente.','¿Qué situación del pasado sientes que aún no terminaste de soltar?'],
  accidente:['Accidente','Soñar con un accidente —de auto, avión o similar— suele reflejar miedo a perder el control sobre una situación que avanza más rápido de lo que te sientes capaz de manejar.','El tipo de vehículo importa: un carro habla de tu propio manejo de la vida diaria; un avión, de proyectos más grandes o ambiciosos.','¿Dónde sientes que las cosas están avanzando más rápido de lo que puedes controlar?'],
  dinero:['Dinero','El dinero en sueños rara vez trata de finanzas literales: suele representar autoestima, valor propio o seguridad. Encontrar dinero habla de recursos internos que no sabías que tenías; perderlo, de inseguridad.','Robar o que te roben dinero en un sueño suele apuntar a sentir que algo tuyo —tiempo, mérito, reconocimiento— no está siendo respetado.','¿Dónde sientes que tu esfuerzo o tu valor no está siendo reconocido como debería?'],
  robo:['Robo','Ser víctima de un robo en sueños suele representar la sensación de que algo tuyo —tiempo, confianza, espacio— está siendo invadido o aprovechado por alguien más.','Si en el sueño eras tú quien robaba, puede señalar culpa por tomar algo (una decisión, un espacio) que sientes que no te "corresponde" del todo.','¿Sientes que algo tuyo está siendo aprovechado sin tu consentimiento?'],
  prision:['Prisión / encierro','Soñar que estás encerrado representa, casi siempre, una sensación real de estar atrapado: en una rutina, una relación o una obligación que sientes que no puedes abandonar.','La forma de salir (o no) del encierro en el sueño suele reflejar cuánta esperanza sientes frente a esa situación en la vida despierta.','¿Qué parte de tu vida se siente como una jaula que tú mismo ayudaste a construir?'],
  llave:['Llave','La llave simboliza acceso: a una oportunidad, una respuesta o una parte de ti mismo que antes estaba fuera de alcance. Perder una llave en sueños habla de sentir que se te escapa una solución.','Encontrar una llave inesperada suele aparecer cuando, en la vida despierta, estás a punto de resolver algo que llevaba tiempo trabado.','¿Qué "puerta" de tu vida sientes que por fin tienes forma de abrir?'],
  camino:['Camino / carretera','Un camino representa tu sentido de dirección en la vida. Uno recto y despejado habla de claridad; uno que se bifurca o se pierde, de dudas frente a una decisión importante.','El estado del camino —liso, con obstáculos, en construcción— suele reflejar cómo sientes, concretamente, el avance de tus planes actuales.','¿En qué decisión sientes que el camino se bifurca y no sabes qué dirección tomar?'],
  montaña:['Montaña','La montaña simboliza un reto importante y el esfuerzo necesario para superarlo. Llegar a la cima representa logro; quedarte a medio camino, un objetivo que aún exige paciencia.','La dificultad del ascenso en el sueño suele ser proporcional a cuán grande sientes el desafío que enfrentas actualmente despierto.','¿Qué meta sientes que exige más paciencia de la que te has dado hasta ahora?'],
  bosque:['Bosque','El bosque representa lo desconocido dentro de ti mismo: instintos, miedos o posibilidades que todavía no has explorado del todo conscientemente.','Perderse en un bosque es un símbolo recurrente en momentos donde una persona siente que no tiene claro su propio camino interior, más allá de lo externo.','¿Qué parte de ti mismo sientes que apenas estás empezando a descubrir?'],
  tormenta:['Tormenta','Una tormenta representa emociones intensas que se están liberando, muchas veces después de haberlas contenido. No siempre es negativa: después de la tormenta suele venir claridad.','El miedo o la calma que sentías durante la tormenta en el sueño indica si esa liberación emocional se siente como algo que controlas o que te controla.','¿Qué emoción sientes que necesita "estallar" para poder después asentarse?'],
  luna:['Luna','La luna se asocia tradicionalmente con la intuición, lo cíclico y el mundo emocional menos consciente —en contraste con el sol, símbolo de la razón y lo exterior.','Las distintas fases lunares en los sueños suelen reflejar en qué punto de un ciclo emocional o personal sientes que te encuentras: comenzando, en plenitud o cerrando una etapa.','¿En qué "fase" de un ciclo personal sientes que estás ahora mismo?'],
  sol:['Sol','El sol representa claridad, vitalidad y la parte consciente y racional de ti mismo. Un sol brillante habla de energía disponible; uno oculto por nubes, de claridad que todavía no termina de llegar.','En muchas lecturas, el sol es la contraparte de la luna: mientras ella simboliza lo intuitivo, el sol representa la comprensión consciente de una situación.','¿Qué situación sientes que por fin estás empezando a ver con claridad?'],
  estrella:['Estrella','Las estrellas simbolizan esperanza, guía y aspiraciones a largo plazo. Verlas con claridad habla de tener un norte definido; un cielo nublado que las oculta, de sentir perdida esa guía por ahora.','Es un símbolo muy ligado al deseo y a las metas de vida, más que a situaciones inmediatas o cotidianas.','¿Cuál es, hoy, tu "estrella" — la meta de largo plazo que te sigue orientando?'],
  oscuridad:['Oscuridad','La oscuridad representa lo desconocido: aquello que aún no comprendes o que te genera incertidumbre. No simboliza necesariamente peligro, sino falta de información o de claridad.','La forma en que reaccionabas —miedo o calma— ante la oscuridad del sueño suele reflejar cómo te sientes, en general, frente a lo incierto en tu vida.','¿Qué parte de tu futuro cercano se siente incierta, más que peligrosa?'],
  tren:['Tren / avión','Los medios de transporte colectivo simbolizan una etapa de vida compartida con otros: un trabajo, una familia, un proyecto común. Perder el tren o el avión habla de sentir que te quedas fuera de un plan importante.','A diferencia del auto —que representa tu manejo individual—, el tren y el avión señalan procesos donde dependes también del ritmo de otras personas.','¿En qué plan compartido sientes que podrías estar quedándote atrás?'],
  reloj:['Reloj / tiempo','Un reloj en sueños suele representar la sensación de que el tiempo se agota o de que una decisión tiene una fecha límite —real o autoimpuesta.','Un reloj detenido puede señalar, al contrario, una situación estancada que necesitas volver a poner en movimiento.','¿Qué decisión sientes que llevas demasiado tiempo posponiendo?'],
  comida:['Comida','La comida en sueños suele representar nutrición emocional: lo que necesitas (o te hace falta) para sentirte sostenido. Compartir comida habla de vínculo; comer solo, de una necesidad no del todo satisfecha.','La abundancia o escasez de comida en el sueño suele reflejar cómo sientes, en general, que están cubiertas tus necesidades afectivas actuales.','¿Qué necesitas ahora mismo para sentirte más sostenido emocionalmente?'],
  sangre:['Sangre','La sangre simboliza vitalidad y también sacrificio: lo que te cuesta esfuerzo, energía o entrega. Perder sangre en un sueño puede hablar de sentirte agotado por dar más de lo que recibes.','En algunas lecturas también representa vínculos familiares profundos ("lazos de sangre"), especialmente cuando aparece junto a figuras cercanas.','¿En qué relación sientes que estás dando más energía de la que te están devolviendo?'],
  correr:['Correr sin avanzar','Soñar que corres pero no avanzas —o que las piernas no responden— es uno de los símbolos de frustración más estudiados: refleja el esfuerzo que haces en una situación donde sientes que los resultados no llegan al ritmo que esperas.','Suele intensificarse en periodos donde el esfuerzo real está siendo mayor que los avances visibles, generando una frustración legítima.','¿Dónde sientes que tu esfuerzo no está dando los resultados que esperabas, al menos todavía?'],
  leon:['León','El león representa autoridad, fuerza personal y la necesidad de hacer respetar tu espacio. Verlo tranquilo habla de seguridad en ti mismo; si atacaba, de una autoridad —propia o ajena— que se siente amenazante.','En la simbología junguiana el león suele representar también a una figura paterna o de poder, real o interiorizada, frente a la que mides tu propia fuerza.','¿Frente a quién sientes que necesitas hacer valer más tu autoridad o tu espacio?'],
  tigre:['Tigre','El tigre simboliza una fuerza instintiva más solitaria que la del león: poder personal, pasión contenida y la capacidad de actuar con decisión cuando hace falta.','Soñar con un tigre suele aparecer en momentos donde una parte tuya, normalmente calmada, necesita mostrarse con más contundencia.','¿En qué situación necesitas mostrar una fuerza que normalmente mantienes guardada?'],
  oso:['Oso','El oso representa protección, fuerza tranquila y también la necesidad de un periodo de retiro o descanso —como su hibernación— antes de volver a actuar.','Un oso agresivo en el sueño suele señalar que una necesidad de protección propia o de un ser querido no está siendo del todo atendida.','¿Necesitas más protección para ti mismo, o darte un descanso que llevas tiempo postergando?'],
  elefante:['Elefante','El elefante simboliza memoria, paciencia y una fuerza tranquila que no necesita demostrarse con violencia. También se asocia con la familia y lo que se recuerda durante mucho tiempo.','Es un símbolo frecuente cuando algo del pasado —un recuerdo, una lealtad familiar— sigue pesando en tus decisiones actuales.','¿Qué recuerdo o lealtad familiar sigue influyendo en una decisión que estás tomando hoy?'],
  mono:['Mono','El mono representa ingenio, imitación y una energía inquieta que busca resolver problemas jugando más que con seriedad. También puede señalar una parte de ti que se siente dispersa.','Suele aparecer cuando necesitas más flexibilidad o creatividad frente a un problema que has estado abordando siempre de la misma forma.','¿Qué problema podrías resolver si dejaras de tomártelo tan en serio?'],
  toro:['Toro','El toro simboliza fuerza bruta, terquedad y una energía que, bien dirigida, puede mover grandes cosas. Un toro embistiendo suele reflejar frustración acumulada que busca salida.','También se asocia con la resistencia al cambio: una parte tuya que se planta con firmeza frente a algo que preferirías evitar.','¿Dónde estás siendo más terco de lo que te conviene?'],
  conejo:['Conejo','El conejo representa fertilidad, rapidez y también nerviosismo o huida ante el conflicto. Verlo escapar habla de evitar una confrontación; verlo tranquilo, de sentirte a salvo.','En muchas lecturas simboliza también la multiplicación de ideas o proyectos, a veces más rápida de lo que puedes sostener.','¿Hay algo de lo que llevas tiempo huyendo en lugar de enfrentarlo?'],
  raton:['Ratón','El ratón suele representar algo pequeño que, sin embargo, te genera una preocupación desproporcionada: un detalle que roe por dentro aunque parezca menor desde fuera.','También puede señalar sentirte invisible o pasado por alto en una situación donde esperabas más atención.','¿Qué preocupación "pequeña" te está quitando más energía de la que admites?'],
  pez:['Pez','El pez simboliza lo que se mueve en las profundidades de tu mundo emocional o inconsciente: ideas, intuiciones o sentimientos que aún no has traído del todo a la superficie.','Un pez brillante o dorado suele asociarse con una idea valiosa que está por "subir a la superficie" de tu conciencia.','¿Qué idea o intuición sientes que está a punto de hacerse clara?'],
  tiburon:['Tiburón','El tiburón representa una amenaza fría y calculadora: puede señalar a una persona o situación que percibes como depredadora, o un miedo profundo que no termina de tener forma clara.','A diferencia del lobo, el tiburón suele representar peligro impersonal, no instinto: algo que "está ahí" sin que lo puedas razonar o negociar.','¿Hay una situación donde te sientes en desventaja frente a algo que no puedes controlar ni predecir?'],
  ballena:['Ballena','La ballena simboliza la inmensidad del mundo emocional o espiritual: algo profundo, antiguo y mucho más grande que los conflictos cotidianos.','Suele aparecer en periodos de búsqueda de sentido, cuando una persona empieza a hacerse preguntas más grandes sobre su vida.','¿Qué pregunta "grande" sobre tu vida llevas tiempo rondando sin atreverte a mirarla de frente?'],
  mariposa:['Mariposa','La mariposa es uno de los símbolos de transformación más claros: habla de un cambio que ya completaste o que está por completarse, dejando atrás una versión anterior de ti.','A diferencia de la serpiente —transformación en proceso—, la mariposa suele señalar que el cambio ya sucedió y solo falta reconocerlo.','¿Qué transformación en ti ya ocurrió, aunque todavía no termines de notarla?'],
  cuervo:['Cuervo','El cuervo se asocia con la inteligencia, los presagios y los mensajes difíciles de recibir. No es un símbolo de mala suerte en sí mismo, sino de información que preferirías no tener que procesar.','En muchas tradiciones también representa la capacidad de ver lo que otros prefieren ignorar.','¿Hay algo que ya sabes, aunque preferirías no haberlo notado?'],
  paloma:['Paloma','La paloma simboliza paz, reconciliación o un mensaje de calma después de un periodo de tensión. Verla volar suele reflejar alivio o el deseo de que un conflicto se resuelva pronto.','Es un símbolo que aparece con frecuencia justo después de discusiones o periodos de tensión emocional importantes.','¿Qué conflicto reciente estás deseando que se resuelva en paz?'],
  cerdo:['Cerdo','El cerdo se asocia con abundancia, disfrute y también con excesos. Puede señalar una necesidad legítima de placer y descanso, o una advertencia sobre un exceso que ya sientes que es demasiado.','El tono del sueño —festivo o incómodo— suele distinguir si representa disfrute merecido o un exceso que te preocupa.','¿Qué "exceso" en tu vida sientes que empieza a pasar factura?'],
  jefe:['Jefe / autoridad','Soñar con el jefe o una figura de autoridad suele reflejar cómo te sientes evaluado en tu vida —no solo laboral— y cuánto control sientes sobre tus propias decisiones frente a esa persona.','El tono del sueño (amenazante, indiferente, aprobador) suele reflejar directamente tu nivel actual de ansiedad laboral o de desempeño.','¿Frente a qué autoridad sientes que necesitas más reconocimiento o más límites?'],
  trabajo:['Trabajo','Soñar con el trabajo —sobre todo fuera de horario— suele reflejar una carga mental que no logras "apagar" del todo, incluso al descansar.','Es uno de los temas oníricos que más ha crecido en los estudios de sueño modernos, asociado a la dificultad de desconectar en la vida contemporánea.','¿Qué necesitarías para realmente desconectar del trabajo, aunque sea por un rato?'],
  escuela:['Escuela / examen de la infancia','Volver a la escuela en sueños, de adulto, suele representar una situación actual donde te sientes evaluado o "puesto a prueba", igual que entonces.','Es muy común en personas que están aprendiendo algo nuevo o enfrentando una evaluación real, sin importar la edad.','¿En qué situación actual te sientes "de vuelta en la escuela", aprendiendo bajo presión?'],
  hospital:['Hospital / enfermedad','Soñar con un hospital o una enfermedad suele reflejar preocupación por la salud propia o de un ser querido, o una sensación más simbólica de que "algo necesita sanar" en tu vida.','No es un presagio: la mente usa la imagen de la enfermedad para señalar cualquier cosa que sientes débil o vulnerable, física o emocionalmente.','¿Qué parte de tu vida sientes que necesita sanar o recibir más cuidado?'],
  guerra:['Guerra / conflicto','Un sueño de guerra o conflicto armado suele representar una tensión importante entre partes de ti mismo, o entre tú y otra persona, que se siente sin resolver.','La intensidad del conflicto soñado suele ser proporcional al nivel real de tensión que sientes en la vida despierta, aunque el tema no tenga nada que ver con guerras literales.','¿Qué conflicto interno o externo sientes que está en su punto más tenso ahora mismo?'],
  ojos:['Ojos','Los ojos simbolizan percepción y verdad: cómo ves una situación, o qué tan dispuesto estás a mirarla de frente. Ojos que no abren bien hablan de algo que evitas ver con claridad.','Soñar con los propios ojos —mirarlos en un espejo, por ejemplo— suele señalar un momento de autoevaluación honesta.','¿Qué situación evitas mirar de frente porque te incomoda lo que podrías ver?'],
  manos:['Manos','Las manos representan tu capacidad de acción: lo que haces, construyes o sostienes. Manos atadas o que no responden hablan de sentirte impedido para actuar como quisieras.','Perder el control de las manos en un sueño suele reflejar una sensación real de falta de agencia sobre una situación importante.','¿En qué área sientes que te faltan "manos libres" para actuar como quieres?'],
  cabeza:['Cabeza','La cabeza simboliza el pensamiento, la identidad y el control racional. Perder la cabeza en un sueño —literal o figurado— habla de sentir que una situación supera tu capacidad de razonarla.','Un dolor de cabeza soñado suele coincidir con una sobrecarga mental real en la vida despierta.','¿Qué decisión sientes que estás "pensando de más" sin llegar a una conclusión?'],
  cabello:['Cabello / pelo','El cabello se asocia con la identidad, la vitalidad y la imagen que proyectas. Perderlo en sueños —aunque sea común y poco dramático en la realidad— suele reflejar miedo a perder atractivo, poder o control.','Cortarse el cabello en un sueño también puede simbolizar un deseo consciente de cambio de identidad o de imagen.','¿Qué parte de tu imagen o identidad sientes que está cambiando ahora mismo?'],
  corazon:['Corazón','El corazón representa el centro emocional y afectivo. Un corazón que duele o se detiene en el sueño suele señalar una herida afectiva real que necesita atención.','Es uno de los símbolos más directos: casi nunca requiere mucha interpretación simbólica adicional sobre qué área de tu vida está tocando.','¿Qué herida afectiva llevas tiempo sin atender del todo?'],
  piernas:['Piernas','Las piernas simbolizan tu capacidad de avanzar y sostenerte. Piernas débiles o que no responden en el sueño reflejan sentirte sin fuerzas para seguir adelante con algo.','Es un símbolo hermano de "correr sin avanzar": ambos hablan de la misma sensación de estancamiento, con distinto matiz.','¿Qué te está quitando fuerzas para seguir avanzando en este momento?'],
  arbol:['Árbol','El árbol representa tu crecimiento personal, tus raíces y tu estabilidad. Un árbol frondoso habla de buena salud vital; uno seco o caído, de una etapa de agotamiento o pérdida.','Las raíces visibles suelen simbolizar tu conexión con la familia o el pasado; las ramas, tus proyectos y aspiraciones futuras.','¿Tus raíces (familia, hábitos, historia) están sosteniendo o limitando tu crecimiento actual?'],
  flor:['Flor','Las flores simbolizan belleza, crecimiento y momentos de plenitud que, como ellas, son también pasajeros. Una flor marchita puede señalar que algo bello está llegando a su fin natural.','El tipo y color de la flor suele añadir matices personales: lo importante es la emoción que te generó verla.','¿Qué momento de belleza o plenitud actual sabes que no va a durar para siempre, y cómo te hace sentir eso?'],
  jardin:['Jardín','El jardín representa tu mundo interior cultivado: lo que has cuidado con esfuerzo. Un jardín descuidado señala partes de ti mismo que llevas tiempo sin atender.','A diferencia del bosque —lo salvaje sin explorar—, el jardín es lo que ya conoces y decides cultivar conscientemente.','¿Qué parte de ti mismo llevas tiempo sin "regar" o cuidar?'],
  nieve:['Nieve','La nieve simboliza una pausa, un silencio o una emoción "congelada" que aún no se ha procesado. También puede representar pureza y un nuevo comienzo cubierto de calma.','Caminar sobre nieve fresca suele señalar el inicio de una etapa todavía sin marcas ni decisiones tomadas.','¿Qué emoción sientes que llevas tiempo "congelada", sin procesar del todo?'],
  arcoiris:['Arcoíris','El arcoíris simboliza esperanza, reconciliación y la promesa de que después de una dificultad llega claridad. Suele aparecer tras periodos de tensión emocional recientes.','Es uno de los pocos símbolos oníricos con una lectura casi unánimemente positiva en todas las tradiciones.','¿Qué dificultad reciente sientes que ya está empezando a aclararse?'],
  viento:['Viento','El viento representa fuerzas externas que no controlas directamente pero que influyen en tu rumbo: cambios, noticias o circunstancias ajenas a tu voluntad.','Un viento fuerte que te empuja suele señalar sentir que las circunstancias están decidiendo por ti.','¿Qué circunstancia externa sientes que está marcando tu rumbo sin que tú lo hayas decidido del todo?'],
  terremoto:['Terremoto','El terremoto simboliza una base que se tambalea: una certeza, relación o situación que creías firme y de pronto se siente inestable.','A diferencia de la tormenta —emoción que se libera—, el terremoto apunta a los cimientos, no al clima emocional pasajero.','¿Qué "base" de tu vida sientes que, de pronto, ya no es tan firme como creías?'],
  isla:['Isla','La isla representa aislamiento, autosuficiencia o la necesidad de un espacio propio lejos de las exigencias cotidianas. No siempre es negativo: puede reflejar un descanso necesario.','Sentirte atrapado en la isla versus sentirte a salvo en ella cambia por completo la lectura: la diferencia es si elegiste estar ahí o no.','¿Necesitas más espacio propio, o te sientes más aislado de lo que te gustaría?'],
  desierto:['Desierto','El desierto simboliza una etapa de escasez emocional o de sentirte solo en un proceso largo, sin apoyo visible cerca. También puede hablar de claridad extrema, sin distracciones.','Encontrar agua o vida en medio del desierto soñado suele señalar que una ayuda o alivio está más cerca de lo que sientes.','¿En qué proceso actual sientes que te falta compañía o apoyo cercano?'],
  cueva:['Cueva','La cueva representa el inconsciente, lo oculto o una parte de ti mismo que mantienes resguardada del mundo exterior. Entrar en ella suele señalar disposición a explorar algo íntimo.','Es un símbolo clásico de introspección: lo que encuentras dentro de la cueva suele ser justo lo que tu mente está lista para mirar.','¿Qué parte íntima de ti mismo estás empezando a estar listo para explorar?'],
  telefono:['Teléfono','El teléfono simboliza comunicación pendiente: algo que necesitas decir, o un mensaje que esperas recibir. Un teléfono que no funciona bien refleja una comunicación que se siente bloqueada.','Es uno de los símbolos que más rápido cambia con la tecnología; hoy suele representar también la ansiedad de estar siempre disponible.','¿Qué conversación pendiente necesitas tener, y con quién?'],
  carta:['Carta / correo','Recibir una carta en sueños representa un mensaje importante —a veces de tu propio inconsciente— que está buscando tu atención. No abrirla puede señalar evitar una noticia o verdad.','El contenido de la carta, si lo recuerdas, suele ser una de las pistas más directas de todo el sueño.','¿Qué "mensaje" sientes que estás evitando abrir en tu vida?'],
  libro:['Libro','Un libro simboliza conocimiento, una historia personal en curso o lecciones que estás integrando. Un libro en blanco habla de posibilidades aún no escritas; uno cerrado, de algo que das por terminado.','Leer un libro antiguo en sueños suele conectar con sabiduría heredada o aprendizajes del pasado que vuelven a ser relevantes.','¿Qué "capítulo" de tu vida sientes que estás escribiendo ahora mismo?'],
  arma:['Arma / pistola','Un arma en sueños rara vez habla de violencia literal: suele representar poder, defensa o una amenaza que sientes necesitas enfrentar. Sostenerla habla de sentirte capaz de protegerte; verla en otros, de sentirte vulnerable.','El contexto decide todo: una pistola guardada es defensa latente; una apuntándote es una amenaza que sientes real en tu vida despierta.','¿Frente a qué situación sientes que necesitas más capacidad de defenderte?'],
  cuchillo:['Cuchillo','El cuchillo simboliza una separación necesaria —cortar con algo— o una herida que sientes causada por palabras, propias o ajenas ("cortante").','Cortar algo con intención (comida, una cuerda) suele ser positivo: representa decidirte a terminar algo que ya no sirve.','¿Qué necesitas "cortar" de tu vida para sentirte mejor?'],
  barco:['Barco','El barco representa cómo navegas tus emociones y los cambios de la vida: un barco firme en aguas tranquilas habla de estabilidad; uno a la deriva, de sentirte sin rumbo claro.','A diferencia de nadar —tu propio esfuerzo—, el barco simboliza también los recursos y apoyos con los que cuentas para atravesar lo emocional.','¿Sientes que tienes suficientes "recursos" para navegar lo que estás viviendo?'],
  puente:['Puente','El puente simboliza una transición entre dos etapas de tu vida. Cruzarlo con facilidad habla de una transición que fluye; uno roto o inestable, de miedo a dar ese paso.','Es un símbolo muy ligado a decisiones de cambio de vida: mudanzas, nuevas relaciones o cierres de etapa.','¿Qué transición estás por cruzar, y qué tan firme sientes el terreno bajo tus pies?'],
  ascensor:['Ascensor / elevador','El ascensor representa cambios rápidos de estatus emocional o de circunstancias: subir habla de progreso acelerado; bajar, de una caída en el ánimo o las circunstancias. Quedarse atrapado habla de sentirte estancado sin poder avanzar ni retroceder.','A diferencia de la escalera —esfuerzo gradual—, el ascensor simboliza cambios que sientes que no dependen solo de tu esfuerzo.','¿Sientes que un cambio reciente en tu vida fue demasiado rápido para procesarlo del todo?'],
  coche:['Coche / auto','El coche representa tu manejo personal de la vida diaria: quién conduce (tú u otra persona) indica quién sientes que tiene el control real de tu rumbo actual.','Un coche sin frenos es uno de los símbolos de ansiedad más comunes: refleja sentir que una situación avanza más rápido de lo que puedes manejar.','¿Sientes que tú estás "al volante" de tu vida ahora mismo, o que alguien más decide por ti?'],
  bicicleta:['Bicicleta','La bicicleta simboliza equilibrio y avance con esfuerzo propio, sin depender de otros. Pedalear con facilidad habla de buen manejo personal; perder el equilibrio, de sentirte inestable en algo que haces solo.','Es un símbolo que aparece con frecuencia en etapas de mayor independencia o autosuficiencia recién adquirida.','¿En qué área reciente estás aprendiendo a sostenerte con tus propios medios?'],
  anciano:['Anciano / figura sabia','Una figura anciana en sueños suele representar sabiduría, experiencia o una parte de ti que ya conoce la respuesta a algo que conscientemente todavía dudas.','En la tradición junguiana es un arquetipo central: el "viejo sabio" aparece justo cuando el soñante necesita una guía interna más que externa.','Si esa figura pudiera darte un consejo directo, ¿cuál crees que sería?'],
  extraño:['Desconocido / extraño','Una persona desconocida en un sueño suele representar una parte de ti mismo que aún no reconoces del todo: una cualidad, un deseo o un miedo sin rostro todavía.','La actitud de ese desconocido —amistosa u hostil— suele reflejar cómo te sientes frente a esa parte propia todavía no integrada.','Si esa persona desconocida fuera una parte de ti, ¿qué cualidad tuya podría representar?'],
  policia:['Policía / autoridad','La policía en sueños representa reglas, límites o tu propia conciencia moral evaluando si estás actuando "correctamente" en algo. Ser perseguido por la policía suele hablar de culpa, no necesariamente de haber hecho algo malo.','También puede representar protección cuando el sueño es de buscar ayuda policial, en lugar de huir de ella.','¿Sientes culpa por algo que, en el fondo, sabes que no fue realmente tu responsabilidad?'],
  medico:['Médico / doctor','Un médico en sueños simboliza la necesidad de cuidado, diagnóstico o respuestas claras sobre algo que te preocupa, física o emocionalmente.','Suele aparecer cuando una preocupación de salud —propia o cercana— no ha sido del todo resuelta o hablada en la vida despierta.','¿Qué preocupación de salud o bienestar no has terminado de resolver o consultar?'],
  multitud:['Multitud','Una multitud representa la presión social: lo que sientes que se espera de ti frente a los demás. Sentirte perdido entre ella habla de sentir que pierdes tu identidad en lo colectivo.','Sentirte cómodo en la multitud, en cambio, puede señalar una pertenencia sana a un grupo o comunidad.','¿Sientes que te pierdes un poco de ti mismo cuando estás rodeado de muchas expectativas externas?'],
  iglesia:['Iglesia / templo','Un templo representa tu sistema de valores, fe o búsqueda de sentido, tengas o no una práctica religiosa activa. Sentirte en paz allí habla de alineación con tus valores; sentirte incómodo, de un conflicto de conciencia.','Es un símbolo que aparece con frecuencia en momentos de decisiones éticas importantes.','¿Hay alguna decisión reciente que sientes en conflicto con tus propios valores?'],
  cementerio:['Cementerio','El cementerio representa cierre, duelo o el peso del pasado. No es un símbolo de muerte literal, sino del espacio que le das —o te falta dar— a procesos de duelo o despedida.','Visitar una tumba específica en sueños suele señalar un duelo puntual que aún no se ha cerrado del todo.','¿Hay alguna despedida o pérdida que sientes que no has terminado de procesar?'],
  playa:['Playa','La playa representa el encuentro entre lo consciente (la tierra) y lo emocional (el mar): un lugar de descanso y reflexión entre dos mundos. Suele aparecer en momentos de necesitar una pausa.','A diferencia de estar en el mar, la playa es un lugar seguro desde el cual observar las propias emociones sin estar sumergido en ellas.','¿Necesitas un espacio de pausa antes de seguir procesando algo emocional?'],
  laberinto:['Laberinto','El laberinto simboliza sentirte confundido frente a una decisión con muchas variables, sin ver con claridad la salida. No implica que no haya salida, sino que aún no la identificas.','A diferencia de perderse en un bosque —lo desconocido interior—, el laberinto suele representar una situación externa compleja y con reglas que no terminas de entender.','¿Qué decisión sientes que tiene demasiadas variables como para ver con claridad el siguiente paso?'],
  aguila:['Águila','El águila simboliza visión de conjunto, ambición y una perspectiva elevada sobre una situación. Verla volar alto habla de claridad sobre tus metas; herida, de una ambición frenada.','Es, junto al halcón, uno de los símbolos más asociados con la claridad mental y la toma de decisiones importantes desde la distancia.','¿Qué decisión mejoraría si la miraras con más distancia, como desde arriba?'],
  buho:['Búho / lechuza','El búho representa sabiduría, intuición nocturna y la capacidad de ver lo que otros no notan, incluso en la oscuridad o la incertidumbre.','En algunas tradiciones también se asocia con mensajes o advertencias, no por peligro sino por su capacidad de percibir antes que los demás.','¿Qué percibes tú, intuitivamente, que otros a tu alrededor todavía no notan?'],
  cisne:['Cisne','El cisne simboliza transformación elegante, autoestima y belleza que se ha ganado con el tiempo —como en la fábula del patito feo. Suele aparecer en etapas donde una persona empieza a reconocer su propio valor.','A diferencia de la mariposa —cambio completado—, el cisne suele representar también la gracia con la que se atraviesa el cambio.','¿Qué cualidad tuya has empezado a valorar más, después de un periodo de dudar de ella?'],
  cocodrilo:['Cocodrilo','El cocodrilo representa un peligro oculto o una emoción —a menudo ira o resentimiento— que permanece "bajo la superficie" hasta que decide actuar de forma repentina.','A diferencia del tiburón, que es frío y distante, el cocodrilo suele simbolizar algo más cercano: una persona o emoción que parece tranquila hasta que no lo es.','¿Hay alguna emoción tuya que mantienes "bajo la superficie" hasta que de pronto se desborda?'],
  tortuga:['Tortuga','La tortuga simboliza paciencia, protección propia y un ritmo propio que no se deja apurar por el entorno. También puede señalar la necesidad de "retraerte" un poco para protegerte.','Es uno de los pocos símbolos animales con una lectura casi siempre positiva, ligada a la sabiduría de ir despacio cuando hace falta.','¿Qué parte de tu vida mejoraría si le permitieras ir más despacio?'],
  ciervo:['Ciervo / venado','El ciervo representa gracia, sensibilidad y una cualidad que se percibe fácil de herir o asustar. También se asocia con la intuición para detectar peligro antes de que sea evidente.','Verlo huir suele reflejar una sensibilidad que sientes amenazada en un entorno que percibes poco seguro.','¿En qué espacio sientes que necesitas más seguridad para mostrar tu lado más sensible?'],
  vaca:['Vaca','La vaca simboliza abundancia tranquila, nutrición y un cuidado maternal constante, sin prisa. Suele aparecer en periodos donde el sustento diario —material o emocional— está presente en tus pensamientos.','En muchas tradiciones agrícolas es también símbolo de prosperidad sostenida, no de riqueza repentina.','¿Sientes que tus necesidades básicas de cuidado están bien sostenidas ahora mismo?'],
  oveja:['Oveja','La oveja representa pertenencia a un grupo y, en ocasiones, la sensación de seguir patrones sin cuestionarlos del todo ("seguir al rebaño"). También puede hablar de inocencia y necesidad de guía.','Verte como pastor en vez de oveja en el sueño puede señalar que estás asumiendo un rol de guía para otros en este momento.','¿Hay alguna decisión que estás tomando solo porque "así lo hacen todos"?'],
  murcielago:['Murciélago','El murciélago simboliza percepción en medio de la confusión: se mueve con seguridad incluso sin ver con claridad, guiándose por otros sentidos. También puede representar miedos poco racionales.','Es un símbolo ambivalente: para algunas tradiciones es mala suerte, para otras representa una intuición que funciona incluso sin información completa.','¿En qué situación confusa estás confiando más en tu instinto que en la información que tienes?'],
  abeja:['Abeja','La abeja representa trabajo colectivo, productividad y la sensación de formar parte de algo más grande que uno mismo. También puede señalar sentirte "picado" por un comentario o situación reciente.','Un panal lleno de abejas suele aparecer en periodos de mucha actividad social o laboral simultánea.','¿Sientes que estás dando mucho a un esfuerzo colectivo sin suficiente reconocimiento individual?'],
  hormiga:['Hormiga','La hormiga simboliza esfuerzo constante, organización y paciencia frente a metas grandes que se logran de a poco. Un hormiguero puede señalar una sensación de estar rodeado de muchas pequeñas tareas a la vez.','A diferencia de otros insectos más inquietantes en sueños, la hormiga suele tener una lectura neutra o positiva ligada al trabajo sostenido.','¿Qué meta grande estás logrando de a poco, aunque no lo notes día a día?'],
  mosca:['Mosca','La mosca representa una molestia persistente: algo pequeño que, por su insistencia, termina generando más frustración de la que su tamaño real justificaría.','Suele aparecer cuando hay un detalle menor —un comentario, una tarea pendiente— que no deja de "zumbar" en tu cabeza.','¿Qué "mosca" pequeña llevas días sin poder sacarte de la cabeza?'],
  rana:['Rana','La rana simboliza transformación por etapas —como su metamorfosis— y la capacidad de moverte entre dos mundos (agua y tierra, es decir, lo emocional y lo consciente).','En muchas tradiciones también representa una limpieza o renovación después de un periodo de incomodidad.','¿En qué etapa de transformación sientes que te encuentras, ni del todo en un lado ni en el otro?'],
  miel:['Miel','La miel simboliza dulzura ganada con esfuerzo, recompensa y placer merecido. A diferencia de otros símbolos de abundancia, suele asociarse con un disfrute que se obtuvo trabajando con paciencia.','También puede representar palabras dulces —sinceras o no— dirigidas hacia ti recientemente.','¿Qué recompensa sientes que por fin te has ganado, aunque aún no te la hayas permitido disfrutar?'],
  pan:['Pan','El pan representa sustento básico: lo esencial para sentirte seguro día a día, más allá de los lujos o excesos. Compartir pan en un sueño suele simbolizar comunidad y apoyo mutuo.','Es uno de los símbolos de abundancia más "humildes": rara vez habla de riqueza, sino de que lo fundamental esté cubierto.','¿Sientes que tienes cubierto lo esencial, aunque no tengas todo lo que quisieras?'],
  vino:['Vino / alcohol','El vino simboliza celebración, pero también la necesidad de "soltar el control" de forma consciente. El exceso en el sueño puede reflejar una necesidad real de descanso de la exigencia personal.','El contexto —celebración con otros o consumo solitario— cambia bastante la lectura entre disfrute compartido y una posible fuga emocional.','¿Necesitas soltar el control de forma sana, o sientes que estás evitando algo con esa necesidad de escape?'],
  extraterrestre:['Extraterrestre / alienígena','Un ser extraterrestre simboliza algo completamente ajeno a tu experiencia conocida: una idea, persona o situación que no sabes cómo clasificar todavía.','No suele ser un símbolo de amenaza en sí, sino de desconcierto frente a algo genuinamente nuevo en tu vida.','¿Qué situación reciente se siente tan nueva que todavía no sabes cómo "clasificarla"?'],
  boca:['Boca','La boca representa expresión y también lo que tragas sin decir. Una boca cosida o sin palabras habla de censura propia; una boca que habla con fluidez, de seguridad al expresarte.','Suele acompañar a los sueños de dientes, ambos ligados a la autoimagen al comunicarte.','¿Qué llevas tiempo sin decir en voz alta?'],
  orejas:['Orejas / oídos','Las orejas simbolizan escucha: lo que captas de los demás o lo que temes que se diga de ti. No escuchar bien en el sueño habla de sentirte desconectado de lo que ocurre a tu alrededor.','También puede reflejar el deseo de "hacer oídos sordos" a un comentario que te afecta.','¿Hay algo que prefieres no escuchar porque sabes que te dolería?'],
  espalda:['Espalda','La espalda representa lo que dejas atrás o lo que cargas sin verlo de frente. Dar la espalda a alguien en el sueño habla de un conflicto no resuelto; sentir algo en la espalda, de una carga que llevas sin procesar del todo.','Un dolor de espalda soñado suele coincidir con una responsabilidad real que sientes pesada.','¿Qué carga sientes que llevas "a tus espaldas" sin mencionarla?'],
  estomago:['Estómago / vientre','El estómago se asocia con lo que "no puedes digerir" emocionalmente: una noticia, una situación o un sentimiento difícil de procesar.','Un dolor de estómago en sueños suele señalar una preocupación que el cuerpo procesa antes que la mente consciente.','¿Qué situación reciente sientes que te "cayó pesado"?'],
  uñas:['Uñas','Las uñas representan defensa y también una ansiedad sutil (como morderlas). Uñas rotas hablan de sentirte desprotegido; uñas largas y cuidadas, de sentirte capaz de defenderte.','Es un símbolo pequeño pero frecuente en sueños de ansiedad cotidiana, no de grandes crisis.','¿En qué situación pequeña sientes que necesitas defenderte un poco más?'],
  sangrar:['Sangrar (herida)','Una herida que sangra en sueños simboliza una emoción expuesta: algo que te lastimó y que todavía no ha cicatrizado del todo.','A diferencia de la sangre como símbolo general, una herida específica suele señalar el origen concreto del dolor, no solo el agotamiento.','¿Qué herida emocional reciente sientes que sigue abierta?'],
  embarazada:['Estar embarazada (propio)','Verte a ti misma embarazada simboliza un proyecto personal en desarrollo, no necesariamente relacionado con la maternidad real.','La actitud frente al embarazo en el sueño —ilusión o temor— suele reflejar cómo te sientes frente a ese proyecto en tu vida despierta.','¿Qué "proyecto" tuyo está en una etapa temprana, todavía sin mostrarse al mundo?'],
  parto:['Parto / dar a luz','Dar a luz en un sueño simboliza el nacimiento de algo nuevo: una idea, una etapa o una versión de ti mismo que por fin está lista para manifestarse.','Un parto difícil en el sueño puede reflejar el esfuerzo real que te está costando concretar algo importante.','¿Qué "nace" en tu vida después de un proceso que sientes que valió la pena?'],
  gemelos:['Gemelos / mellizos','Los gemelos representan dualidad: dos caminos, decisiones o aspectos de ti mismo que conviven y a veces compiten entre sí.','También puede simbolizar un vínculo de espejo con alguien cercano que sientes muy parecido a ti.','¿Qué dos caminos sientes que conviven dentro de ti ahora mismo?'],
  abuelo:['Abuelo / abuela','Una figura de abuelos en sueños suele representar sabiduría familiar, raíces o un consejo que necesitas, incluso si ya no están físicamente presentes.','Es un símbolo que aparece con frecuencia en momentos donde se necesita perspectiva de largo plazo sobre una decisión.','¿Qué consejo crees que te daría esa figura si pudiera hablarte ahora?'],
  hermano:['Hermano / hermana','Un hermano en sueños suele representar comparación, rivalidad sana o un vínculo de lealtad incondicional, dependiendo del tono del sueño.','Cuando no tienes hermanos reales, esta figura puede simbolizar una parte de ti con la que compites internamente.','¿Con quién sientes que te comparas más seguido, para bien o para mal?'],
  padre:['Padre','La figura paterna simboliza autoridad, estructura y protección. Un conflicto con el padre en sueños suele reflejar tu relación actual con las reglas o la autoridad en general, no solo con esa persona.','Es uno de los arquetipos centrales en la psicología del sueño: representa el orden y los límites que aprendiste de niño.','¿Qué regla o límite de tu infancia sigues cuestionando hoy, para bien o para mal?'],
  madre:['Madre','La figura materna representa cuidado, origen y la base emocional desde la que te relacionas con el mundo. Buscarla en un sueño sin encontrarla habla de necesitar más contención en este momento.','Jung la consideró uno de los arquetipos más poderosos: va más allá de la persona real y simboliza el cuidado incondicional en sí mismo.','¿Qué tipo de cuidado necesitas recibir —de otros o de ti mismo— ahora mismo?'],
  hijo:['Hijo / hija','Soñar con un hijo (propio o imaginado) representa una parte tuya en crecimiento: un proyecto, una responsabilidad nueva o una versión futura de ti mismo que estás formando.','Incluso sin tener hijos reales, este símbolo aparece ligado a lo que sientes que debes "criar" con paciencia en tu vida.','¿Qué parte de tu vida estás "criando" con paciencia ahora mismo?'],
  rey:['Rey / reina','Una figura de rey o reina representa autoridad personal, soberanía sobre tu propia vida o, en otros casos, una autoridad externa que sientes desproporcionada.','Verte a ti mismo coronado suele señalar una etapa de reconocimiento o logro que sientes merecido.','¿En qué área de tu vida sientes que por fin tienes el control que buscabas?'],
  soldado:['Soldado','Un soldado simboliza disciplina, deber y, a veces, el costo personal de cumplir una obligación que no siempre elegiste del todo.','También puede representar una parte de ti que se siente en "modo defensa" permanente frente a la vida.','¿En qué área sientes que llevas demasiado tiempo en "modo defensa"?'],
  payaso:['Payaso','El payaso representa la máscara que usamos para ocultar una emoción real detrás del humor. Un payaso inquietante en sueños suele señalar que algo "no cuadra" detrás de una apariencia alegre.','Puede reflejar tu propia tendencia a usar el humor para evitar mostrar vulnerabilidad.','¿Hay alguna emoción real que escondes detrás de bromas o una actitud ligera?'],
  bruja:['Bruja / hechicero','Una bruja simboliza poder transformador, sabiduría oculta o, en su versión más temida, manipulación que sientes fuera de tu control.','Depende mucho del tono: una bruja sabia habla de poder personal; una amenazante, de sentirte manipulado por alguien o algo.','¿Sientes que tienes el poder de transformar tu situación, o que alguien más decide por ti?'],
  vampiro:['Vampiro','El vampiro representa algo o alguien que sientes que "drena" tu energía: una relación, una obligación o un hábito que te deja agotado.','A diferencia del fantasma (pasado sin resolver), el vampiro suele representar un drenaje activo y presente.','¿Qué relación o actividad sientes que te deja sin energía después de cada encuentro?'],
  zombi:['Zombi','Un zombi simboliza sentirte desconectado de tus emociones, actuando en "piloto automático" sin verdadera vitalidad en lo que haces.','Suele aparecer en periodos de agotamiento extremo, cuando el cuerpo cumple funciones pero la mente se siente ausente.','¿En qué parte de tu rutina sientes que estás funcionando sin estar realmente presente?'],
  angel:['Ángel','Un ángel representa protección, guía o un mensaje de consuelo en un momento de necesidad. Suele aparecer en sueños durante periodos de duda importante o duelo.','A diferencia de otras figuras de autoridad, el ángel no impone: acompaña, lo cual suele reflejar una necesidad de sentirte cuidado sin exigencias.','¿Qué tipo de apoyo —sin exigencias— sientes que necesitas ahora mismo?'],
  demonio:['Demonio / diablo','Un demonio simboliza un impulso, deseo o emoción que consideras inaceptable en ti mismo y que por eso aparece como una figura externa amenazante.','En la lectura junguiana representa la "sombra": lo que rechazamos de nosotros mismos y por eso proyectamos como ajeno.','¿Qué impulso o deseo tuyo te cuesta aceptar como parte legítima de ti?'],
  sirena:['Sirena','La sirena representa la atracción hacia algo emocionalmente intenso que, al mismo tiempo, puede ser peligroso o engañoso si te dejas llevar sin cuidado.','También puede simbolizar una parte tuya que vive entre dos mundos: lo racional (tierra) y lo profundamente emocional (mar).','¿Hay algo que te atrae fuertemente pero que, en el fondo, sabes que conviene mirar con cautela?'],
  dragon:['Dragón','El dragón simboliza un poder enorme, ya sea una amenaza que sientes desproporcionada o una fuerza interna todavía sin domar del todo.','En la tradición oriental es un símbolo de buena fortuna; en la occidental, de un reto que debe enfrentarse con valentía.','¿Qué poder tuyo —propio o ajeno— sientes que todavía no termina de "domarse"?'],
  unicornio:['Unicornio','El unicornio representa pureza, un ideal poco común y a veces la sensación de perseguir algo hermoso pero difícil de alcanzar.','Suele aparecer en sueños ligados a esperanzas muy personales que no siempre se comparten con los demás.','¿Qué ideal persigues que sientes que pocos a tu alrededor entienden del todo?'],
  oceano:['Océano','El océano, más vasto incluso que el mar, representa el inconsciente colectivo o emociones tan profundas que escapan a cualquier intento de control individual.','Suele aparecer en momentos de grandes preguntas existenciales, no en conflictos cotidianos puntuales.','¿Qué pregunta "más grande que tú" ha estado rondando tu mente últimamente?'],
  rio:['Río','El río simboliza el fluir de la vida: el paso del tiempo y de las emociones en movimiento constante, a diferencia del mar o el lago, que son más estáticos.','Nadar a favor o en contra de la corriente suele reflejar si sientes que vas en sintonía con el ritmo de tu vida o luchando contra él.','¿Sientes que vas a favor o en contra de la corriente de tu vida actual?'],
  lago:['Lago','El lago representa calma emocional contenida: a diferencia del mar, sus límites son claros, lo que habla de emociones que sí puedes abarcar y comprender.','Un lago en calma suele reflejar estabilidad emocional actual; uno agitado, una calma que empieza a tambalearse.','¿Qué tan en calma sientes, hoy, tu mundo emocional?'],
  cascada:['Cascada','La cascada simboliza una liberación emocional repentina después de haber contenido algo por un tiempo: energía que finalmente encuentra salida.','A diferencia de la tormenta —caótica—, la cascada suele representar una liberación con dirección clara, no destructiva.','¿Qué emoción contenida sientes que finalmente está encontrando una salida sana?'],
  lluvia:['Lluvia','La lluvia simboliza limpieza emocional y, en muchos casos, alivio después de un periodo de tensión acumulada. Una lluvia suave es sanadora; una tormenta de lluvia, más intensa emocionalmente.','También puede representar tristeza que necesita expresarse, especialmente si el sueño incluía llanto.','¿Qué necesitas "soltar" para sentir ese mismo alivio en tu vida despierta?'],
  niebla:['Niebla','La niebla representa confusión temporal: no ver con claridad una situación, aunque la solución probablemente esté más cerca de lo que percibes.','A diferencia de la oscuridad —lo desconocido en general—, la niebla sugiere que la claridad está a punto de volver, solo que todavía no del todo.','¿Qué decisión sientes que pronto se aclarará, aunque ahora se vea confusa?'],
  hielo:['Hielo','El hielo simboliza emociones congeladas o una situación que se ha enfriado —una relación, un proyecto— y que necesita calor o atención para volver a fluir.','Caminar sobre hielo resbaladizo también puede representar inestabilidad en un terreno que sentías seguro.','¿Qué parte de tu vida sientes que se ha "enfriado" y merece más atención?'],
  rayo:['Rayo (relámpago)','El rayo simboliza una revelación súbita: una idea, verdad o decisión que llega de golpe, con claridad repentina pero también con intensidad.','A diferencia de la luz constante del sol, el rayo representa comprensión instantánea, no gradual.','¿Qué verdad se te reveló de golpe recientemente?'],
  eclipse:['Eclipse','Un eclipse simboliza un periodo donde algo que normalmente te da claridad (razón o intuición, según sea solar o lunar) queda temporalmente oculto.','Suele señalar una etapa de confusión pasajera que, como el fenómeno real, tiene un tiempo limitado.','¿Qué parte de tu claridad habitual sientes que está temporalmente "eclipsada"?'],
  cometa:['Cometa (astro)','Un cometa representa un evento o persona que aparece de forma inesperada y deja una marca memorable, aunque su paso sea breve.','Suele reflejar la sensación de que algo importante está ocurriendo, aunque todavía no sepas bien qué significa a largo plazo.','¿Qué evento reciente sientes que dejó una marca, aunque haya sido breve?'],
  nube:['Nube','Las nubes representan pensamientos o emociones que flotan sin asentarse del todo: ideas en proceso, no decisiones tomadas.','Nubes oscuras suelen anunciar una preocupación próxima a manifestarse; nubes claras, pensamientos livianos en curso.','¿Qué pensamiento sientes que todavía está "flotando" sin aterrizar en una decisión?'],
  cielo:['Cielo','El cielo representa tus aspiraciones y tu sentido de posibilidad. Un cielo despejado habla de optimismo disponible; uno encapotado, de limitaciones percibidas sobre lo que crees posible.','Mirar hacia el cielo en sueños suele coincidir con momentos donde te estás permitiendo soñar más en grande.','¿Qué te estás permitiendo soñar en grande últimamente?'],
  volcanerupcion:['Erupción volcánica','Ver un volcán en plena erupción (no solo presente, sino activo) representa que una emoción contenida ya está saliendo, para bien o para mal, y ya no hay forma de detenerla.','A diferencia del volcán en reposo —contención—, la erupción activa señala que el proceso de liberación ya comenzó.','¿Qué emoción sientes que ya "hizo erupción" y ahora toca manejar sus consecuencias?'],
  tesoro:['Tesoro','Encontrar un tesoro simboliza descubrir un recurso interno, talento o posibilidad que no sabías que tenías disponible.','A diferencia del dinero encontrado (recurso inmediato), el tesoro suele representar algo de mayor valor simbólico y duradero.','¿Qué talento o recurso propio sientes que recién estás empezando a descubrir?'],
  mapa:['Mapa','Un mapa representa la necesidad de orientación clara frente a una decisión o etapa de vida. Un mapa confuso o ilegible habla de sentirte sin un plan claro por ahora.','Encontrar un mapa inesperado en un sueño suele coincidir con el deseo consciente de tener más claridad sobre el siguiente paso.','¿En qué área de tu vida sientes que más necesitas un "mapa" claro ahora mismo?'],
  espada:['Espada','La espada simboliza decisión, claridad de juicio y la capacidad de "cortar" con precisión una situación, a diferencia del cuchillo, más cotidiano.','Sostener una espada con firmeza suele señalar sentirte preparado para defender una postura importante.','¿Qué postura sientes que estás, por fin, lista o listo para defender con firmeza?'],
  escudo:['Escudo','El escudo representa protección activa frente a una amenaza percibida, más defensiva que agresiva, a diferencia del arma.','Un escudo roto o débil en el sueño puede señalar sentir que tus defensas emocionales habituales no están siendo suficientes.','¿Sientes que tus defensas habituales están funcionando bien frente a lo que estás viviendo?'],
  corona:['Corona','La corona simboliza reconocimiento, logro o la asunción de una responsabilidad importante que conlleva también una carga de expectativas.','Una corona que pesa o incomoda en el sueño suele reflejar el costo emocional de un logro o rol que otros valoran mucho.','¿Qué reconocimiento reciente sientes que trae también una carga que no esperabas?'],
  anillo:['Anillo','El anillo representa compromiso, un ciclo cerrado (su forma circular) o un vínculo que sientes definitivo. Perder un anillo habla de temor a romper ese compromiso.','En sueños de boda o compromiso, el anillo suele ser el símbolo central sobre el que se construye toda la lectura.','¿Qué compromiso sientes que define una parte importante de quién eres ahora?'],
  vestido:['Vestido / ropa elegante','Un vestido o ropa elegante representa cómo quieres ser percibido en una situación importante. No encontrar el vestido adecuado habla de sentirte "no preparado" para la ocasión.','También puede reflejar inseguridad sobre cómo te perciben los demás en un evento social próximo.','¿Hay alguna situación social próxima donde sientes que no estás del todo preparado para mostrarte?'],
  ropainterior:['Ropa interior (exposición)','Mostrar ropa interior sin querer en sueños combina el símbolo de la desnudez con algo más específico: sentir expuesta una parte íntima que preferías guardar solo para ti.','Suele intensificarse cuando compartiste algo personal recientemente y temes el juicio ajeno.','¿Compartiste algo privado recientemente que ahora temes que se use en tu contra?'],
  zapatos:['Zapatos','Los zapatos representan tu forma de "caminar" por la vida: tu enfoque, tus decisiones de rumbo. Zapatos que no calzan bien hablan de sentirte en un rol o camino que no te queda del todo.','Perder un zapato suele simbolizar sentirte desequilibrado en algo que normalmente dominas con facilidad.','¿Sientes que el "camino" o rol actual te queda bien, o te aprieta en algún punto?'],
  maleta:['Maleta / equipaje','La maleta representa lo que cargas contigo emocionalmente de una etapa a otra: recuerdos, responsabilidades o expectativas. Una maleta demasiado pesada habla de cargar más de lo necesario.','Hacer la maleta en un sueño suele coincidir con una transición próxima, real o emocional.','¿Qué "peso" innecesario podrías dejar atrás antes de tu próxima etapa?'],
  caja:['Caja','Una caja cerrada representa algo guardado, a veces deliberadamente, que todavía no estás listo para abrir o mostrar.','Abrir una caja sorpresa en el sueño suele reflejar curiosidad o ansiedad frente a algo que está por revelarse en tu vida.','¿Qué tienes "guardado en una caja" que sientes que pronto tendrás que abrir?'],
  regalo:['Regalo','Recibir un regalo en sueños simboliza una oportunidad, reconocimiento o apoyo que está llegando a tu vida, a veces desde donde menos lo esperas.','Dar un regalo, en cambio, suele reflejar el deseo de mostrar aprecio a alguien de forma más abierta en la vida despierta.','¿A quién te gustaría mostrarle más abiertamente tu aprecio?'],
  globo:['Globo (aerostático o de fiesta)','Un globo representa ligereza, celebración o el deseo de "elevarte" por encima de un problema cotidiano. Un globo que se poncha habla de una ilusión que se desinfla.','También puede simbolizar un entusiasmo que sientes frágil, fácil de romper con un comentario o un contratiempo menor.','¿Qué ilusión reciente sientes que es frágil y fácil de "ponchar"?'],
  musica:['Música','La música en sueños representa armonía emocional, o su ausencia si el sueño incluía ruido desagradable en vez de melodía. Una canción específica que recuerdas suele traer una pista emocional directa.','Bailar al ritmo de esa música suele reflejar qué tan en sintonía te sientes con tu momento actual.','Si la escena de tu sueño tuviera una canción de fondo, ¿cuál sería y qué te dice eso?'],
  baile:['Bailar','Bailar en sueños representa fluidez emocional y la capacidad de "moverte" con gracia frente a una situación, incluso si es compleja.','Bailar incómodo o fuera de ritmo puede señalar sentirte desalineado con las expectativas de una situación social.','¿En qué situación sientes que, por fin, te estás moviendo con más soltura?'],
  canto:['Cantar','Cantar en un sueño representa expresión auténtica de tu voz interior, incluso sin palabras literales de por medio. Cantar con libertad habla de sentirte en paz con lo que expresas al mundo.','No poder cantar, o hacerlo con la voz quebrada, suele reflejar una expresión personal que sientes bloqueada.','¿Qué te gustaría "cantar" (expresar) con más libertad en tu vida?'],
  risa:['Risa (en el sueño)','Reír en sueños, incluso en situaciones extrañas, suele reflejar una capacidad sana de no tomarte tan en serio una dificultad actual.','Una risa que se siente incómoda o fuera de lugar puede señalar nerviosismo disfrazado de ligereza.','¿Hay algo que podrías tomarte un poco menos en serio de lo que lo haces ahora?'],
  cancion:['Grito de auxilio (pedir ayuda)','Pedir ayuda en un sueño y no recibirla refleja una necesidad real de apoyo que sientes que no ha sido escuchada en tu vida despierta.','Recibir ayuda inesperada en el sueño, en cambio, puede señalar que un apoyo real está más cerca de lo que crees.','¿A quién podrías pedirle ayuda directamente, en lugar de esperar que la noten solos?'],
  incendio:['Incendio (casa u objeto)','Un incendio que destruye algo específico (una casa, un objeto) simboliza una pérdida percibida de seguridad o identidad relacionada con eso que se quema.','A diferencia del fuego controlado —energía—, el incendio descontrolado habla de un cambio que se siente destructivo, aunque después pueda abrir algo nuevo.','¿Qué sientes que se está "quemando" en tu vida, y qué podría nacer después de esa pérdida?'],
  inundacion:['Inundación','Una inundación representa emociones que se desbordan y afectan áreas de tu vida que normalmente sentías secas o bajo control.','A diferencia del mar embravecido —emoción general—, la inundación invade espacios cotidianos: tu casa, tu trabajo, tu rutina.','¿En qué área cotidiana sientes que tus emociones están "desbordándose" más de lo habitual?'],
  naufragio:['Naufragio','Un naufragio simboliza el colapso de un plan o proyecto en el que habías invertido mucha confianza y recursos.','El tono del sueño —pánico o calma al nadar hacia la orilla— suele reflejar qué tan preparado te sientes para reconstruir después de ese fracaso percibido.','¿Qué plan sientes que no salió como esperabas, y qué aprendiste de todos modos?'],
  secuestro:['Secuestro','Soñar con ser secuestrado simboliza sentir que una parte de tu libertad o tiempo está siendo controlada por otra persona, obligación o circunstancia.','Quién te secuestra en el sueño suele ser la pista más directa sobre qué o quién sientes que limita tu libertad actual.','¿Quién o qué sientes que está limitando tu libertad de decisión ahora mismo?'],
  traicion:['Traición','Soñar que alguien cercano te traiciona rara vez predice una traición real: suele reflejar una inseguridad sobre la solidez de ese vínculo, no necesariamente una verdad oculta.','También puede representar tu propio miedo a decepcionar a alguien, proyectado como si fuera al revés.','¿Hay una relación donde sientes más inseguridad que evidencia real de un problema?'],
  mentira:['Descubrir una mentira','Soñar que descubres que te mintieron suele reflejar una intuición activa que percibe inconsistencias, aunque todavía no tengas pruebas concretas en la vida despierta.','También puede señalar una mentira que te estás contando a ti mismo sobre alguna situación.','¿Hay alguna "mentira" —ajena o propia— que presientes, aunque no la hayas confirmado del todo?'],
  celos:['Celos (en el sueño)','Sentir celos en un sueño suele reflejar una inseguridad sobre tu propio valor en una relación, más que información real sobre la lealtad de la otra persona.','Es un símbolo que vale la pena mirar hacia adentro antes que hacia afuera.','¿Qué necesitarías sentir de ti mismo para que ese miedo pesara menos?'],
  divorcio:['Divorcio / separación','Soñar con un divorcio o ruptura —incluso sin estar en pareja en la vida real— puede simbolizar la separación de una parte de ti mismo que ya no te representa, o el cierre de cualquier tipo de vínculo o etapa.','El alivio o la tristeza que sentías en el sueño es la clave para saber si esa separación simbólica es bienvenida o temida.','¿Qué "parte" de tu vida sientes que está lista para separarse de ti, para bien?'],
  infidelidad:['Infidelidad (propia o ajena)','Soñar con una infidelidad —cometida o sufrida— rara vez es literal: suele reflejar una falta de atención percibida en una relación, no necesariamente una traición real.','También puede simbolizar sentirte atraído por una posibilidad de vida distinta a la actual, sin que eso implique una persona específica.','¿Sientes que te falta atención en algún vínculo importante, más allá de lo romántico?'],
  curacion:['Sanar una herida','Soñar que una herida sana o cicatriza simboliza que un proceso de recuperación emocional real ya está en marcha, aunque de forma gradual.','Es uno de los pocos símbolos de sueño con una lectura casi siempre alentadora.','¿Qué herida sientes que, aunque despacio, ya está empezando a sanar?'],
  risadeotro:['Burla / ser objeto de burla','Que se rían de ti en un sueño refleja un miedo activo al juicio social o a no encajar en un grupo importante para ti.','Suele intensificarse después de situaciones reales donde te sentiste expuesto o evaluado frente a otros.','¿En qué contexto social sientes más miedo a no encajar?'],
  abandonar:['Ser abandonado','Soñar que te abandonan —una pareja, un padre, un amigo— refleja un miedo profundo a la soledad o al rechazo, que puede o no estar relacionado con la persona específica del sueño.','Es uno de los temores más universales y antiguos del repertorio emocional humano, documentado en casi todas las culturas.','¿De dónde viene, históricamente, tu miedo a ser abandonado?'],
  rechazo:['Ser rechazado','El rechazo en sueños —una propuesta, una idea, un amor— suele reflejar inseguridad sobre tu propio valor en una situación concreta de tu vida despierta.','La reacción tuya ante el rechazo soñado (tristeza vs. indiferencia) suele mostrar cuánto peso real le das a esa posible situación.','¿Qué tanto miedo al rechazo está frenando una decisión que quieres tomar?'],
  exito:['Lograr algo (éxito)','Soñar con lograr una meta importante refleja confianza creciente y, muchas veces, anticipa el estado emocional de sentirte capaz, más que el resultado literal.','Es un símbolo que suele reforzar motivación real cuando aparece en etapas de esfuerzo sostenido.','¿Qué logro reciente, aunque pequeño, deberías estar celebrando más?'],
  competencia:['Competencia / carrera','Participar en una carrera o competencia simboliza comparación con otros o contigo mismo frente a una meta. Ir en último lugar no siempre es negativo: puede reflejar que vas a tu propio ritmo.','El tipo de competencia (física, intelectual) suele apuntar al área específica de tu vida donde sientes esa presión.','¿Con quién —o contigo mismo— sientes que estás compitiendo más fuerte ahora?'],
  regreso:['Regresar a un lugar del pasado','Volver en sueños a un lugar de tu pasado (una casa antigua, una ciudad de la infancia) representa revisar una etapa o decisión que sigue teniendo peso emocional hoy.','El estado de ese lugar en el sueño —cuidado o deteriorado— suele reflejar cómo recuerdas esa etapa: con cariño o con pérdida.','¿Qué de esa etapa pasada sigue influyendo en cómo vives el presente?'],
  mudanza:['Mudanza','Soñar con una mudanza representa un cambio de identidad o de etapa vital en curso, más allá de un cambio de domicilio literal.','El tono del sueño —ilusión o pérdida— suele reflejar cómo te sientes frente a ese cambio real que estás atravesando.','¿Qué cambio de etapa estás viviendo que se parece a "mudarte" de quién eras antes?'],
  fiesta:['Fiesta / celebración','Una fiesta en sueños simboliza conexión social, celebración de un logro o, si se siente incómoda, presión social que no disfrutas del todo.','Sentirte fuera de lugar en una fiesta soñada suele reflejar una sensación real de no encajar en cierto grupo social.','¿En qué espacio social sientes que no terminas de encajar del todo?'],
  reunion:['Reunión familiar','Una reunión familiar en sueños activa dinámicas y roles antiguos: quién hablaba, quién se quedaba callado, suele reflejar tu lugar real dentro de ese sistema familiar.','Es un símbolo rico en matices personales, más que universales: conviene mirarlo según tu propia historia familiar.','¿Qué rol sientes que siempre terminas ocupando en tu familia, te guste o no?'],
  despedida:['Despedida','Una despedida en sueños, incluso de alguien vivo y presente en tu vida, simboliza el cierre simbólico de una etapa de esa relación, no necesariamente su fin real.','El tono —tristeza o paz— suele reflejar qué tan resuelto sientes ese cierre.','¿Hay una "versión" de alguna relación que ya terminó, aunque la persona siga presente?'],
  reencuentro:['Reencuentro','Un reencuentro en sueños con alguien que no ves hace tiempo suele representar una cualidad de esa relación que tu mente está recuperando o extrañando en este momento.','No siempre implica que debas buscar a esa persona: a veces basta con reconocer qué representaba para ti.','¿Qué cualidad de esa persona sientes que te falta ahora mismo en tu vida?'],
  perderse:['Perderse (sin encontrar el camino)','Sentirte perdido, sin encontrar el camino de regreso, refleja incertidumbre sobre el rumbo general de tu vida, más que sobre una decisión puntual.','A diferencia del laberinto (una situación compleja puntual), perderse sin más habla de una falta de dirección más amplia y de fondo.','¿Hace cuánto no te detienes a pensar hacia dónde quieres ir, en general?'],
  buscar:['Buscar algo sin encontrarlo','Buscar algo en un sueño sin lograr encontrarlo —sin saber bien qué es— refleja una necesidad difusa que todavía no logras nombrar del todo.','Es uno de los símbolos más frustrantes precisamente porque la mente aún no sabe qué es lo que falta.','Si tuvieras que adivinar qué buscabas en el sueño, ¿qué dirías sin pensarlo mucho?'],
  escondite:['Esconderse','Esconderte en un sueño representa evitar una confrontación, exposición o responsabilidad que sientes que no estás listo para enfrentar todavía.','El lugar donde te escondías suele dar pistas: un clóset habla de ocultar una parte de ti; un sótano, de algo más profundo y antiguo.','¿De qué situación te estás "escondiendo" en este momento de tu vida?'],
  trampa:['Caer en una trampa','Caer en una trampa en un sueño simboliza sentirte engañado o atrapado por una situación que no viste venir, o por decisiones pasadas que ahora limitan tus opciones.','También puede reflejar desconfianza hacia una propuesta o persona reciente que no termina de convencerte.','¿Hay alguna situación reciente que sientes que podría ser una "trampa" disfrazada de oportunidad?'],
  rescate:['Ser rescatado','Ser rescatado en un sueño —de un peligro, un accidente— refleja la necesidad real de apoyo y, a la vez, el alivio de saber que ese apoyo puede llegar cuando lo necesitas.','Quién te rescata en el sueño suele ser significativo: puede representar a una persona real o una cualidad propia que te está salvando.','¿Quién o qué cualidad tuya te está "rescatando" en este momento difícil?'],
  salvar:['Salvar a alguien','Soñar que salvas a otra persona de un peligro refleja tu propio instinto protector y, en ocasiones, la responsabilidad que sientes hacia esa persona en la vida real.','Si no logras salvarla a tiempo, el sueño puede reflejar culpa o impotencia frente a algo que escapa a tu control.','¿Sientes una responsabilidad hacia alguien que, en el fondo, no depende solo de ti?'],
  luchar:['Pelear / luchar físicamente','Pelear en un sueño representa un conflicto activo —interno o con otra persona— que ya no se mantiene en silencio, sino que busca resolución directa.','Ganar o perder la pelea soñada suele reflejar qué tan capaz te sientes de sostener tu postura en ese conflicto real.','¿Qué conflicto sientes que ya no puedes seguir evitando en silencio?'],
  ira:['Ira / enojo (en el sueño)','Sentir ira intensa dentro de un sueño, incluso sin motivo claro, suele reflejar frustración acumulada que no has tenido espacio para expresar despierto.','Es más informativo mirar hacia quién o qué se dirigía esa ira que buscarle lógica a la situación del sueño en sí.','¿Hacia quién o qué sientes una frustración que no has expresado todavía?'],
  vergüenza:['Vergüenza','La vergüenza en sueños —hacer el ridículo frente a otros— refleja miedo al juicio social, generalmente más intenso en el sueño que en la situación real que lo originó.','Suele intensificarse después de una situación real donde sentiste, aunque sea levemente, que no estuviste a la altura esperada.','¿Qué situación reciente te hizo sentir, aunque sea un poco, expuesto al juicio de otros?'],
  culpa:['Culpa','Sentir culpa en un sueño por algo que ni siquiera hiciste suele señalar una autoexigencia alta, más que una falta real cometida.','Vale la pena distinguir entre culpa por algo concreto y una culpa general que ya forma parte de tu forma habitual de pensar.','¿Esa culpa corresponde a algo concreto, o es una sensación que cargas casi siempre?'],
  nostalgia:['Nostalgia (en el sueño)','Un sueño con un tono nostálgico marcado —aunque la escena sea neutra— suele señalar que extrañas una etapa, lugar o vínculo más de lo que te permites admitir despierto.','A diferencia de regresar a un lugar del pasado, aquí lo central es la emoción, no la escena específica.','¿Qué extrañas actualmente, aunque no se lo digas a nadie?'],
  alegria:['Alegría intensa (en el sueño)','Un sueño con alegría desbordante, incluso sin razón aparente, suele anticipar que una parte de ti ya sabe que algo bueno está en camino, antes de que lo confirmes conscientemente.','Es uno de los pocos símbolos donde el tono emocional, más que el contenido, lo dice casi todo.','¿Qué podría estar mejorando en tu vida que todavía no te permites celebrar del todo?'],
  computadora:['Computadora / laptop','Una computadora que falla en sueños simboliza sentir que tu forma habitual de organizar o resolver problemas no está funcionando como esperabas.','También puede reflejar sobrecarga de información: demasiados pendientes digitales acumulados.','¿Sientes que tu forma habitual de resolver problemas ya no te está funcionando tan bien?'],
  internet:['Internet / sin señal','Quedarte sin conexión a internet en un sueño refleja miedo a la desconexión social o a perderte de algo importante que ocurre sin ti.','También puede señalar, al revés, un deseo inconsciente de desconectarte un poco de la sobreexposición digital.','¿Necesitas, en el fondo, un poco más de desconexión de la que te permites?'],
  redes:['Redes sociales','Soñar con redes sociales —publicar, recibir comentarios— refleja preocupación por cómo te perciben los demás o por la validación externa en general.','Comentarios negativos en el sueño suelen reflejar un miedo al juicio más amplio, no solo digital.','¿Cuánto peso le das, realmente, a lo que otros opinan de ti?'],
  avion:['Avión','Un avión representa un proyecto o ambición de gran escala. Despegar con éxito habla de confianza en ese proyecto; turbulencia, de miedo a perder el control sobre algo grande que emprendiste.','A diferencia del coche —vida diaria—, el avión simboliza decisiones con mayor impacto o alcance en tu vida.','¿Qué proyecto grande tienes en marcha, y qué tan en control te sientes de él?'],
  barcopesquero:['Equipaje perdido','Perder el equipaje en un aeropuerto soñado simboliza miedo a que, en una transición importante, se te "pierda" algo esencial de ti mismo en el proceso.','Suele intensificarse antes de cambios grandes y reales: mudanzas, nuevos trabajos, viajes importantes.','¿Qué parte de ti temes "perder" en medio de un cambio grande que se aproxima?'],
  aeropuerto:['Aeropuerto','El aeropuerto representa un punto de transición entre dos etapas de vida: ya no estás del todo en un lugar, pero tampoco has llegado al siguiente.','Sentirte perdido en un aeropuerto suele reflejar la incomodidad natural de estar "entre" dos versiones de tu vida.','¿En qué transición "intermedia" sientes que te encuentras ahora mismo?'],
  tren2:['Estación de tren','Una estación de tren simboliza esperar el momento adecuado para avanzar en un plan. Perder el tren varias veces en el mismo sueño puede señalar miedo recurrente a quedarte atrás.','A diferencia del tren en movimiento, la estación representa la espera misma, no el viaje.','¿Qué estás esperando "el momento correcto" para empezar, y qué tan justificada es esa espera?'],
  hotel:['Hotel','Un hotel representa una etapa temporal de tu vida: algo que sabes que no es permanente, aunque por ahora te sostenga.','Un hotel incómodo o extraño en el sueño puede señalar que esa etapa transitoria se siente más larga o incómoda de lo esperado.','¿Qué parte de tu vida actual sientes que es "temporal", aunque lleve más tiempo del planeado?'],
  restaurante:['Restaurante','Un restaurante en sueños representa cómo "te nutres" en lo social: compartir, ser atendido o atender a otros. No encontrar nada en el menú habla de sentir que tus necesidades no están bien representadas en una situación social.','También puede señalar indecisión frente a varias opciones de vida que tienes disponibles.','¿Sientes que tus necesidades reales están bien representadas en tus espacios sociales actuales?'],
  supermercado:['Supermercado / tienda','Un supermercado representa opciones y abastecimiento: lo que sientes que necesitas reunir para sentirte preparado. Pasillos interminables sin encontrar lo que buscas reflejan sobrecarga de decisiones.','Un carrito vacío puede señalar sentir que te faltan recursos; uno muy lleno, sentir que acumulas más de lo necesario.','¿Sientes que tienes demasiadas opciones, o muy pocas, frente a una decisión actual?'],
  banco:['Banco (institución)','Un banco en sueños representa seguridad material y confianza en el sistema que sostiene tu estabilidad. Una fila larga o un banco cerrado habla de sentir trabas para acceder a algo que necesitas.','También puede simbolizar tu relación personal con el ahorro, el control o la falta de control sobre tus recursos.','¿Qué tan segura sientes, hoy, tu estabilidad material?'],
  oficina:['Oficina','La oficina representa tu identidad profesional y cómo te sientes evaluado en ese rol. Una oficina caótica o ajena refleja desconexión con tu trabajo actual.','Encontrar tu oficina cambiada de lugar o distinta suele señalar un cambio de rol o de percepción sobre tu trabajo.','¿Qué tan alineado te sientes, hoy, con tu rol profesional actual?'],
  reunionlaboral:['Junta / reunión de trabajo','Soñar con una reunión laboral tensa refleja presión por desempeño o miedo a no estar a la altura de lo que tu entorno laboral espera de ti.','Llegar sin preparación a esa reunión soñada es una variante directa del símbolo del examen, aplicado al mundo adulto.','¿En qué aspecto de tu trabajo sientes que necesitas sentirte más preparado?'],
  despido:['Ser despedido del trabajo','Soñar que te despiden —incluso en un trabajo donde te sientes seguro— suele reflejar inseguridad general sobre tu valor o desempeño, más que un presagio real.','También puede señalar el deseo, no siempre consciente, de un cambio de rumbo profesional.','¿Es inseguridad, o en el fondo hay un deseo de cambiar de rumbo profesional?'],
  renuncia:['Renunciar al trabajo','Soñar que renuncias a tu trabajo, incluso sin planearlo en la vida real, suele reflejar el deseo de más libertad o de un cambio que todavía no te atreves a considerar en voz alta.','El alivio o el miedo que sentías al renunciar en el sueño es la pista principal sobre qué tan listo estás para ese cambio.','¿Qué cambio profesional te permitirías considerar si el miedo no fuera un factor?'],
  dinero2:['Ganar la lotería','Soñar que ganas la lotería simboliza un deseo de solución rápida frente a una presión económica o de otro tipo que sientes pesada actualmente.','Rara vez trata literalmente de dinero: suele representar el deseo de que "algo" resuelva de golpe una carga que llevas tiempo cargando.','¿Qué carga desearías que se resolviera "de golpe", sin tener que trabajarla paso a paso?'],
  deuda:['Deuda','Soñar con una deuda económica simboliza sentir que le debes algo a alguien —no necesariamente dinero: tiempo, una disculpa, una explicación pendiente.','El monto o la persona a quien le debes en el sueño suele dar pistas directas sobre qué es lo que realmente sientes pendiente.','¿A quién sientes que le "debes" algo que no es dinero?'],
  numero:['Un número específico que se repite','Ver el mismo número repetirse varias veces en un sueño suele reflejar que tu mente está procesando algo relacionado con una fecha, edad o ciclo importante para ti.','No hay un significado universal fijo por número: lo relevante es qué asocias tú personalmente con esa cifra.','¿Qué asocias tú, personalmente, con ese número que se repitió?'],
  amanecer:['Amanecer','El amanecer simboliza un nuevo comienzo, claridad después de un periodo difícil o el inicio de una etapa que se siente prometedora.','Es uno de los símbolos con lectura más consistentemente positiva en casi todas las tradiciones de interpretación.','¿Qué "nuevo comienzo" sientes que se está gestando en tu vida ahora mismo?'],
  atardecer:['Atardecer','El atardecer representa el cierre amable de una etapa: no un final abrupto, sino un proceso de conclusión natural y, muchas veces, hermoso de observar.','A diferencia de la noche o la oscuridad —lo desconocido—, el atardecer es un cierre consciente y sereno.','¿Qué etapa sientes que está cerrando de forma natural, sin necesidad de forzar nada?'],
  medianoche:['Medianoche','La medianoche simboliza un punto de inflexión: el momento más profundo antes de que algo empiece a cambiar de dirección.','En muchas tradiciones se asocia también con decisiones tomadas en soledad, lejos de la influencia de otros.','¿Qué decisión sientes que estás tomando más en soledad que de costumbre?'],
  primavera:['Primavera (estación)','Soñar con la primavera simboliza renovación, crecimiento y el inicio de una etapa fértil después de un periodo más estático.','Es un símbolo estacional que casi siempre acompaña a otros signos de nuevos comienzos en el mismo sueño.','¿Qué área de tu vida sientes que está floreciendo después de un periodo más quieto?'],
  invierno:['Invierno (estación)','El invierno representa un periodo de repliegue, descanso necesario o una etapa emocionalmente más fría, pero no necesariamente negativa.','Al igual que la naturaleza en invierno, puede tratarse de un descanso necesario antes de un nuevo ciclo de crecimiento.','¿Necesitas permitirte un periodo de descanso antes de retomar impulso?'],
  escueladocente:['Maestro / profesor','Un maestro en sueños representa una guía o conocimiento que estás buscando, o una evaluación de tu propio aprendizaje reciente en algún área de vida.','Sentirte intimidado por el maestro suele reflejar inseguridad frente a una habilidad que sientes todavía en desarrollo.','¿Qué habilidad sientes que todavía estás aprendiendo, y te cuesta aceptar que no la dominas aún?'],
  grupo:['Formar parte de un equipo','Soñar con trabajar en equipo, con buena o mala coordinación, refleja cómo te sientes actualmente integrado —o no— dentro de un grupo importante de tu vida.','La calidad de la coordinación en el sueño suele ser un reflejo directo de cómo sientes esa dinámica en la vida real.','¿Te sientes bien integrado en los grupos importantes de tu vida actual?'],
  desafio:['Superar un obstáculo físico','Soñar con superar un obstáculo físico (un muro, un río, una distancia) representa confianza creciente en tu capacidad de resolver un reto real que estás enfrentando.','No lograr superarlo en el sueño, en cambio, puede señalar que necesitas más apoyo o un enfoque distinto frente a ese reto.','¿Qué obstáculo real sientes que estás, poco a poco, logrando superar?'],
  calor:['Calor extremo','Sentir un calor insoportable en un sueño simboliza una presión o tensión emocional que se ha vuelto difícil de sostener por más tiempo.','A diferencia del fuego —energía con forma—, el calor ambiental representa una presión más difusa y constante.','¿Qué presión constante sientes que ya es difícil de sostener?'],
  frio:['Frío extremo','Sentir frío intenso en un sueño simboliza sentirte emocionalmente desatendido o distante de alguien importante en tu vida.','A diferencia del hielo —algo específico congelado—, el frío ambiental habla de una sensación general de desconexión.','¿En qué relación sientes una distancia emocional que te gustaría acortar?'],
  sed:['Tener sed (en el sueño)','Tener mucha sed en un sueño simboliza una necesidad emocional insatisfecha: algo esencial que sientes que te falta y que no has logrado nombrar del todo.','A diferencia del hambre —necesidad más amplia—, la sed suele señalar algo puntual y urgente.','¿Qué necesitas con más urgencia de la que te permites admitir?'],
  hambre:['Tener hambre (en el sueño)','Tener hambre intensa en un sueño representa una necesidad no cubierta, que puede ser afectiva, de reconocimiento o de descanso, más que literalmente alimenticia.','Comer hasta saciarte en el mismo sueño suele reflejar alivio frente a una carencia que empieza a resolverse.','¿Qué necesidad no cubierta sientes que empieza, por fin, a resolverse?'],
  cansancio:['Sentirte exhausto (en el sueño)','Sentirte agotado dentro del propio sueño, sin razón aparente, suele reflejar un cansancio real acumulado que tu cuerpo necesita que reconozcas conscientemente.','Es uno de los mensajes más directos que puede dar un sueño: a veces no simboliza nada más que la necesidad literal de descansar más.','¿Cuánto descanso real te has permitido en la última semana?'],
  embriaguez:['Estar ebrio (en el sueño)','Sentirte ebrio o fuera de control en un sueño, sin haber bebido en la vida real, simboliza sentir que una situación te está haciendo perder claridad o control sobre tus propias decisiones.','También puede reflejar el deseo de soltar el control de forma consciente por un rato.','¿En qué situación sientes que estás perdiendo claridad sobre tus propias decisiones?'],
  drogas:['Sueños relacionados con sustancias','Soñar con el uso de sustancias, incluso sin relación con tu vida real, suele simbolizar el deseo de escapar temporalmente de una realidad que sientes demasiado intensa.','No necesariamente refleja un deseo real de consumo: la mente usa esa imagen como metáfora de evasión.','¿De qué realidad sientes, simbólicamente, ganas de "escapar" un rato?'],
  enfermedadpropia:['Enfermarte gravemente (en el sueño)','Soñar con una enfermedad grave propia suele reflejar ansiedad general sobre el control que tienes sobre tu cuerpo o tu vida, más que una premonición real de salud.','Si la preocupación persiste al despertar, siempre vale la pena consultarlo con un profesional de salud real, más allá del sueño.','¿Qué área de tu vida sientes que se te está "escapando de las manos" en cuanto a control?'],
  cirugia:['Cirugía','Una cirugía en sueños simboliza un cambio profundo y necesario, aunque incómodo o invasivo en el proceso, para resolver algo que no se solucionaría de forma superficial.','A diferencia de una herida que sana sola, la cirugía implica intervención activa y consciente para resolver el problema.','¿Qué situación sientes que necesita una "intervención" más profunda, no solo paños tibios?'],
  medicina:['Tomar medicina','Tomar medicina en un sueño representa buscar una solución concreta a un malestar que ya reconociste. Rechazar la medicina en el sueño puede señalar resistencia a aceptar ayuda.','El sabor o la dificultad para tragarla suele reflejar qué tan fácil o difícil te resulta aceptar esa ayuda en la vida real.','¿Qué tipo de "ayuda" te cuesta más aceptar, aunque sepas que la necesitas?'],
  boca2:['Vomitar (en el sueño)','Vomitar en un sueño simboliza liberar algo que te hizo daño —una situación, una palabra, una emoción tóxica— que ya no quieres seguir conteniendo.','Aunque la imagen sea desagradable, suele tener una lectura positiva: el cuerpo "expulsando" lo que ya no sirve.','¿Qué necesitas "sacar de tu sistema" porque ya no te hace bien retenerlo?'],
  embarazada2:['Aborto (en el sueño)','Soñar con un aborto, propio o ajeno, suele simbolizar el fin de un proyecto o idea antes de que pudiera desarrollarse del todo, generando duelo por ese potencial no realizado.','No necesariamente está relacionado con un embarazo real: la mente usa el símbolo para cualquier "proyecto" interrumpido.','¿Qué proyecto o idea sientes que quedó interrumpido antes de poder desarrollarse?'],
  ceguera:['Quedarte ciego (en el sueño)','Perder la vista en un sueño simboliza negarte a ver algo —una verdad, una señal— que en el fondo ya percibes con claridad.','A diferencia de la niebla (confusión temporal), la ceguera sugiere una negación más activa, no solo falta de información.','¿Qué verdad estás evitando mirar de frente, aunque en el fondo ya la conozcas?'],
  sordera:['Quedarte sordo (en el sueño)','Quedarte sordo en un sueño simboliza negarte a escuchar un mensaje, consejo o advertencia que alguien ya te ha dado, consciente o inconscientemente.','Puede reflejar también cansancio de escuchar siempre la misma opinión ajena sobre un tema sensible.','¿Qué consejo llevas tiempo recibiendo y evitando escuchar de verdad?'],
  mudo:['Quedarte mudo','Quedarte sin voz en un sueño, sin poder hablar aunque quieras, refleja sentir que no tienes permiso —propio o percibido— de expresar algo importante en una situación concreta.','Es una variante más intensa del grito silencioso: aquí ni siquiera lo intentas, simplemente no puedes.','¿En qué espacio sientes que no tienes "permiso" de decir lo que realmente piensas?'],
  volarsinalas:['Flotar (sin volar del todo)','Flotar suavemente, sin control total pero sin caer, simboliza un estado de transición cómoda: no tienes control absoluto de la situación, pero tampoco sientes peligro inminente.','Es distinto a volar con intención: flotar sugiere dejarte llevar más que dirigir activamente el rumbo.','¿Hay alguna situación donde te está funcionando bien simplemente "dejarte llevar"?'],
  transformacion:['Transformarte en otro ser','Soñar que te transformas en un animal u otra persona simboliza integrar una cualidad de ese ser —fuerza, libertad, astucia— que sientes que necesitas ahora mismo.','La reacción emocional durante la transformación (miedo o fascinación) suele reflejar qué tan cómodo te sientes integrando esa nueva cualidad.','¿Qué cualidad de ese ser sientes que te vendría bien integrar en ti ahora?'],
  dobleyo:['Verte a ti mismo desde afuera','Verte a ti mismo como si fueras otra persona (una experiencia extracorporal onírica) suele reflejar un momento de autoevaluación consciente sobre cómo estás viviendo tu vida.','Es un fenómeno fascinante estudiado en la ciencia del sueño, relacionado con los sueños lúcidos y la autoconciencia durante el dormir.','Si te vieras a ti mismo desde afuera ahora mismo, ¿qué es lo primero que notarías?'],
  luciadosueño:['Sueño lúcido (saber que sueñas)','Darte cuenta dentro del sueño de que estás soñando —un sueño lúcido— refleja un alto nivel de autoconciencia y, muchas veces, el deseo de tomar más control sobre una situación de tu vida despierta.','Es uno de los fenómenos de sueño más estudiados científicamente y puede entrenarse con práctica consciente.','¿En qué área de tu vida te gustaría sentir ese mismo nivel de control consciente?'],
  delfin:['Delfín','El delfín simboliza inteligencia emocional, alegría y una conexión intuitiva sana con tus propios sentimientos, a diferencia de otros símbolos del mar más amenazantes.','Verlo jugar suele reflejar una relación armoniosa con tu mundo emocional en este momento de tu vida.','¿Qué parte de tu vida emocional sientes que fluye con esa misma ligereza ahora?'],
  pulpo:['Pulpo','El pulpo representa versatilidad y la sensación de tener que atender muchas cosas a la vez, a veces más de las que puedes manejar con comodidad.','Sus tentáculos también pueden simbolizar sentirte "atrapado" por varias obligaciones simultáneas.','¿Sientes que estás atendiendo demasiadas cosas al mismo tiempo?'],
  cangrejo:['Cangrejo','El cangrejo simboliza protección mediante una coraza externa, mientras por dentro puede haber mayor sensibilidad de la que se muestra.','Caminar "de lado" como el cangrejo también puede representar evitar enfrentar un tema de forma directa.','¿Hay un tema que estás abordando "de lado" en vez de ir directo a él?'],
  pavoreal:['Pavo real','El pavo real representa orgullo, belleza y el deseo de ser reconocido o admirado por los demás.','Mostrar las plumas con naturalidad habla de autoestima sana; hacerlo con ansiedad, de necesitar validación externa constante.','¿Buscas reconocimiento porque lo disfrutas, o porque sientes que lo necesitas para sentirte bien?'],
  zorro:['Zorro','El zorro simboliza astucia, adaptabilidad y, en ocasiones, desconfianza hacia alguien que percibes como calculador en tus relaciones.','También puede representar una parte tuya que resuelve problemas con ingenio más que con fuerza.','¿Estás resolviendo una situación con ingenio, o sientes que alguien más lo está haciendo a tu costa?'],
  ardilla:['Ardilla','La ardilla representa previsión: guardar recursos para el futuro. También puede señalar ansiedad por "acumular" más de lo que realmente necesitas por inseguridad.','Verla recolectar con calma habla de planificación sana; hacerlo con urgencia, de ansiedad sobre el futuro.','¿Estás planificando con calma, o acumulando por miedo a que falte algo?'],
  jirafa:['Jirafa','La jirafa simboliza perspectiva elevada y la capacidad de ver más allá de lo inmediato, aunque a veces a costa de sentirte distinto a los demás.','También puede representar la necesidad de "estirarte" un poco más para alcanzar una meta que sientes alta pero posible.','¿Qué meta sientes que está un poco fuera de tu alcance actual, pero no imposible?'],
  pinguino:['Pingüino','El pingüino representa adaptación a condiciones difíciles y la fortaleza de mantenerte de pie con otros en un entorno exigente.','También simboliza comunidad: los pingüinos sobreviven juntos, lo cual puede señalar la importancia de no enfrentar algo en soledad.','¿Hay algo difícil que estás atravesando y que sería más fácil si no lo hicieras solo?'],
  camello:['Camello','El camello simboliza resistencia y la capacidad de sostener una carga pesada durante un trayecto largo sin quejarte demasiado.','Puede ser una señal de que, aunque aguantas bien, convendría revisar cuánta carga realmente necesitas seguir llevando.','¿Cuánta de esa carga que sostienes con resistencia es realmente necesaria?'],
  hiena:['Hiena','La hiena se asocia con astucia oportunista o con sentir que alguien se beneficia de una situación a costa tuya.','Su risa característica también puede representar una burla que sientes dirigida hacia ti en algún contexto.','¿Sientes que alguien se está beneficiando de una situación tuya sin que sea justo?'],
  erizo:['Erizo','El erizo representa sensibilidad protegida por defensas: alguien —o una parte de ti— que se eriza ante el peligro aunque por dentro sea más suave de lo que aparenta.','Soñar con un erizo que se relaja contigo puede señalar que estás ganando confianza para bajar tus propias defensas con alguien.','¿Con quién sientes que, poco a poco, puedes bajar un poco tus defensas?'],
  rinoceronte:['Rinoceronte','El rinoceronte simboliza fuerza bruta protegida por una coraza gruesa: avanza sin detenerse demasiado a dudar, aunque a veces con poca delicadeza.','Puede representar una parte tuya que necesita avanzar con más determinación, dejando de lado el exceso de cautela.','¿Dónde necesitas avanzar con más determinación y menos cautela de la habitual?'],
  canguro:['Canguro','El canguro representa protección maternal o la necesidad de "cargar" algo cerca de ti para sentirte seguro durante una etapa vulnerable.','También puede simbolizar grandes saltos de avance, alternados con pausas necesarias para recuperar impulso.','¿Qué necesitas mantener "cerca" para sentirte seguro en esta etapa?'],
  foca:['Foca','La foca simboliza juego, sociabilidad y una facilidad natural para desenvolverte en ambientes cambiantes (como el agua y la tierra a la vez).','Verla jugar con otras suele reflejar una necesidad sana de más momentos ligeros y sociales en tu rutina.','¿Hace cuánto no te permites un momento verdaderamente ligero y social?'],
  armario:['Armario / clóset','El armario representa lo que guardas —ropa, identidades o secretos— fuera de la vista inmediata. Encontrar algo inesperado dentro simboliza descubrir una parte de ti misma que habías olvidado.','"Salir del clóset" simbólicamente puede aplicarse a cualquier verdad personal que estás considerando mostrar abiertamente.','¿Hay alguna verdad personal que estás considerando mostrar más abiertamente?'],
  cama:['Cama','La cama representa descanso, intimidad y vulnerabilidad. Una cama incómoda o ajena en el sueño puede señalar que un espacio que debería darte seguridad no lo está haciendo del todo.','También es un símbolo recurrente en sueños sobre relaciones de pareja, dado su vínculo con la intimidad.','¿Tu espacio de descanso habitual realmente te hace sentir seguro y cómodo?'],
  mesa:['Mesa','La mesa simboliza encuentro y lo que se comparte en comunidad: decisiones, comidas, conversaciones importantes. Una mesa vacía habla de soledad; una llena, de abundancia en vínculos.','Sentarte en la cabecera de la mesa en un sueño puede reflejar sentir —o desear sentir— más liderazgo en un grupo.','¿En qué grupo te gustaría tener, o sientes que ya tienes, un rol más de liderazgo?'],
  silla:['Silla','Una silla representa tu lugar o rol en una situación específica. Una silla vacía puede señalar la ausencia de alguien importante; quedarte sin silla, miedo a no tener un lugar asegurado.','Es un símbolo pequeño pero frecuente en sueños sobre pertenencia social o familiar.','¿Sientes que tienes un lugar asegurado en los espacios que más te importan?'],
  techo:['Techo','El techo simboliza protección y límites: lo que te cubre, pero también lo que puede sentirse como un tope. Un techo que gotea habla de una protección que ya no es suficiente.','Romper un techo en sueños puede simbolizar el deseo de superar un límite que sentías fijo hasta ahora.','¿Qué "techo" sientes que estás a punto de superar?'],
  sotano:['Sótano','El sótano representa el inconsciente más profundo: lo que has guardado durante mucho tiempo, incluso de ti mismo. Bajar a un sótano oscuro simboliza disposición a explorar algo incómodo pero importante.','A diferencia del ático —ideales—, el sótano suele conectar con miedos o recuerdos más antiguos.','¿Qué recuerdo antiguo sientes que influye más de lo que admites en tu presente?'],
  atico:['Ático / desván','El ático representa tus ideales, recuerdos guardados con cariño o aspiraciones que mantienes "arriba", fuera del uso diario pero presentes.','Encontrar un objeto querido en el ático soñado suele señalar el deseo de recuperar algo valioso que dejaste de lado.','¿Qué aspiración antigua te gustaría "bajar del ático" y retomar?'],
  tatuaje:['Tatuaje','Un tatuaje simboliza una marca permanente —una decisión, experiencia o identidad— que has decidido llevar contigo de forma consciente y duradera.','Si el tatuaje en el sueño no te gusta o aparece sin que lo eligieras, puede reflejar sentir que una etapa te "marcó" sin tu consentimiento total.','¿Qué experiencia reciente sientes que te "marcó" de forma permanente, para bien o para mal?'],
  cicatriz:['Cicatriz','Una cicatriz representa una herida ya superada que dejó una marca, pero que ya no duele activamente como al principio.','A diferencia de una herida abierta, soñar con una cicatriz suele reflejar que un proceso difícil ya está integrado en tu historia personal.','¿Qué "cicatriz" de tu historia llevas hoy con más paz que antes?'],
  sombrero:['Sombrero','El sombrero representa el rol o la identidad que decides mostrar en una situación ("ponerte un sombrero" distinto según el contexto). Perderlo con el viento habla de sentir que pierdes el control de esa identidad frente a otros.','También puede simbolizar protección de la mente frente a presiones externas, como un sol intenso.','¿Qué "rol" sientes que te toca sostener en este momento de tu vida?'],
  mascara:['Máscara','Una máscara simboliza una parte de ti que ocultas deliberadamente frente a los demás, ya sea por protección o por adaptarte a lo que se espera de ti.','Quitarte la máscara en el sueño frente a alguien de confianza suele reflejar el deseo de mostrarte más auténtico con esa persona.','¿Con quién te gustaría poder "quitarte la máscara" un poco más?'],
  guantes:['Guantes','Los guantes representan distancia protectora al manejar algo delicado o incómodo: tocar sin comprometerte del todo emocionalmente.','Quitarte los guantes en un sueño puede señalar el deseo de involucrarte más directamente en algo que antes mantenías a distancia.','¿Hay algo que estás manejando "con guantes" y que, en el fondo, te gustaría abordar más directo?'],
  martillo:['Martillo','El martillo simboliza fuerza aplicada con intención: construir algo nuevo o, según el contexto, resolver un problema de forma contundente.','Usarlo para romper algo en vez de construir puede reflejar frustración acumulada buscando una salida física.','¿Estás usando tu energía actual para construir algo, o más bien para "romper" tensión acumulada?'],
  hacha:['Hacha','El hacha representa la decisión de cortar de raíz algo que ya no sirve, de forma más drástica que con un cuchillo o una espada.','Cortar un árbol con un hacha puede simbolizar el fin consciente de un ciclo de crecimiento que ya cumplió su función.','¿Qué necesitas "cortar de raíz" en lugar de seguir postergando?'],
  televisor:['Televisor / pantalla','Una pantalla que no funciona bien en sueños simboliza sentir que no estás recibiendo información clara sobre una situación importante.','Ver algo inquietante en la pantalla puede reflejar una preocupación que absorbes del entorno más de lo que te das cuenta.','¿Qué tanto te está afectando, sin notarlo, la información que consumes a diario?'],
  radio:['Radio (aparato)','Una radio con estática o mala señal representa un mensaje —interno o externo— que no está llegando con claridad.','Escuchar una canción específica en la radio del sueño suele traer una pista emocional directa si la recuerdas.','Si pudieras "sintonizar" con claridad un mensaje interno ahora mismo, ¿cuál sería?'],
  guitarra:['Guitarra','La guitarra representa expresión creativa personal e íntima, a menudo ligada a emociones que prefieres comunicar sin palabras directas.','Tocarla con torpeza puede reflejar inseguridad sobre cómo expresas tu mundo emocional ante otros.','¿Qué emoción expresarías mejor con un gesto creativo que con palabras directas?'],
  piano:['Piano','El piano simboliza armonía entre distintas partes de ti mismo: cada tecla representa un matiz emocional distinto que, juntos, pueden sonar en equilibrio.','Un piano desafinado puede señalar que alguna parte de tu vida está "fuera de tono" con el resto.','¿Qué área de tu vida sientes "desafinada" respecto al resto?'],
  tambor:['Tambor','El tambor representa el ritmo vital básico: energía, pulso y, en ocasiones, una llamada de atención que no puedes ignorar.','Escuchar un tambor a la distancia puede simbolizar una señal interna que se acerca y pide ser atendida.','¿Qué "llamado" interno sientes que se acerca y ya no puedes seguir posponiendo?'],
  futbol:['Fútbol / deporte en equipo','Jugar un deporte en equipo en sueños representa cooperación, estrategia compartida y cómo te sientes integrado dentro de un grupo con una meta común.','Fallar un gol o jugada clave puede reflejar miedo a decepcionar a un grupo que depende de ti.','¿Sientes presión por no decepcionar a un grupo que cuenta contigo?'],
  bombero:['Bombero','Un bombero simboliza ayuda rápida ante una crisis, o tu propia capacidad de "apagar incendios" emocionales, propios o ajenos, de forma recurrente.','Ser tú el bombero del sueño puede reflejar que sueles asumir el rol de resolver crisis de otros antes que las propias.','¿Con qué frecuencia apagas "incendios" ajenos antes que los propios?'],
  enfermera:['Enfermera / enfermero','Una figura de enfermería representa cuidado activo y atención a una herida —física o emocional— que necesita acompañamiento constante, no solo diagnóstico.','Puede señalar la necesidad de un cuidado más sostenido, no solo una solución puntual.','¿Qué necesita, en tu vida, un cuidado sostenido en vez de una solución rápida?'],
  abogado:['Abogado / juez','Una figura de abogado o juez en sueños representa la necesidad de justicia, de ser escuchado con imparcialidad o de defender una postura que sientes cuestionada.','Sentirte juzgado injustamente en el sueño refleja una necesidad real de sentirte comprendido en un conflicto actual.','¿En qué situación sientes que necesitas que alguien escuche "tu versión" con más justicia?'],
  sacerdote:['Sacerdote / figura religiosa','Una figura religiosa en sueños representa tu brújula moral interna, más allá de tu práctica religiosa real, o la necesidad de orientación ética frente a una decisión.','Buscar su consejo en el sueño suele señalar una decisión donde sientes que lo correcto no es del todo obvio.','¿Qué decisión sientes que tiene más de un "correcto" posible, y te cuesta elegir?'],
  monja:['Monja','Una monja simboliza disciplina espiritual, renuncia consciente a ciertos placeres o una parte tuya que busca sentido más allá de lo material.','También puede representar un conflicto entre deseo personal y un compromiso que sientes que debes honrar.','¿Sientes tensión entre un deseo personal y un compromiso que valoras cumplir?'],
  buda:['Buda / figura de paz','Una figura como Buda en sueños simboliza la búsqueda de calma interior y desapego frente a algo que normalmente te genera ansiedad.','Suele aparecer en periodos donde, conscientemente, estás intentando soltar el control sobre algo que no depende de ti.','¿Qué estás intentando soltar, aunque te cueste trabajo hacerlo del todo?'],
  navidad:['Navidad / fiesta familiar','Soñar con una celebración como la Navidad activa dinámicas familiares y expectativas de unión, para bien o para mal, según cómo se sintiera la escena.','Sentir tensión en una celebración soñada suele reflejar una tensión familiar real que se intensifica en fechas significativas.','¿Qué expectativa familiar sientes que pesa más en fechas importantes?'],
  cumpleanos:['Cumpleaños','Un cumpleaños en sueños simboliza balance de etapa: revisar qué has logrado y qué sientes pendiente antes de un nuevo ciclo personal.','Sentirte solo en tu propio cumpleaños soñado puede reflejar miedo a no sentirte suficientemente acompañado en este momento de tu vida.','Si hicieras un balance honesto de esta etapa, ¿qué destacarías como logro y qué como pendiente?'],
  mochila:['Mochila','La mochila representa lo que cargas cotidianamente: responsabilidades que llevas contigo a diario, a diferencia de la maleta, más ligada a una transición grande.','Una mochila demasiado pesada para cargar refleja una sobrecarga de responsabilidades diarias, no de una sola etapa de vida.','¿Qué podrías "sacar de tu mochila" diaria para sentir menos peso?'],
  tarea:['Tarea sin terminar','Soñar con una tarea escolar o laboral sin terminar, con el tiempo corriendo en contra, refleja ansiedad por responsabilidades pendientes reales en tu vida despierta.','Es una variante directa del símbolo del examen, enfocada en la sensación de estar "atrasado" más que evaluado.','¿Qué responsabilidad pendiente sientes que corre contra el tiempo ahora mismo?'],
  tsunami:['Tsunami','Un tsunami representa una emoción —o un conjunto de noticias— que llega de golpe y con una fuerza que se siente imposible de controlar o prevenir.','A diferencia de la inundación gradual, el tsunami simboliza un evento repentino que cambia el panorama de una sola vez.','¿Qué situación reciente sientes que cambió todo de golpe, sin darte tiempo de prepararte?'],
  huracan:['Huracán','El huracán representa una crisis emocional intensa pero con un centro de calma reconocible (el "ojo del huracán"): en medio del caos, una parte tuya sigue sabiendo qué hacer.','Buscar refugio durante el huracán soñado refleja la búsqueda real de un espacio seguro mientras algo difícil pasa a tu alrededor.','¿Dónde encuentras tu "centro de calma" mientras algo caótico ocurre alrededor?'],
  sequia:['Sequía','La sequía simboliza una etapa de escasez emocional sostenida: falta de inspiración, afecto o energía durante un periodo más largo de lo habitual.','A diferencia de la sed puntual, la sequía refleja un patrón prolongado que necesita un cambio de fondo, no una solución inmediata.','¿Qué área de tu vida sientes "seca" desde hace ya bastante tiempo?'],
  granizo:['Granizo','El granizo representa un conflicto breve pero intenso: algo que golpea con fuerza durante poco tiempo, dejando daños puntuales más que una crisis prolongada.','Suele aparecer después de discusiones repentinas que, aunque cortas, dejan una marca incómoda.','¿Hubo una discusión reciente, breve pero intensa, que todavía sientes que dejó una marca?'],
  piedra:['Piedra / roca','Una piedra simboliza solidez, un obstáculo concreto en tu camino, o la base firme sobre la que construyes algo importante, según el contexto del sueño.','Cargar una piedra pesada puede representar una responsabilidad que sientes que debes sostener aunque te cueste esfuerzo.','¿Esa "piedra" en tu camino es un obstáculo a quitar, o una base sobre la que construir?'],
  arena:['Arena','La arena representa inestabilidad o el paso del tiempo (como en un reloj de arena): algo que se te escapa entre los dedos por más que intentes sostenerlo con firmeza.','Caminar sobre arena que se hunde puede simbolizar sentir que tus esfuerzos no encuentran un terreno firme donde apoyarse.','¿Sientes que algo se te "escapa entre los dedos" sin importar cuánto esfuerzo pongas?'],
  cristal:['Cristal / gema','Un cristal o gema representa claridad, valor personal reconocido o una cualidad tuya que recién empieza a "pulirse" y mostrarse con brillo propio.','Encontrar una gema escondida suele señalar el descubrimiento de un valor propio que antes no reconocías del todo.','¿Qué cualidad tuya sientes que recién está empezando a "brillar" con más claridad?'],
  perla:['Perla','La perla simboliza algo valioso que nació de una irritación o dificultad inicial (como la perla dentro de la ostra): un aprendizaje hermoso que vino de un proceso incómodo.','Suele aparecer cuando, en retrospectiva, empiezas a ver el valor de una experiencia que en su momento fue dolorosa.','¿Qué dificultad pasada reconoces hoy que, con el tiempo, se convirtió en algo valioso?'],
  escarabajo:['Escarabajo','El escarabajo simboliza transformación persistente y paciente, trabajando en silencio aunque desde fuera parezca poco notorio.','En varias tradiciones antiguas representa también renovación y la capacidad de "reciclar" lo viejo en algo nuevo y útil.','¿Qué estás transformando poco a poco, aunque desde fuera no se note todavía?'],
  mariquita:['Mariquita','La mariquita simboliza buena fortuna pequeña e inesperada, un detalle afortunado que llega en medio de la rutina diaria.','Verla posarse sobre ti en sueños suele asociarse, en muchas culturas, con un pequeño golpe de suerte próximo.','¿Qué pequeño detalle afortunado has notado últimamente, aunque le hayas dado poca importancia?'],
  saltamontes:['Saltamontes','El saltamontes representa avance por impulsos: saltos repentinos de progreso en lugar de un camino constante y lineal.','Puede reflejar una forma de avanzar que a veces se siente errática, pero que igual te acerca a donde quieres llegar.','¿Sientes que avanzas "a saltos" en vez de forma constante, y qué tan bien te funciona ese ritmo?'],
  soledad:['Soledad (sentirla en el sueño)','Sentir soledad profunda dentro de un sueño, incluso rodeado de gente, refleja una necesidad de conexión más genuina que la que estás teniendo en tu vida social actual.','Es distinto de estar solo físicamente: aquí lo relevante es la emoción de desconexión, no la cantidad de gente alrededor.','¿Sientes que tienes compañía real, o más bien presencia sin verdadera conexión?'],
  esperanza:['Esperanza (tono general del sueño)','Un sueño con un tono general esperanzador, aunque la escena sea neutra, suele reflejar que una parte de ti ya confía en que una situación difícil va a mejorar.','Vale la pena prestar atención a estos sueños como contrapeso de la ansiedad cotidiana, no solo a los inquietantes.','¿Qué situación actual sientes que, en el fondo, confías en que va a mejorar?'],
  orgullo:['Orgullo (sentirlo en el sueño)','Sentir orgullo genuino dentro de un sueño por algo logrado refleja una autoestima que está reconociendo, por fin, un esfuerzo real que hiciste.','Vale la pena no minimizar este tipo de sueños: suelen ser un recordatorio de algo que mereces reconocerte a ti mismo.','¿Qué logro propio mereces reconocerte más de lo que lo haces normalmente?'],
  olvidar:['Olvidar algo importante','Soñar que olvidas algo crucial (una cita, un objeto, una persona) refleja miedo a fallarle a alguien o a ti mismo en un compromiso que consideras importante.','También puede señalar, al contrario, el deseo inconsciente de "olvidar" algo que te pesa llevar en la memoria.','¿Es miedo a fallar, o en el fondo hay algo que preferirías poder olvidar?'],
  recordar:['Recordar algo olvidado','Recordar de pronto, dentro de un sueño, algo que habías olvidado en la vida real simboliza que tu mente está reconectando información relevante que tu consciente pasó por alto.','Vale la pena anotar estos sueños: a veces señalan de forma literal un pendiente real que conviene resolver.','¿Hay algo que tu sueño te "recordó" que de verdad necesitas atender?'],
  olor:['Un olor específico (en el sueño)','Oler algo específico y memorable dentro de un sueño es poco común y suele estar ligado a un recuerdo muy concreto que ese olor activó en tu memoria.','El olfato es el sentido más directamente conectado con la memoria emocional, así que este símbolo suele ser muy personal.','¿Qué recuerdo específico te trae ese olor en particular?'],
  moto:['Motocicleta','La motocicleta representa libertad de movimiento más arriesgada y personal que el coche: menos protección, pero más sensación directa de control y velocidad.','Perder el equilibrio en la moto puede reflejar que estás tomando un riesgo que, aunque emocionante, sientes que requiere más cuidado.','¿Qué riesgo estás tomando que te emociona, pero también sabes que requiere más cuidado?'],
  camion:['Camión','Un camión simboliza una carga grande que transportas, muchas veces relacionada con responsabilidades familiares o laborales de mayor peso que lo cotidiano.','Conducir un camión con dificultad puede reflejar sentir que una responsabilidad es más grande de lo que te sientes preparado para manejar.','¿Qué responsabilidad sientes que es más grande de lo que esperabas asumir?'],
  metro:['Metro / subterráneo','El metro representa avanzar en la vida de forma colectiva y bajo tierra, es decir, de forma menos visible pero igualmente efectiva que otros medios.','Perder la salida correcta en el metro soñado puede señalar sentirte desorientado dentro de un sistema o institución más grande que tú.','¿Te sientes orientado dentro del "sistema" (laboral, social) del que formas parte?'],
  tijeras:['Tijeras','Las tijeras representan la capacidad de separar con precisión: cortar un vínculo, una idea o un hábito de forma más controlada que con un hacha o cuchillo.','Usarlas para crear algo (como un collage) en lugar de cortar puede simbolizar creatividad a partir de piezas sueltas de tu vida.','¿Qué necesitas separar con precisión, sin necesidad de un corte drástico?'],
  pintura:['Pintura / pintar','Pintar en un sueño representa expresión creativa de tu mundo interior, dándole forma y color a emociones que de otra manera serían difíciles de explicar con palabras.','Un cuadro que no logras terminar puede reflejar una idea o proyecto creativo que sientes incompleto en la vida real.','¿Qué proyecto creativo o personal sientes que te falta terminar de "pintar"?'],
  escritura:['Escribir (en el sueño)','Escribir algo importante en un sueño —una carta, un diario— representa la necesidad de ordenar tus pensamientos o dejar un registro consciente de algo que estás viviendo.','No poder encontrar las palabras correctas en el sueño refleja dificultad real para expresar algo complejo en tu vida despierta.','¿Qué necesitas "poner por escrito" para empezar a procesarlo mejor?'],
  fotografia:['Fotografía / foto','Una fotografía en sueños representa un recuerdo congelado en el tiempo, o el deseo de preservar un momento que sientes valioso y fugaz.','Una foto borrosa o dañada puede simbolizar un recuerdo que se está desvaneciendo y que, en el fondo, no quieres perder del todo.','¿Qué momento reciente te gustaría "congelar" para no olvidarlo nunca?'],
  nombre:['Olvidar tu propio nombre','Olvidar tu propio nombre en un sueño, aunque poco común, representa una crisis profunda de identidad: sentir que ya no sabes bien quién eres en esta etapa de tu vida.','Suele aparecer en momentos de transición muy grandes, donde varias certezas sobre ti mismo están cambiando a la vez.','¿Qué parte de tu identidad sientes que está en plena redefinición ahora mismo?'],
  voz:['Escuchar una voz sin ver a nadie','Escuchar una voz sin ver a quién pertenece representa un mensaje de tu propio inconsciente, muchas veces más honesto que lo que te permites pensar conscientemente.','Vale la pena recordar exactamente qué decía esa voz: suele ser la parte más reveladora de todo el sueño.','Si esa voz fuera tu propia intuición hablándote con honestidad, ¿qué crees que te estaría diciendo?'],
  eco:['Eco (sonido que se repite)','Un eco que se repite en un sueño simboliza una idea o preocupación que vuelve una y otra vez, sin que termines de resolverla del todo.','A diferencia de un pensamiento puntual, el eco sugiere que ya ha pasado por tu mente más de una vez sin encontrar solución.','¿Qué pensamiento sientes que se repite en tu mente sin llegar nunca a una conclusión?'],
  silencio:['Silencio absoluto (en el sueño)','Un silencio total y pesado en un sueño puede representar la calma antes de un cambio importante, o la sensación de estar esperando algo que todavía no llega.','También puede señalar la necesidad real de más momentos de silencio consciente en tu día a día.','¿Necesitas más silencio real en tu rutina diaria del que normalmente te permites?'],
  multitudperdido:['Perderte entre la multitud','Perderte de alguien importante entre una multitud representa miedo a perder la conexión con esa persona en medio de las exigencias cotidianas.','También puede simbolizar sentir que tu identidad se diluye un poco cuando estás rodeado de demasiadas personas o expectativas.','¿Con quién temes "perder la conexión" en medio de tanto ruido cotidiano?'],
  vacuna:['Vacuna / inyección','Una inyección en sueños representa una medida preventiva: protegerte de algo antes de que se convierta en un problema mayor, aunque el proceso incomode un poco.','El miedo a la aguja en el sueño puede reflejar resistencia a tomar una precaución que, en el fondo, sabes que te conviene.','¿Qué precaución sabes que te conviene tomar, aunque te incomode el proceso?'],
  diente2:['Dentista','Soñar con el dentista combina el símbolo de los dientes con la idea de "revisión": una autoevaluación sobre tu imagen o tu forma de comunicarte que sientes pendiente.','Un tratamiento doloroso en el sueño puede reflejar que esa revisión personal no será del todo cómoda, pero sí necesaria.','¿Qué parte de cómo te comunicas o te muestras sientes que merece una revisión honesta?'],
  embotellamiento:['Tráfico / embotellamiento','Quedar atrapado en tráfico simboliza sentir que un proyecto o plan avanza mucho más lento de lo que esperabas, sin que dependa solo de ti.','La frustración en el sueño suele ser proporcional a cuánta prisa sientes realmente en la vida despierta.','¿Qué plan sientes que avanza más lento de lo que te gustaría, por razones fuera de tu control?'],
  semaforo:['Semáforo','Un semáforo en rojo representa una pausa obligada antes de avanzar: no es un no definitivo, sino una señal de esperar el momento correcto.','Uno en verde que de pronto cambia puede simbolizar una oportunidad que se cierra más rápido de lo esperado.','¿Qué "luz" (señal) sientes que estás esperando antes de avanzar con algo importante?'],
  barrera:['Barrera / valla','Una barrera que te impide el paso representa un obstáculo que sientes puesto por reglas, normas o límites ajenos a tu voluntad directa.','Saltarla con éxito en el sueño puede reflejar confianza creciente en tu capacidad de sortear restricciones externas.','¿Qué "barrera" impuesta por otros sientes que podrías empezar a cuestionar?'],
  cerca:['Cerca / muro bajo','Una cerca representa un límite propio que marcas frente a otros: hasta dónde permites que alguien entre en tu espacio personal o emocional.','Una cerca derribada en el sueño puede señalar que un límite tuyo fue cruzado recientemente sin tu consentimiento.','¿Sientes que un límite tuyo fue cruzado recientemente?'],
  muroalto:['Muro / pared','Un muro alto simboliza una barrera emocional que has levantado, muchas veces como protección después de una experiencia dolorosa.','Verlo desde el otro lado, sin poder cruzarlo, puede reflejar una parte de ti de la que te sientes distante incluso de ti mismo.','¿Qué muro propio pusiste después de una experiencia dolorosa, y sigue siendo necesario?'],
  jaula:['Jaula','La jaula simboliza una limitación que, a diferencia de la prisión, puede ser más sutil: una rutina, un rol o una expectativa que te restringe sin parecer una condena evidente.','Un pájaro en una jaula abierta que no sale puede reflejar miedo a la libertad más que falta de oportunidad real para tomarla.','Si la "puerta de tu jaula" estuviera abierta ahora mismo, ¿qué te detendría de salir?'],
  cadena:['Cadenas','Las cadenas representan una atadura más específica que la jaula: un compromiso, deuda o lealtad concreta que sientes que te limita de forma directa.','Romper una cadena en el sueño simboliza el deseo —o el proceso ya en marcha— de liberarte de esa atadura específica.','¿Qué atadura concreta sientes que estás, poco a poco, logrando soltar?'],
  cerradura:['Cerradura','Una cerradura que no abre representa un acceso bloqueado a algo que deseas: una oportunidad, una respuesta o una relación que se siente fuera de tu alcance por ahora.','Encontrar la llave correcta después de varios intentos puede simbolizar que la solución está más cerca de lo que parecía al principio.','¿Qué "cerradura" sientes que estás cerca de abrir, aunque te haya costado varios intentos?'],
  pasillo:['Pasillo largo','Un pasillo interminable simboliza una espera prolongada o un proceso de transición que se siente más largo de lo que esperabas.','Puertas a los lados del pasillo que no abres pueden representar opciones que estás postergando explorar.','¿Qué opción llevas tiempo postergando explorar, aunque esté "a los lados" de tu camino actual?'],
  escaleraelectrica:['Escalera eléctrica','Una escalera eléctrica que avanza sola representa un progreso que sientes que ocurre con menos esfuerzo propio del habitual, a veces generando la sensación de no merecerlo del todo.','Si se detiene de golpe, puede reflejar miedo a que un avance reciente se frene inesperadamente.','¿Sientes que un avance reciente fue "demasiado fácil" como para confiar del todo en él?'],
  ascensorroto:['Elevador atascado entre pisos','Quedar atascado en un ascensor entre dos pisos simboliza sentirte "entre dos etapas" sin terminar de llegar a ninguna, generando ansiedad por la indefinición.','A diferencia de quedar atrapado del todo, aquí el símbolo central es la indefinición, no el encierro en sí.','¿En qué área sientes que estás "entre dos etapas", sin aterrizar del todo en ninguna?'],
  disparo:['Disparo / bala','Escuchar o recibir un disparo en sueños representa una noticia o palabra que te impactó de forma repentina y dolorosa, incluso si no fue literalmente violenta.','Esquivar la bala en el sueño puede simbolizar alivio reciente por haber evitado una consecuencia que temías.','¿Qué "bala" —palabra o noticia— sentiste que te impactó de golpe recientemente?'],
  explosion:['Explosión','Una explosión representa una situación que, tras acumular tensión, finalmente estalla de forma visible para todos, no solo para ti.','A diferencia del volcán (interno y personal), la explosión suele involucrar a más personas o un contexto más público.','¿Qué tensión acumulada sientes que podría "estallar" si no se atiende pronto?'],
  bomba:['Bomba (artefacto)','Una bomba sin estallar todavía simboliza una situación tensa que sientes que podría "explotar" en cualquier momento si no se maneja con cuidado.','Desactivarla con éxito en el sueño refleja confianza en tu capacidad de manejar un conflicto delicado antes de que escale.','¿Qué situación sientes que necesita manejarse "con cuidado" antes de que escale?'],
  humo:['Humo','El humo representa una señal de que algo está ocurriendo, aunque todavía no veas la fuente exacta del problema con claridad.','Seguir el humo hasta su origen en el sueño simboliza disposición a investigar una situación confusa hasta entenderla del todo.','¿Qué situación confusa estás dispuesto a investigar hasta entenderla por completo?'],
  ceniza:['Ceniza','La ceniza representa lo que queda después de un proceso de transformación intenso: el final de algo, pero también la base fértil para lo que viene después.','Recoger ceniza con cuidado en el sueño puede simbolizar honrar el cierre de una etapa antes de empezar la siguiente.','¿Qué final necesitas honrar antes de sentirte listo para empezar algo nuevo?'],
  semilla:['Semilla','La semilla simboliza potencial puro: una idea o proyecto en su etapa más temprana, antes de que se pueda ver resultado alguno todavía.','Plantarla con cuidado en el sueño refleja que, aunque no veas avances inmediatos, el proceso ya comenzó.','¿Qué "semilla" plantaste recientemente que todavía no da frutos visibles, pero ya está en marcha?'],
  raiz:['Raíces (de planta)','Las raíces representan tu conexión con el pasado, la familia o los valores que te sostienen, incluso cuando no son visibles a simple vista.','Raíces dañadas en el sueño pueden simbolizar una base familiar o personal que sientes debilitada.','¿Qué tan firmes sientes, hoy, tus raíces más importantes?'],
  fruta:['Fruta','La fruta representa el resultado de un esfuerzo sostenido: lo que finalmente puedes "cosechar" después de un proceso de cuidado y paciencia.','Fruta podrida en el sueño puede simbolizar una oportunidad que se dejó pasar por no haberla atendido a tiempo.','¿Qué esfuerzo sostenido sientes que por fin está listo para dar sus frutos?'],
  espina:['Espina','Una espina representa un dolor pequeño pero persistente: un comentario, situación o recuerdo que sigue molestando aunque parezca menor.','Sacarte una espina con éxito en el sueño simboliza alivio al resolver, por fin, algo que incomodaba desde hace tiempo.','¿Qué molestia pequeña pero persistente sientes que ya es momento de resolver?'],
  cactus:['Cactus','El cactus simboliza resistencia en condiciones difíciles y, a la vez, una forma de protegerte con espinas que puede alejar a quienes se acercan con buenas intenciones.','Puede reflejar la necesidad de suavizar un poco tus defensas con quienes realmente buscan acercarse de forma genuina.','¿Hay alguien con buenas intenciones de quien, sin querer, te estás protegiendo demasiado?'],
  hongo:['Hongo / seta','Un hongo representa crecimiento rápido e inesperado, a veces surgido en condiciones que parecían poco favorables (como la oscuridad o la humedad).','También puede simbolizar algo que crece "bajo la superficie" sin que te des cuenta del todo hasta que ya es visible.','¿Qué está creciendo en tu vida sin que lo hayas notado del todo hasta ahora?'],
  musgo:['Musgo','El musgo simboliza tiempo y permanencia: algo que ha estado presente durante mucho tiempo, de forma silenciosa, cubriendo lo que ya es antiguo.','Puede reflejar la acumulación lenta de una costumbre o hábito que ya forma parte natural de tu vida, para bien o para mal.','¿Qué hábito antiguo sientes que ya "cubrió" por completo una parte de tu rutina?'],
  pantano:['Pantano','El pantano representa una situación confusa y pegajosa de la que es difícil salir con rapidez, aunque tampoco implica un peligro inmediato como ahogarse.','Avanzar lentamente mientras te hundes un poco en el sueño refleja el esfuerzo real de salir de una situación estancada.','¿Qué situación sientes que avanza lento, como caminar en un pantano?'],
  oasis:['Oasis','Un oasis representa un alivio inesperado en medio de una etapa difícil: un respiro, apoyo o buena noticia en medio de la escasez.','Suele aparecer justo cuando, en la vida despierta, más necesitas un momento de descanso dentro de un periodo demandante.','¿Qué pequeño "oasis" has tenido recientemente en medio de una etapa demandante?'],
  faro:['Faro','El faro simboliza una guía confiable en medio de la incertidumbre: una persona, valor o certeza que te orienta cuando todo lo demás se siente confuso.','Verlo a la distancia, aunque no llegues a él, puede reflejar que la claridad está disponible aunque todavía no la alcances del todo.','¿Qué o quién ha sido tu "faro" en medio de la confusión reciente?'],
  acantilado:['Acantilado','Estar al borde de un acantilado simboliza sentirte frente a una decisión de alto riesgo, donde el siguiente paso se siente definitivo e irreversible.','Dudar antes de saltar o retroceder refleja justamente esa tensión entre el miedo y las ganas de dar un paso decisivo.','¿Qué decisión sientes que, una vez tomada, ya no tendría vuelta atrás?'],
  valle:['Valle','El valle representa un periodo de calma entre dos momentos más intensos (como entre dos montañas): un descanso necesario en medio de un proceso de esfuerzo.','Puede reflejar que, aunque no sientas grandes avances ahora mismo, estás en una pausa útil antes del siguiente ascenso.','¿Estás en un "valle" de descanso necesario entre dos etapas de mayor esfuerzo?'],
  volcan2:['Geiser / fuente termal','Un géiser o fuente de agua caliente representa energía interna que sale con fuerza mas de forma periódica y predecible, a diferencia del volcán, más descontrolado.','Puede simbolizar una emoción intensa que sabes que vas a sentir en ciertos momentos, y que ya aprendiste a anticipar.','¿Qué emoción intensa sientes que ya aprendiste a anticipar, aunque siga siendo fuerte cuando llega?'],
  roble:['Roble (árbol específico)','El roble simboliza fuerza duradera y resistencia construida con el tiempo, más que crecimiento rápido: representa solidez ganada con los años.','Puede aparecer como recordatorio de que cierta fortaleza tuya no se construyó de la noche a la mañana, y eso la hace más valiosa.','¿Qué fortaleza tuya reconoces que se construyó poco a poco, con los años?'],
  sauce:['Sauce llorón','El sauce simboliza flexibilidad emocional: la capacidad de doblarte ante la dificultad sin romperte del todo, incluso si por fuera parece un signo de tristeza.','Puede representar un duelo que, aunque visible, no te está quebrando, solo haciéndote más flexible.','¿Qué dificultad reciente te ha hecho más flexible, aunque también más sensible?'],
  palmera:['Palmera','La palmera simboliza resistencia con ligereza: se dobla con el viento fuerte sin quebrarse, representando adaptabilidad frente a presiones externas intensas.','Puede aparecer en periodos donde necesitas "doblarte" ante una circunstancia sin perder tu forma esencial.','¿Qué presión externa reciente requiere que te adaptes sin perder quién eres?'],
  girasol:['Girasol','El girasol representa la tendencia a orientarte hacia lo que te da energía y luz, dejando atrás lo que te resta vitalidad.','Puede reflejar hacia qué —o quién— estás "girando" naturalmente en busca de más energía positiva.','¿Hacia qué (persona, actividad) sientes que te "giras" naturalmente en busca de energía?'],
  rosa:['Rosa (flor)','La rosa simboliza amor, belleza y también la posibilidad de dolor si no se maneja con cuidado (sus espinas). Representa que lo valioso a veces requiere delicadeza.','Recibir una rosa en sueños puede señalar un gesto de cariño real que estás por recibir o que ya recibiste sin darle el peso que merecía.','¿Hay un gesto de cariño reciente al que no le diste el peso que merecía?'],
  lirio:['Lirio','El lirio se asocia tradicionalmente con pureza, renovación y, en algunas culturas, con el duelo y la despedida respetuosa de una etapa.','Puede aparecer en sueños donde estás procesando una pérdida con serenidad, en vez de resistencia.','¿Qué despedida estás procesando con más serenidad de la que esperabas?'],
  loto:['Flor de loto','La flor de loto simboliza crecimiento espiritual a partir de condiciones difíciles: florece limpia incluso saliendo del lodo, representando transformación desde la adversidad.','Suele aparecer en etapas donde una persona está encontrando claridad o paz justo después de un periodo difícil.','¿Qué claridad o paz reciente sientes que nació justo después de una etapa difícil?'],
  bambu:['Bambú','El bambú representa flexibilidad y resistencia a la vez: se dobla con facilidad pero rara vez se rompe, y crece rápido una vez que encuentra las condiciones adecuadas.','Puede reflejar un periodo de crecimiento acelerado después de una etapa donde sentías que nada avanzaba.','¿Sientes que, después de una pausa larga, finalmente estás creciendo más rápido en algo?'],
  colmena:['Colmena','La colmena representa organización colectiva y productividad compartida, donde cada parte cumple un rol específico para un bien mayor.','Puede señalar cómo te sientes dentro de un sistema (familia, trabajo) donde todos cumplen una función, incluida la tuya.','¿Qué rol específico sientes que cumples dentro de tu "colmena" (familia, equipo, comunidad)?'],
  telaraña:['Telaraña','Una telaraña representa una situación compleja tejida con cuidado —por ti o por otra persona— de la que puede ser difícil salir sin dañar algo en el proceso.','Quedar atrapado en ella puede reflejar sentirte enredado en compromisos que se fueron acumulando sin que lo planearas del todo.','¿En qué "telaraña" de compromisos sientes que te fuiste enredando sin planearlo?'],
  nido:['Nido','El nido representa el hogar que construyes con cuidado para proteger algo valioso: una familia, un proyecto o una parte vulnerable de ti mismo.','Un nido vacío puede simbolizar una etapa de transición, como cuando los hijos crecen o un proyecto importante concluye.','¿Qué "nido" construiste con cuidado y ahora está entrando en una nueva etapa?'],
  huevo:['Huevo','El huevo simboliza potencial todavía no desarrollado: una idea, proyecto o incluso una parte de tu personalidad que está en proceso de "incubarse" antes de mostrarse.','Romperlo con cuidado en el sueño puede señalar que estás listo para dejar salir algo que llevabas gestando en privado.','¿Qué llevas "incubando" en privado y sientes que está cerca de mostrarse?'],
  pluma:['Pluma (de ave)','Una pluma representa un mensaje ligero, una señal de que vas por buen camino, o el recuerdo de alguien que ya no está pero sigue presente simbólicamente.','Encontrar una pluma en el suelo del sueño suele tener, en muchas tradiciones, una lectura de consuelo y buena señal.','¿Hay alguna "señal" reciente, por pequeña que sea, que interpretaste como un buen augurio?'],
  concha:['Concha de mar','Una concha representa algo delicado protegido por una capa resistente: una emocion o vulnerabilidad que guardas bien cuidada dentro de ti.','Encontrarla vacía en la orilla puede simbolizar una etapa emocional que ya se cerró, dejando solo su huella.','¿Qué vulnerabilidad guardas bien protegida, aunque esté ahí dentro de ti?'],
  estrellademar:['Estrella de mar','La estrella de mar simboliza regeneración: su capacidad de regenerar partes perdidas representa tu propia capacidad de recuperarte después de una pérdida.','Puede aparecer como recordatorio de que, aunque algo se haya roto, tienes más capacidad de recuperación de la que crees.','¿Qué parte de ti se está regenerando después de una pérdida reciente?'],
  coral:['Coral (arrecife)','El arrecife de coral representa una comunidad diversa construida con el tiempo, donde muchas partes distintas sostienen un ecosistema más grande que cualquiera por separado.','Puede reflejar cómo valoras las comunidades (familiares, de amistad) que se construyeron poco a poco con el tiempo.','¿Qué comunidad construida con el tiempo valoras más de lo que sueles expresar?'],
  medusa:['Medusa (animal marino)','La medusa representa belleza con riesgo oculto: algo atractivo a primera vista que puede generar daño si te acercas sin precaución.','Puede simbolizar una persona o situación que te atrae pero que, en el fondo, sabes que requiere mantener cierta distancia prudente.','¿Hay algo atractivo en tu vida que, en el fondo, sabes que requiere más distancia prudente?'],
  langosta:['Langosta (crustáceo)','La langosta representa protección mediante una capa dura, similar al cangrejo, pero asociada también con momentos de celebración o lujo poco frecuente.','Puede aparecer en sueños relacionados con merecerte un disfrute especial después de un periodo de mucho esfuerzo.','¿Qué disfrute especial sientes que ya te has ganado, aunque no te lo hayas dado todavía?'],
  camaron:['Camarón','El camarón simboliza algo pequeño que, en conjunto con otros, forma parte de algo mayor: tu aporte individual dentro de un esfuerzo colectivo.','Puede reflejar la sensación de sentirte "pequeño" dentro de un proyecto grande, aunque tu parte sea igualmente valiosa.','¿Sientes que tu aporte, aunque parezca pequeño, es parte importante de algo mayor?'],
  marte:['Marte (planeta)','Soñar con el planeta Marte representa energía marcial: impulso, acción directa y, en ocasiones, un conflicto que sientes necesario enfrentar sin rodeos.','Puede aparecer en periodos donde necesitas más decisión y menos duda frente a una situación concreta.','¿Dónde necesitas actuar con más decisión y menos duda?'],
  saturno:['Saturno (planeta)','Saturno simboliza estructura, límites y responsabilidad a largo plazo: lo que exige disciplina y paciencia antes de dar resultados.','Puede señalar una etapa donde sientes el peso de compromisos serios que requieren constancia, no soluciones rápidas.','¿Qué compromiso serio requiere más paciencia y constancia de la que le estás dando?'],
  galaxia:['Galaxia / espacio exterior','El espacio exterior representa lo infinito y lo que escapa a tu comprensión inmediata: preguntas existenciales más grandes que cualquier conflicto cotidiano.','Flotar en el espacio con calma puede reflejar una aceptación serena frente a lo que no puedes controlar del todo.','¿Qué pregunta existencial, más grande que lo cotidiano, ha estado presente en tu mente?'],
  nave:['Nave espacial / OVNI','Una nave espacial representa una posibilidad completamente fuera de tu marco habitual de referencia: una idea, oportunidad o cambio de vida radicalmente distinto a lo conocido.','Subir a ella por voluntad propia puede simbolizar apertura genuina a una transformación grande en tu vida.','¿Qué cambio radicalmente distinto a lo conocido estarías dispuesto a considerar?'],
  robot:['Robot','Un robot simboliza una parte de ti que actúa de forma mecánica, sin conexión emocional real, muchas veces por exceso de rutina o agotamiento.','Puede señalar la necesidad de reconectar con tus emociones en algún área donde sientes que solo estás "cumpliendo funciones".','¿En qué área de tu vida sientes que estás funcionando como robot, sin verdadera conexión emocional?'],
  inteligenciaartificial:['Inteligencia artificial','Soñar con una inteligencia artificial representa la tensión entre lo racional-automático y lo genuinamente humano en una decisión que estás tomando.','Puede reflejar dudas sobre si estás decidiendo con el corazón o solo con la lógica en una situación importante.','¿Estás decidiendo esto más con la cabeza o con el corazón, y cuál necesitas escuchar más?'],
  bateria:['Batería descargada','Un dispositivo con la batería agotada en sueños refleja, casi literalmente, sentirte sin energía para sostener tus actividades actuales al mismo ritmo.','Es uno de los símbolos de agotamiento más directos de la vida moderna.','¿Qué necesitas para "recargar batería" antes de seguir al mismo ritmo?'],
  contraseña:['Olvidar una contraseña','Olvidar una contraseña o código de acceso representa sentirte bloqueado para acceder a algo que antes manejabas con facilidad: una habilidad, un recuerdo o una relación.','Puede señalar frustración por sentir que perdiste el "acceso" a una versión de ti mismo más segura.','¿A qué sientes que perdiste el "acceso" fácil que antes tenías?'],
  camara:['Cámara fotográfica','Una cámara que no funciona bien en sueños simboliza el miedo a no poder capturar o retener un momento importante antes de que se escape.','Tomar una foto perfecta en el sueño puede reflejar el deseo de preservar conscientemente una etapa feliz actual.','¿Qué momento actual te gustaría "retener" antes de que pase?'],
  micrófono:['Micrófono','Un micrófono representa la oportunidad —o la presión— de hacer que tu voz sea escuchada por muchos a la vez.','Que falle justo cuando vas a hablar puede reflejar miedo a no ser escuchado en un momento importante frente a otros.','¿En qué momento próximo sientes que necesitas que tu voz realmente se escuche?'],
  escenario:['Escenario (teatro)','Estar en un escenario frente a público representa sentirte expuesto y evaluado en una situación donde todos te están observando.','Olvidar tu papel en el escenario soñado es una variante directa del sueño de examen, aplicada a la exposición pública.','¿En qué situación próxima sientes que estarás "bajo los reflectores", evaluado por otros?'],
  publico:['Público (audiencia)','Una audiencia observándote representa la sensación de estar siendo juzgado en una decisión o actuación importante de tu vida.','Un público amigable versus uno hostil en el sueño suele reflejar directamente cuán segura te sientes de esa decisión.','¿Te sientes más apoyado o más juzgado en la decisión que estás tomando ahora?'],
  circo:['Circo','El circo representa una situación caótica pero, a la vez, cuidadosamente coordinada: muchas cosas pasando a la vez que, de algún modo, logran funcionar juntas.','Puede reflejar cómo te sientes manejando varias responsabilidades simultáneas sin que, hasta ahora, nada se haya caído.','¿Cómo logras, hasta ahora, que tantas responsabilidades simultáneas sigan funcionando juntas?'],
  acrobata:['Acróbata / equilibrista','Un acróbata en la cuerda floja representa el esfuerzo consciente de mantener el equilibrio entre varias áreas importantes de tu vida a la vez.','Caer de la cuerda en el sueño puede reflejar miedo a que ese equilibrio, por ahora frágil, se rompa pronto.','¿Qué áreas de tu vida sientes que mantienes en un equilibrio delicado ahora mismo?'],
  mago:['Mago / ilusionista','Un mago representa transformación aparentemente sin esfuerzo visible, o la sospecha de que algo "demasiado bueno" tiene truco detrás.','Puede señalar desconfianza hacia una solución que parece demasiado fácil para ser del todo real.','¿Hay alguna solución reciente que parece "demasiado fácil" y te genera algo de desconfianza?'],
  titere:['Títere / marioneta','Un títere representa sentir que alguien más controla tus decisiones, con hilos que no siempre reconoces del todo conscientemente.','Cortar los hilos del títere en el sueño puede simbolizar el deseo de recuperar autonomía en una situación donde te sientes manipulado.','¿En qué área sientes que alguien más está "moviendo los hilos" de tus decisiones?'],
  reloj2:['Reloj de arena','El reloj de arena, a diferencia del reloj digital, enfatiza que el tiempo se agota de forma visible y continua, no de golpe.','Puede reflejar la sensación de ver pasar una oportunidad poco a poco, sin que hayas actuado todavía.','¿Qué oportunidad sientes que se está agotando poco a poco mientras decides?'],
  calendario:['Calendario','Un calendario con una fecha marcada representa un compromiso o plazo que pesa en tu mente, consciente o inconscientemente.','Tachar días en el sueño puede simbolizar ansiedad por la cercanía de un evento importante que se aproxima.','¿Qué fecha próxima está pesando más de lo que admites conscientemente?'],
  despertador:['Despertador','Un despertador que no logras apagar simboliza una señal de alerta que tu mente no quiere seguir ignorando, aunque conscientemente prefieras posponerla.','También puede representar, literalmente, la necesidad real de ajustar tus horarios de sueño.','¿Qué "alarma" interna llevas tiempo posponiendo escuchar del todo?'],
  espejoroto:['Espejo roto (específico)','Un espejo que se rompe frente a ti simboliza un quiebre repentino en cómo te percibías a ti mismo, generalmente ligado a un evento reciente que cambió tu autoimagen.','A diferencia de ver un reflejo distinto, aquí el énfasis está en lo abrupto del cambio, no en su gradualidad.','¿Qué evento reciente cambió, de forma abrupta, cómo te ves a ti mismo?'],
  reflejo:['Ver un reflejo que no es tuyo','Ver en el espejo un reflejo que no te pertenece (otra cara, otra edad) representa una exploración profunda de identidad: quién eras, quién eres o quién temes convertirte.','Suele generar inquietud precisamente porque toca una pregunta identitaria central.','¿Qué versión de ti mismo —pasada o futura— sientes que está intentando mostrarse?'],
  sombra:['Tu propia sombra','Ver tu propia sombra comportándose distinto a ti representa, en términos junguianos, confrontar partes de ti mismo que normalmente mantienes ocultas o reprimidas.','Es uno de los símbolos psicológicos más estudiados: la "sombra" junguiana es justamente lo que rechazamos de nosotros mismos.','¿Qué parte de ti mismo sueles mantener oculta, incluso de ti mismo?'],
  gemelo:['Doble de ti mismo (sosias)','Encontrarte con un doble idéntico a ti representa una confrontación directa con una parte de tu personalidad que percibes como separada o en conflicto contigo mismo.','Llevarte bien o mal con ese doble en el sueño refleja qué tan integradas sientes tus propias contradicciones internas.','¿Qué contradicción interna sientes que todavía no logras integrar del todo?'],
  voznotuya:['Hablar con una voz que no es tuya','Escucharte hablar con una voz distinta a la tuya en un sueño representa decir algo que no sientes del todo auténtico, quizás repitiendo palabras ajenas como propias.','Puede señalar una situación donde sientes que no estás siendo del todo genuino en lo que expresas.','¿Hay algo que dices con frecuencia que, en el fondo, sientes que no es del todo tuyo?'],
  edadmayor:['Verte mucho más viejo','Verte a ti mismo mucho más viejo de lo que eres representa preocupación por el paso del tiempo o el deseo de tener ya la sabiduría de una etapa futura.','Puede reflejar impaciencia por llegar a una versión de ti mismo que sientes más resuelta y segura.','¿Qué sabiduría de una etapa futura desearías tener ya disponible ahora mismo?'],
  edadmenor:['Verte mucho más joven / niño','Verte como un niño dentro del sueño representa una necesidad de volver a una emoción más pura o sin las cargas que has ido acumulando con la edad.','También puede señalar el deseo de recuperar la curiosidad o la libertad de esa etapa.','¿Qué cualidad de tu niñez te gustaría recuperar, aunque sea un poco?'],
  amigoimaginario:['Amigo imaginario (reaparece)','Que reaparezca un amigo imaginario de la infancia en un sueño adulto representa la necesidad de reconectar con una parte creativa o lúdica que dejaste de lado con el tiempo.','Puede ser una señal amable de que necesitas más espacio para el juego o la imaginación en tu vida actual.','¿Hace cuánto no te das permiso para algo puramente lúdico o imaginativo?'],
  juguete:['Juguete de la infancia','Un juguete específico de tu infancia que reaparece en sueños representa un recuerdo emocional concreto ligado a esa etapa, muchas veces de seguridad o simplicidad.','Puede señalar nostalgia por una época donde las preocupaciones eran menos complejas que ahora.','¿Qué de esa etapa más simple extrañas, aunque sepas que no puedes volver a ella del todo?'],
  columpio:['Columpio','Un columpio representa el vaivén entre dos estados: avance y retroceso, alegría y vértigo, en una misma experiencia emocional.','Puede reflejar una situación donde sientes que oscilas entre dos sentimientos opuestos sin terminar de decidirte por uno.','¿Entre qué dos sentimientos sientes que oscilas sin decidirte del todo?'],
  resbaladero:['Resbaladilla / tobogán','Un tobogán representa una situación que avanza rápido y con poco esfuerzo propio, para bien (diversión) o para mal (pérdida de control), según el tono del sueño.','Puede reflejar cómo te sientes frente a una decisión que avanza más rápido de lo que esperabas, con o sin tu control activo.','¿Sientes que una situación reciente avanzó "cuesta abajo" más rápido de lo que esperabas?'],
  parqueinfantil:['Parque infantil','Un parque infantil en sueños representa la necesidad de reconectar con la alegría espontánea, sin la presión de la productividad adulta constante.','Verlo vacío puede simbolizar la sensación de haber perdido ese espacio de disfrute sin presión en tu rutina actual.','¿Cuándo fue la última vez que disfrutaste algo sin ninguna presión de productividad?'],
  feria:['Feria / parque de atracciones','Una feria simboliza intensidad emocional condensada: muchas sensaciones fuertes en poco tiempo, entre la emoción y el vértigo.','Perderte en una feria concurrida puede reflejar sentirte abrumado por demasiados estímulos o decisiones a la vez.','¿Sientes que tienes demasiados estímulos o decisiones encima en este momento?'],
  montañarusa:['Montaña rusa','La montaña rusa representa altibajos emocionales intensos que, aunque no siempre cómodos, forman parte de un proceso que ya decidiste —consciente o inconscientemente— atravesar.','Disfrutarla versus tenerle pánico suele reflejar qué tan preparado te sientes para los altibajos actuales de tu vida.','¿Qué tan preparado te sientes para los altibajos actuales que estás viviendo?'],
  castillo:['Castillo','Un castillo representa aspiraciones grandes, protección reforzada o, en ocasiones, una distancia emocional autoimpuesta frente a los demás ("vivir en una torre").','Sentirte solo dentro de un castillo grande puede reflejar éxito material acompañado de soledad emocional.','¿Hay algún logro reciente que, aunque grande, se siente también un poco solitario?'],
  torre:['Torre','Una torre alta simboliza ambición y perspectiva, pero también aislamiento si te alejas demasiado de los demás para alcanzarla.','Subir una torre con esfuerzo representa el camino hacia una meta ambiciosa que requiere paciencia y cierto grado de soledad en el proceso.','¿Qué meta ambiciosa estás persiguiendo, aunque el camino se sienta solitario?'],
  mazmorra:['Mazmorra / calabozo','Una mazmorra representa una parte muy antigua y oscura de tu historia personal, generalmente ligada a un miedo o herida de hace mucho tiempo.','A diferencia del sótano, la mazmorra sugiere algo más severo: un encierro impuesto, no solo guardado voluntariamente.','¿Qué herida antigua sientes que sigue "encerrada" sin haber sido realmente procesada?'],
  tunel:['Túnel','Un túnel representa un proceso de transición incómodo pero con un final visible: sabes que hay luz al otro lado, aunque el trayecto se sienta oscuro.','Es uno de los símbolos con lectura más alentadora a pesar de su apariencia inquietante: casi siempre implica que hay salida.','¿Qué proceso incómodo estás atravesando, sabiendo que tiene un final a la vista?'],
  cripta:['Cripta','Una cripta representa recuerdos muy antiguos, casi ancestrales, que pesan más por tradición familiar que por experiencia personal directa.','Puede señalar patrones heredados de generaciones anteriores que todavía influyen en tus decisiones actuales.','¿Qué patrón familiar heredado sientes que todavía influye en tus decisiones?'],
  altar:['Altar','Un altar representa aquello a lo que le das un valor casi sagrado en tu vida: una persona, un proyecto o un principio que pones por encima de lo demás.','Puede ser útil revisar si eso que "está en tu altar" sigue mereciendo ese lugar de prioridad absoluta.','¿Qué tienes "en tu altar" actualmente, y sigue mereciendo ese lugar de prioridad?'],
  campana:['Campana','Una campana que suena representa un llamado de atención importante: algo que necesita ser notado ahora, no después.','Ignorarla en el sueño puede reflejar que, en la vida real, también estás posponiendo atender una señal clara.','¿Qué "campana" has estado ignorando, aunque sabes que suena por una buena razón?'],
  vela:['Vela (de cera)','Una vela encendida representa esperanza y guía en medio de la incertidumbre, aunque su luz sea pequeña comparada con la oscuridad alrededor.','Que se apague inesperadamente puede simbolizar miedo a perder una fuente de esperanza o apoyo que sentías constante.','¿Qué pequeña fuente de esperanza sientes que necesitas proteger de que se apague?'],
  incienso:['Incienso','El incienso representa purificación consciente de un espacio o de un estado de ánimo, un ritual de transición entre una emoción y otra.','Puede reflejar el deseo activo de "limpiar" el ambiente emocional antes de enfrentar algo nuevo.','¿Qué necesitas "limpiar" emocionalmente antes de enfrentar tu próximo paso?'],
  ofrenda:['Ofrenda','Una ofrenda representa gratitud, respeto o el deseo de honrar algo o a alguien importante, incluso si ya no está físicamente presente.','Puede señalar una necesidad de cerrar, con un gesto consciente, algo que sientes pendiente de agradecer o despedir.','¿A quién o qué te gustaría honrar con un gesto consciente de agradecimiento?'],
  procesion:['Procesión / desfile','Una procesión representa un proceso colectivo compartido con otros hacia una misma meta o creencia, con un sentido de propósito común.','Sentirte fuera de la procesión puede reflejar distancia respecto a una creencia o valor que tu entorno comparte pero tú cuestionas.','¿Hay alguna creencia compartida por tu entorno que, en el fondo, estás empezando a cuestionar?'],
  mascarabaile:['Máscara de fiesta / disfraz','Un disfraz en una fiesta representa una identidad temporal que te permites probar, sin el compromiso de que sea permanente.','Puede reflejar curiosidad sana por explorar una faceta de ti mismo que normalmente no muestras.','¿Qué faceta tuya te gustaría "probarte" un rato, sin compromiso de que sea definitiva?'],
  espejismo:['Espejismo','Un espejismo representa una expectativa que, al acercarte, se revela distinta —o inexistente— de como la imaginaste desde lejos.','Puede señalar la necesidad de revisar si una meta actual es tan sólida como parece a primera vista.','¿Hay alguna meta que, al acercarte más, sientes que no es exactamente lo que imaginabas?'],
  reflejoagua:['Reflejo en el agua','Ver tu reflejo en el agua, a diferencia del espejo, representa una autoimagen más fluida y cambiante, sujeta al estado emocional del momento.','Un reflejo distorsionado por el movimiento del agua puede señalar que tu autopercepción actual está más influida por tus emociones que de costumbre.','¿Sientes que tu forma de verte a ti mismo cambia mucho según tu estado de ánimo del día?'],
  burbuja:['Burbuja','Una burbuja representa una protección frágil y temporal: te sientes a salvo dentro de ella, aunque sabes que puede romperse con facilidad.','Puede reflejar una zona de confort que, aunque cómoda, sabes que no es sostenible de forma permanente.','¿Qué "burbuja" cómoda sabes que tarde o temprano vas a necesitar dejar atrás?'],
  espuma:['Espuma (de mar u olas)','La espuma representa la parte más superficial y pasajera de una emoción intensa: lo que queda visible después de que la fuerza principal ya pasó.','Puede señalar que estás procesando los "restos" de una emoción fuerte que ya vivió su momento más intenso.','¿Qué emoción intensa sientes que ya pasó su pico, aunque todavía queden restos de ella?'],
  marea:['Marea (alta o baja)','La marea representa ciclos naturales de intensidad emocional: periodos donde sientes más y periodos donde sientes menos, ambos igual de válidos y temporales.','Una marea muy alta inesperada puede simbolizar una emoción que llegó con más fuerza de la que anticipabas.','¿En qué "marea" emocional sientes que estás ahora: alta, baja, o en transición?'],
  corriente:['Corriente (de agua o aire)','Una corriente fuerte que te arrastra representa circunstancias que sientes que avanzan más rápido de lo que puedes decidir por ti mismo.','Nadar a favor de la corriente, en cambio, simboliza aceptación y fluidez frente a un cambio que no puedes controlar del todo.','¿Te estás resistiendo a una corriente que, quizás, sería más fácil acompañar?'],
  bosquequemado:['Bosque quemado','Un bosque quemado representa un proceso difícil que, aunque doloroso, despeja el terreno para un crecimiento distinto y más fuerte en el futuro.','En la naturaleza real, el fuego forestal a veces es necesario para que nazcan nuevas semillas: la lectura simbólica sigue esa misma lógica.','¿Qué proceso doloroso reciente sientes que, con el tiempo, podría abrir paso a algo nuevo?'],
  jardinsecreto:['Jardín secreto / escondido','Descubrir un jardín oculto representa encontrar una parte de ti mismo —un talento, un deseo— que mantenías guardada incluso de ti mismo.','A diferencia del jardín habitual que ya conoces, este simboliza un hallazgo sorpresivo y personal.','¿Qué parte de ti mismo descubriste recientemente que no sabías que tenías?'],
  invernadero:['Invernadero','Un invernadero representa un espacio protegido donde algo delicado puede crecer sin las presiones habituales del entorno exterior.','Puede reflejar la necesidad de crear condiciones especiales —más paciencia, menos exigencia— para que un proyecto delicado prospere.','¿Qué proyecto necesita un ambiente más protegido para poder desarrollarse bien?'],
  vinedo:['Viñedo','Un viñedo representa un proceso de maduración lenta que, con paciencia, produce algo de calidad superior a lo inmediato.','Puede señalar que una situación actual necesita tiempo de maduración antes de dar su mejor resultado.','¿Qué área de tu vida necesita más tiempo de "maduración" antes de dar su mejor resultado?'],
  trigo:['Campo de trigo','Un campo de trigo representa abundancia colectiva y el resultado de un esfuerzo sostenido a lo largo de una temporada completa, no de un solo día.','Puede reflejar satisfacción por un proceso largo que finalmente está llegando a su cosecha.','¿Qué proceso largo sientes que finalmente está llegando a su momento de cosecha?'],
  arrozal:['Arrozal / campo inundado','Un campo de cultivo inundado representa el equilibrio delicado entre dos elementos —agua y tierra, emoción y acción— necesario para que algo crezca bien.','Puede señalar que una situación actual requiere ese mismo balance entre sentir y actuar, sin que domine solo uno de los dos.','¿Sientes que estás equilibrando bien la emoción y la acción en una situación actual?'],
  desiertoflorido:['Desierto en flor','Un desierto que florece de pronto representa una sorpresa positiva después de un periodo de sequía emocional prolongada: algo bueno que llega justo cuando menos lo esperabas.','Es uno de los símbolos más alentadores dentro del repertorio de paisajes áridos.','¿Qué sorpresa positiva reciente llegó justo después de un periodo que sentías "seco"?'],
  iceberg:['Iceberg','Un iceberg representa que solo una parte pequeña de una situación es visible, mientras la mayor parte permanece oculta bajo la superficie.','Puede señalar que un conflicto que parece menor en realidad tiene raíces mucho más profundas de lo que se ve a simple vista.','¿Qué situación parece "pequeña" por fuera pero sientes que tiene mucho más debajo de la superficie?'],
  glaciar:['Glaciar','Un glaciar representa algo que cambia de forma extremadamente lenta: una actitud, relación o patrón que lleva mucho tiempo sin moverse, aunque en el fondo sí avance.','Verlo derretirse puede simbolizar que, después de mucho tiempo, algo rígido finalmente empieza a moverse.','¿Qué situación "congelada" desde hace mucho tiempo sientes que, por fin, empieza a moverse?'],
  avalancha:['Avalancha','Una avalancha representa una acumulación de pequeñas tensiones que, de pronto, se desprenden todas juntas y de forma arrolladora.','A diferencia del terremoto (base que falla), la avalancha simboliza algo que se venía acumulando poco a poco antes de caer de golpe.','¿Qué pequeñas tensiones sientes que se han ido acumulando y podrían "caer juntas" pronto?'],
  relampago:['Relámpago (sin trueno)','Ver un relámpago sin escuchar el trueno representa una advertencia visual que llega antes de que sientas por completo el impacto emocional de una situación.','Puede señalar que percibiste una señal de alerta antes de que el problema se manifestara del todo.','¿Captaste alguna señal de alerta temprana que, en su momento, no le diste suficiente peso?'],
  arcoirisdoble:['Arcoíris doble','Un arcoíris doble intensifica el símbolo original: una señal de esperanza reforzada, muchas veces asociada con una buena noticia que confirma otra anterior.','Puede reflejar que dos señales positivas recientes, juntas, te están dando más confianza de la que admites.','¿Qué dos buenas señales recientes, juntas, te están dando más confianza de la que reconoces?'],
  estanque:['Estanque','Un estanque representa un espacio emocional pequeño y manejable, a diferencia del mar o el lago: emociones contenidas en un entorno que sí puedes abarcar del todo.','Puede señalar una situación emocional que, aunque presente, se siente manejable y no desbordante.','¿Qué emoción actual, aunque presente, sientes que todavía es manejable?'],
  fuentedeagua:['Fuente de agua (ornamental)','Una fuente decorativa representa emociones que fluyen de forma controlada y hasta estética: sentimientos que expresas con cierta elegancia, no de forma caótica.','Puede reflejar que has encontrado una forma saludable de canalizar una emoción que antes se sentía más desbordante.','¿Qué emoción has aprendido a expresar de forma más controlada y sana que antes?'],
  pozo:['Pozo','Un pozo representa acceso a recursos internos profundos: lo que necesitas puede estar disponible, pero requiere esfuerzo llegar hasta ahí.','Un pozo seco, en cambio, puede simbolizar sentir que un recurso que antes tenías disponible (energía, paciencia) ya se agotó por ahora.','¿Qué recurso interno sientes que necesitas esforzarte más para alcanzar en este momento?'],
  cataratas:['Cataratas (grandes)','Unas cataratas representan una fuerza emocional abrumadora pero también hermosa: intensidad que, aunque imponente, no necesariamente es peligrosa si la observas desde un lugar seguro.','Puede reflejar admiración y temor simultáneos frente a una emoción muy intensa que estás presenciando, propia o ajena.','¿Qué emoción intensa, propia o de alguien cercano, te genera a la vez respeto y algo de temor?'],
  arenamovediza:['Arenas movedizas','Las arenas movedizas representan una situación donde, mientras más esfuerzo haces por salir solo con fuerza, más te hundes: necesitas un enfoque distinto, no solo más esfuerzo.','Suele aparecer cuando una estrategia habitual ya no está funcionando y sigues insistiendo en la misma.','¿Qué situación necesita un enfoque distinto, en vez de simplemente más esfuerzo del mismo tipo?'],
  desfiladero:['Desfiladero / cañón','Un desfiladero representa un camino estrecho entre dos límites altos: una decisión con pocas opciones de desviación, donde debes avanzar con precisión.','Puede reflejar una situación actual donde sientes que el margen de error es más reducido de lo habitual.','¿En qué decisión sientes que tienes menos margen de error del que te gustaría?'],
  selva:['Selva (jungla)','La selva representa un entorno denso, vivo y a la vez desafiante: muchas posibilidades de crecimiento conviviendo con riesgos que no siempre ves con claridad.','A diferencia del bosque —exploración interior más tranquila—, la selva implica mayor intensidad y menor previsibilidad.','¿Qué área de tu vida se siente como una selva: llena de potencial, pero también de incertidumbre?'],
  sabana:['Sabana (paisaje)','La sabana representa amplitud y visibilidad: una etapa donde puedes ver con claridad lo que viene, sin sorpresas ocultas como en un bosque denso.','Puede reflejar una sensación actual de mayor claridad y perspectiva sobre tu situación de vida en general.','¿En qué área sientes, por fin, más claridad y visibilidad sobre lo que viene?'],
  tundra:['Tundra','La tundra representa un periodo de vida austero pero con una belleza particular: pocas distracciones, enfoque en lo esencial, aunque el ambiente se sienta frío.','Puede señalar una etapa de simplificación consciente, donde estás dejando de lado lo superfluo.','¿Qué estás simplificando conscientemente en tu vida últimamente?'],
  arrecife:['Arrecife (rocoso, peligro)','Un arrecife bajo la superficie del agua representa un peligro oculto que podría dañar un plan que, desde la superficie, parece ir bien.','Puede ser una señal de precaución frente a un riesgo que, aunque no visible todavía, conviene anticipar.','¿Hay algún riesgo oculto que convendría anticipar antes de que un plan avance más?'],
  bahia:['Bahía','Una bahía representa un refugio emocional parcial: más protegido que el mar abierto, pero todavía conectado a él, sin aislarte por completo.','Puede reflejar un espacio de descanso que no implica desconexión total de tu vida emocional más amplia.','¿Dónde encuentras ese "refugio parcial" que te da descanso sin desconectarte del todo?'],
  peninsula:['Península','Una península representa una posición intermedia: conectada a lo conocido, pero también adentrándote en terreno nuevo rodeado de incertidumbre.','Puede señalar una etapa donde mantienes un pie en lo seguro mientras exploras algo distinto.','¿En qué estás "explorando terreno nuevo" sin soltar del todo lo conocido?'],
  archipielago:['Archipiélago (islas)','Un archipiélago representa varias partes de tu vida que, aunque parecen separadas, están conectadas por debajo de la superficie (como islas sobre el mismo fondo marino).','Puede reflejar que áreas de tu vida que sientes desconectadas en realidad comparten una misma raíz.','¿Qué áreas de tu vida, aunque parezcan separadas, sientes que en el fondo están conectadas?'],
  meseta:['Meseta','Una meseta representa una etapa de estabilidad después de un ascenso importante: ya no subes con esfuerzo, pero tampoco avanzas mucho más por ahora.','Puede señalar una pausa merecida después de un logro, antes de decidir el siguiente objetivo.','¿Estás en una "meseta" merecida después de un logro, antes de decidir tu siguiente meta?'],
  pradera:['Pradera','Una pradera abierta representa libertad sin obstáculos inmediatos: un momento de tu vida con menos restricciones de las habituales.','Correr libremente por una pradera en sueños suele reflejar una sensación real de alivio reciente frente a una presión que se levantó.','¿Qué presión reciente se levantó, dándote una sensación de mayor libertad?'],
  oasisnocturno:['Luciérnagas','Ver luciérnagas representa pequeñas señales de esperanza visibles solo en medio de la oscuridad: detalles buenos que solo se notan cuando las cosas están más difíciles.','Puede reflejar tu capacidad de encontrar algo positivo incluso en medio de una etapa complicada.','¿Qué pequeña "luz" has sabido encontrar en medio de una etapa complicada?'],
  telarañarota:['Telaraña rota','Una telaraña rota, a diferencia de estar atrapado en ella, representa haber logrado salir de una situación enredada que te limitaba antes.','Puede señalar alivio reciente por haber roto un patrón o compromiso que te tenía atrapado.','¿De qué "enredo" reciente sientes alivio por haber podido salir?'],
  plumablanca:['Pluma blanca','Una pluma blanca, en muchas tradiciones, representa un mensaje de paz o la presencia simbólica de alguien que ya no está pero sigue cuidándote de alguna forma.','Suele traer una sensación de consuelo más que de inquietud, incluso en sueños relacionados con el duelo.','¿Sientes la presencia simbólica de alguien que ya no está, cuidándote de alguna forma?'],
  cuervoblanco:['Ave blanca grande (cisne, garza)','Un ave blanca grande representa pureza de intención y un mensaje de calma que llega en un momento de mucho ruido mental.','Verla volar con tranquilidad suele reflejar la posibilidad de encontrar paz en medio de una situación que hasta ahora se sentía tensa.','¿Qué necesitarías para encontrar algo de paz en medio de la situación que más te tensiona ahora?'],
  serpientedoscabezas:['Serpiente con dos cabezas','Una serpiente con dos cabezas representa una decisión donde sientes que dos caminos de transformación compiten entre sí, generando indecisión.','Puede señalar que no se trata de elegir "correcto o incorrecto", sino de aceptar que ambos caminos implican cambio real.','¿Entre qué dos caminos de cambio sientes que estás decidiendo ahora mismo?'],
  lobosolitario:['Lobo solitario','Un lobo solitario, separado de la manada, representa una etapa de independencia consciente, elegida por necesidad de espacio propio más que por rechazo social.','Puede reflejar que, por ahora, necesitas procesar algo en soledad antes de reintegrarte del todo a tu grupo habitual.','¿Qué necesitas procesar en soledad antes de volver a sentirte parte del grupo?'],
  manadadeleones:['Manada (de leones u otros)','Una manada representa pertenencia y jerarquía dentro de un grupo: tu rol, protección y also las dinámicas de poder que vives dentro de él.','Sentirte protegido o amenazado por la manada refleja directamente cómo percibes tu posición dentro de un grupo importante de tu vida.','¿Cómo describirías tu rol actual dentro de los grupos más importantes de tu vida?'],
  caballoalado:['Caballo alado (Pegaso)','Un caballo alado representa la combinación de fuerza vital con libertad de pensamiento: energía que no solo avanza, sino que también se eleva e inspira.','Puede señalar un momento donde sientes que tu energía y tu creatividad están alineadas de forma poco habitual.','¿Sientes que, en este momento, tu energía y tu creatividad están más alineadas de lo usual?'],
  fenix:['Fénix (ave mítica)','El fénix representa renacimiento total después de una destrucción completa: no solo cambio, sino un resurgir más fuerte de lo que había antes.','Es uno de los símbolos de transformación más intensos: implica que algo tuvo que terminar por completo para que lo nuevo pudiera nacer.','¿Qué parte de ti sientes que "resurgió" después de que algo tuvo que terminar del todo?'],
  esfinge:['Esfinge','La esfinge representa un enigma que exige ser resuelto antes de poder avanzar: una pregunta importante de tu vida que necesita una respuesta honesta.','Puede señalar que hay una pregunta central que llevas tiempo evitando responderte con claridad.','¿Qué pregunta importante de tu vida llevas tiempo evitando responder con honestidad?'],
  centauro:['Centauro','El centauro representa la integración entre instinto (cuerpo de animal) y razón (torso humano): equilibrio entre lo impulsivo y lo reflexivo dentro de ti.','Puede señalar un momento donde estás logrando integrar mejor tus impulsos con tu capacidad de pensar antes de actuar.','¿Sientes que estás logrando un mejor equilibrio entre impulso y reflexión últimamente?'],
  minotauro:['Minotauro','El minotauro representa un instinto o emoción intensa, atrapada en el centro de un laberinto interno de pensamientos complejos.','Puede señalar una emoción fuerte (ira, deseo) que mantienes "encerrada" en el centro de una situación difícil de resolver del todo.','¿Qué emoción intensa sientes que mantienes "encerrada" en el centro de un conflicto complicado?'],
  hadas:['Hada / ser feérico','Un hada representa magia cotidiana: la capacidad de ver posibilidad y belleza en los detalles pequeños de la vida diaria.','Puede reflejar un momento de mayor conexión con tu lado más lúdico, imaginativo o esperanzado de lo habitual.','¿Qué pequeño detalle reciente te hizo ver algo de "magia" en tu día a día?'],
  duende:['Duende / gnomo','Un duende representa travesura, ingenio o, en ocasiones, pequeños contratiempos inesperados que, aunque molestos, no son realmente graves.','Puede señalar una serie de pequeñas complicaciones recientes que, vistas con humor, no son tan graves como parecen.','¿Qué pequeño contratiempo reciente podrías empezar a ver con más humor?'],
  ogro:['Ogro / gigante','Un ogro o gigante representa un miedo o figura de autoridad que percibes desproporcionadamente grande comparado con tu propia fuerza percibida.','Enfrentarlo con éxito en el sueño puede reflejar que estás ganando confianza frente a algo que antes se sentía abrumador.','¿Qué desafío que antes se sentía "gigante" empieza a sentirse más manejable?'],
  trol:['Trol (criatura)','Un trol representa un obstáculo que parece amenazante a primera vista, pero que muchas veces se resuelve con ingenio más que con fuerza directa.','Puede señalar que una situación difícil tiene una solución más creativa de lo que parece a simple vista.','¿Qué obstáculo reciente podría resolverse con más ingenio que con fuerza bruta?'],
  genio:['Genio (de la lámpara)','Un genio que concede deseos representa el contacto directo con tus propios deseos más auténticos, antes de filtrarlos por lo que "deberías" querer.','Si en el sueño dudas qué pedir, puede reflejar que no tienes del todo claro cuál es tu deseo más genuino en este momento.','Si pudieras pedir un deseo ahora mismo sin pensarlo de más, ¿cuál sería?'],
  oraculo:['Oráculo / adivino','Consultar a un oráculo en sueños representa la búsqueda activa de claridad sobre un futuro incierto, y el deseo de que alguien más confirme lo que ya intuyes.','Puede señalar que, en el fondo, ya tienes una corazonada sobre el resultado de algo, aunque busques confirmación externa.','¿Qué corazonada tienes sobre un resultado futuro, aunque busques que alguien más la confirme?'],
  talisman:['Talismán / amuleto','Un talismán representa la necesidad de sentirte protegido frente a algo incierto, incluso si racionalmente sabes que el objeto en sí no cambia el resultado.','Puede reflejar un ritual personal —objeto, frase, costumbre— que te da seguridad frente a situaciones que no controlas del todo.','¿Qué "ritual" personal usas para sentirte más seguro frente a lo incierto?'],
  pocion:['Poción / elixir','Una poción representa una solución transformadora que esperas resuelva algo de forma casi mágica, sin el proceso gradual habitual.','Puede señalar el deseo de un atajo frente a un problema que, en el fondo, sabes que requiere tiempo y esfuerzo real.','¿Hay algún "atajo mágico" que desearías para algo que, en el fondo, sabes que toma tiempo?'],
  pergamino:['Pergamino / documento antiguo','Un pergamino antiguo representa conocimiento o acuerdos heredados: reglas no escritas que vienen de generaciones anteriores y siguen influyendo en ti.','Puede señalar una tradición familiar o cultural que estás revisando si todavía tiene sentido seguir honrando igual.','¿Qué regla heredada de tu familia o cultura estás empezando a cuestionar?'],
  cristalbola:['Bola de cristal','Una bola de cristal representa el deseo de certeza total sobre el futuro, algo que la vida rara vez ofrece, generando ansiedad por lo desconocido.','Puede reflejar que estás pidiéndote a ti mismo más certeza de la que es razonable tener en esta etapa.','¿Te estás exigiendo más certeza de la que realmente es posible tener ahora mismo?'],
  runas:['Runas (símbolos antiguos)','Las runas representan sabiduría simbólica que requiere interpretación activa: mensajes que no son obvios a primera vista, pero sí tienen sentido si te detienes a mirarlos.','Puede señalar que una situación actual tiene más significado del que has notado a primera vista.','¿Qué situación reciente podría tener más significado del que le has dado a primera vista?'],
  brujula:['Brújula','Una brújula representa la búsqueda de dirección clara en medio de la incertidumbre: necesitas saber hacia dónde ir, más que qué tan rápido llegar.','Una brújula que gira sin fijarse en un punto puede reflejar que todavía no tienes claro cuál es tu verdadero norte en este momento.','¿Tienes claro tu "norte" actual, o sientes que la brújula sigue girando?'],
  sextante:['Instrumento de navegación antiguo','Un instrumento de navegación antiguo representa orientarte con herramientas propias y probadas, en vez de depender de sistemas externos modernos.','Puede señalar confianza en tu propio criterio, incluso cuando otros usan métodos distintos para decidir.','¿Confías en tu propio criterio, aunque otros usen métodos distintos para decidir?'],
  ancla:['Ancla','Un ancla representa estabilidad y la decisión consciente de detenerte en un lugar, en vez de seguir avanzando sin rumbo fijo.','Puede reflejar una relación, valor o rutina que usas como punto fijo cuando todo lo demás se siente en movimiento.','¿Qué usas como "ancla" cuando todo lo demás se siente inestable?'],
  remo:['Remo','Un remo representa esfuerzo propio y directo para avanzar, sin depender de un motor o fuerza externa: tu propio impulso es el que mueve la situación.','Remar en círculos puede simbolizar esfuerzo real que, sin embargo, no está llevándote a ningún destino concreto todavía.','¿Sientes que estás poniendo esfuerzo real, aunque todavía no veas hacia dónde te lleva?'],
  vela2:['Vela de barco','Una vela de barco representa aprovechar las condiciones externas (el viento) en lugar de forzar el avance solo con esfuerzo propio.','Puede señalar el momento de dejarte ayudar por circunstancias favorables, en vez de insistir en hacerlo todo tú solo.','¿Hay alguna "corriente favorable" actual que podrías aprovechar en vez de forzar todo con esfuerzo propio?'],
  timon:['Timón','El timón representa quién tiene el control real de la dirección de una situación, incluso si otros están remando o aportando esfuerzo.','Sostenerlo con firmeza en el sueño refleja sentirte, por fin, al mando de una decisión importante.','¿Sientes que tienes el "timón" de la decisión más importante de tu vida en este momento?'],
  brasas:['Brasas (fuego que se apaga)','Brasas que todavía arden, aunque sin llama visible, representan una pasión o conflicto que no ha terminado del todo, aunque parezca haberse calmado por fuera.','Puede señalar que algo que creías resuelto todavía tiene energía residual que podría reavivarse.','¿Hay algo que creías resuelto pero que, en el fondo, todavía tiene "brasas" activas?'],
  chispas:['Chispas','Las chispas representan el inicio de algo —una idea, una atracción, un conflicto— antes de que se convierta en algo más grande y definido.','Puede señalar el comienzo de una situación que todavía está en una etapa muy temprana para saber hacia dónde va.','¿Qué "chispa" reciente sientes que podría convertirse en algo más grande?'],
  hornoardiendo:['Horno (de cocina)','Un horno representa un proceso de transformación que requiere tiempo y calor sostenido: algo que no se puede apresurar sin arruinar el resultado.','Puede señalar que un proyecto actual necesita el tiempo justo de "cocción" antes de mostrarse al mundo.','¿Qué proyecto necesita todavía su tiempo de "cocción" antes de estar listo para mostrarse?'],
  chimenea:['Chimenea','Una chimenea representa calidez compartida en un espacio íntimo y seguro: el calor emocional de un hogar, literal o simbólico.','Puede reflejar la importancia actual de un espacio donde te sientes genuinamente cómodo y acompañado.','¿Dónde encuentras ese espacio de calidez genuina que representa una chimenea encendida?'],
  pozodeagua:['Pozo de los deseos','Un pozo de los deseos representa la costumbre de depositar esperanzas concretas en algo externo, confiando en que el universo o el destino responda.','Puede señalar un deseo específico que llevas tiempo guardando sin decirlo en voz alta a nadie.','Si lanzaras una moneda a ese pozo ahora mismo, ¿qué desearías sin pensarlo de más?'],
  vitral:['Vitral (vidrio de colores)','Un vitral representa cómo la luz —la claridad— se transforma al pasar por tus propias experiencias y matices personales, dando un color único a cómo ves las cosas.','Puede reflejar que tu forma particular de ver una situación, aunque distinta a la de otros, es igual de válida.','¿Qué "color" único le das tú a una situación que otros ven de forma distinta?'],
  campanario:['Campanario','Un campanario representa un punto de referencia visible desde lejos: algo en tu vida que sirve de guía constante, aunque no estés directamente frente a él todo el tiempo.','Puede señalar un valor o persona que, aunque no esté presente a diario, sigue siendo tu punto de orientación.','¿Qué valor o persona sigue siendo tu "punto de referencia", aunque no esté presente a diario?'],
  reloj3:['Reloj detenido en una hora específica','Un reloj detenido marcando una hora exacta y memorable representa un momento preciso que tu mente sigue procesando, consciente o inconscientemente.','Vale la pena recordar qué asocias tú, personalmente, con esa hora específica que marcaba el reloj.','¿Qué recuerdas que haya pasado alrededor de esa hora específica que marcaba el reloj?'],
  llavero:['Llavero con muchas llaves','Un llavero cargado de llaves representa sentir que tienes muchas responsabilidades o accesos que manejar al mismo tiempo, algunos quizás ya innecesarios.','Puede ser útil revisar cuáles de esas "llaves" (compromisos) ya no abren ninguna puerta relevante en tu vida actual.','¿Qué compromiso actual sientes que ya no "abre ninguna puerta" relevante para ti?'],
  candado:['Candado','Un candado representa una protección deliberada sobre algo que consideras valioso o vulnerable, a veces más reforzada de lo necesario.','Puede señalar que estás protegiendo algo con más rigidez de la que realmente requiere la situación.','¿Hay algo que proteges con más rigidez de la que realmente necesita?'],
  cajafuerte:['Caja fuerte','Una caja fuerte representa algo de gran valor —material o emocional— que guardas con especial cuidado, lejos del alcance casual de los demás.','Olvidar la combinación en el sueño puede reflejar sentir que perdiste el acceso a un recurso interno importante.','¿A qué recurso valioso sientes que, por ahora, has perdido un poco el acceso?'],
  diario:['Diario personal','Un diario personal representa tu historia íntima registrada con honestidad, y el valor de revisar tu propio proceso con perspectiva.','Que alguien más lo lea sin permiso en el sueño puede reflejar miedo a que una parte muy privada de ti se exponga sin tu consentimiento.','¿Qué parte muy privada de ti sientes que temes que se exponga sin tu consentimiento?'],
  pasaporte:['Pasaporte','Un pasaporte representa tu identidad reconocida oficialmente y tu capacidad de moverte libremente hacia nuevas experiencias o etapas.','Perderlo en sueños puede simbolizar miedo a que una oportunidad de cambio importante se vea bloqueada justo antes de concretarse.','¿Qué oportunidad de cambio sientes que podría bloquearse justo antes de concretarse?'],
  visa:['Visa (documento de viaje)','Una visa representa el permiso —propio o ajeno— que sientes necesario antes de avanzar hacia una nueva etapa o lugar en tu vida.','Que te la nieguen en el sueño puede señalar sentir que todavía no tienes la "autorización" interna para dar ese paso.','¿Sientes que todavía necesitas darte permiso a ti mismo para avanzar hacia algo nuevo?'],
  equipaje2:['Hacer las maletas con prisa','Empacar con prisa, olvidando cosas importantes, representa una transición que sientes que está llegando más rápido de lo que te gustaría estar preparado.','Puede reflejar la sensación real de no tener suficiente tiempo para prepararte del todo para un cambio que se aproxima.','¿Sientes que un cambio próximo está llegando más rápido de lo que puedes prepararte?'],
  pasajero:['Ser pasajero (no conducir)','Ser pasajero en lugar de conducir representa dejar que otra persona —o las circunstancias— decidan el rumbo de una situación por un tiempo.','Puede reflejar comodidad al soltar el control, o frustración si preferirías decidir tú mismo el camino.','¿Estás cómodo dejando que alguien más decida el rumbo por ahora, o preferirías tomar tú el control?'],
  autoestopista:['Autoestopista (hacer dedo)','Pedir que alguien te lleve en la carretera representa necesitar ayuda externa para avanzar en un trayecto que no puedes recorrer completamente solo.','Puede señalar que es momento de aceptar apoyo en lugar de insistir en resolver todo de forma autosuficiente.','¿Hay algo donde necesitas aceptar ayuda en vez de insistir en hacerlo todo solo?'],
  cruzarfrontera:['Cruzar una frontera','Cruzar una frontera representa dejar atrás un marco conocido de reglas para entrar en un territorio con normas distintas: un cambio de contexto significativo.','Puede reflejar una transición real hacia un entorno (laboral, social, personal) con reglas muy distintas a las que conocías.','¿Qué "territorio" nuevo, con reglas distintas a las habituales, estás empezando a cruzar?']
};
