const dreamThemes=[
  {keys:['animal','insecto','mosca','abeja','hormiga'],title:'Instinto y compañía',text:'La presencia animal suele señalar instintos, vínculos y cualidades que estás reconociendo en ti mismo. En la tradición de los símbolos oníricos, cada especie aporta un matiz distinto: lo importante es la actitud del animal, no solo su presencia.',hidden:'Pregúntate qué cualidad asocias con ese animal en particular: suele ser justo la que tu mente está intentando señalarte.',question:'¿Qué actitud tenía el animal y qué parte tuya reconoces en ella?'},
  {keys:['miedo','ansiedad','llorar','triste','peligro','pesadilla'],title:'Una emoción que pide ser escuchada',text:'Cuando un sueño trae tensión o angustia, la ciencia del sueño coincide en que suele estar procesando una preocupación real o un límite pendiente, no anticipando un peligro literal.',hidden:'Las pesadillas cumplen una función conocida como "ensayo de amenazas": tu mente practica escenarios difíciles para sentirse más preparada, no para advertirte del futuro.',question:'¿Qué situación real de tu vida despierta una emoción parecida a la del sueño?'},
  {keys:['amor','beso','familia','amigo','amiga','abrazo'],title:'Vínculo y necesidad afectiva',text:'Las personas y los gestos de cariño en los sueños suelen expresar conexión, nostalgia o una cualidad que deseas integrar en ti mismo, más que un mensaje literal sobre esa persona.',hidden:'Incluso cuando sueñas con alguien que ya no ves, los estudios sobre memoria y sueño sugieren que tu mente está usando esa figura como símbolo de algo que esa persona representó para ti.',question:'¿Qué cualidad de esa persona sientes que necesitas más en tu vida ahora mismo?'},
  {keys:['ex novio','ex novia','ex pareja','expareja','mi ex'],title:'Ex pareja',text:'Soñar con una expareja casi nunca habla de querer volver: suele representar una cualidad, patrón o aprendizaje de esa relación que sigue activo en cómo te vinculas hoy.',hidden:'Es uno de los sueños más frecuentes y menos literales: la ciencia del sueño lo asocia con procesamiento de memoria emocional, no con deseo real de regreso.',question:'¿Qué patrón de esa relación sigue repitiéndose en tus vínculos actuales?'},
  {keys:['perdi','perder mis','perder las llaves','perder la cartera','perder el bolso','perdi mi'],title:'Perder un objeto',text:'Soñar que pierdes un objeto importante (llaves, cartera, documentos) suele reflejar miedo a perder control, identidad o seguridad en un área específica de tu vida.',hidden:'El objeto perdido suele ser simbólico: una cartera habla de identidad o recursos; unas llaves, de acceso u oportunidades.',question:'¿Qué sientes que podrías estar a punto de perder si no le pones atención pronto?'},
  {keys:['llegar tarde','llego tarde','no llegaba','se me hacia tarde'],title:'Llegar tarde',text:'Soñar que llegas tarde a algo importante —o que no alcanzas a prepararte— refleja ansiedad por el tiempo y la sensación de no estar a la altura de lo que se espera de ti.',hidden:'Es uno de los sueños de ansiedad más comunes junto al examen: ambos reflejan miedo a no cumplir expectativas, propias o ajenas.',question:'¿Sientes que vas "tarde" en algún plan de vida, comparado con lo que esperabas de ti mismo?'},
  {keys:['grite y no','no me salia la voz','gritaba sin','no podia gritar'],title:'Grito silencioso',text:'Soñar que gritas y no sale ningún sonido —o que nadie te escucha— es un símbolo muy estudiado de sentir que tu voz no tiene el peso o la atención que necesitas en una situación real.',hidden:'Suele intensificarse en periodos donde una persona siente que ha intentado expresar algo importante sin ser realmente escuchada.',question:'¿En qué situación sientes que tu voz no está siendo realmente escuchada?'},
  {keys:['no podia moverme','no me podia mover','paralizado','paralizada','parálisis'],title:'No poder moverse',text:'La sensación de no poder moverte en un sueño —a veces ligada a la parálisis del sueño real, un fenómeno fisiológico conocido— suele reflejar sentirte atrapado o indeciso frente a una decisión importante.',hidden:'Si esto ocurre de forma física al despertar (parálisis del sueño), es un fenómeno neurológico común y no tiene una causa emocional necesaria, aunque puede resultar perturbador.',question:'¿Frente a qué decisión sientes que, simbólicamente, "no puedes moverte"?'},
  {keys:['invisible','nadie me veia','no me notaban','nadie me escuchaba'],title:'Ser invisible',text:'Sentirte invisible en un sueño —que nadie te nota o escucha— suele reflejar una necesidad real de atención o reconocimiento que no está siendo cubierta en tu vida despierta.',hidden:'A diferencia de la soledad elegida, la invisibilidad suele sentirse como una falta de reconocimiento no deseada.',question:'¿En qué relación o espacio sientes que no estás siendo del todo visto?'},
  {keys:['muy pequeño','muy pequeña','gigante','enorme comparado','me hice chiquito'],title:'Cambiar de tamaño',text:'Volverte muy pequeño o muy grande en un sueño refleja directamente cómo te sientes frente a una situación: pequeño ante algo que te supera, o grande frente a algo que por fin sientes manejable.',hidden:'Es un símbolo muy ligado a la autoestima situacional: no habla de quién eres en general, sino de cómo te sientes frente a algo puntual.',question:'¿Frente a qué situación te sientes actualmente "demasiado pequeño" o "demasiado grande"?'},
  {keys:['mismo dia otra vez','se repetia','dia una y otra vez','bucle'],title:'Repetir el mismo día',text:'Soñar que revives el mismo día una y otra vez suele reflejar la sensación de estar atrapado en una rutina o patrón que sientes que no cambia, por más que lo intentes.',hidden:'A diferencia del laberinto, este símbolo habla de monotonía y falta de novedad percibida, no de falta de claridad.',question:'¿Qué parte de tu rutina sientes que se repite sin ningún cambio real, por más que lo intentes?'},
  {keys:['viajaba en el tiempo','al pasado','al futuro','de niño otra vez','de nino otra vez'],title:'Viajar en el tiempo',text:'Soñar con viajar al pasado o al futuro suele reflejar una necesidad de revisar una decisión antigua, o ansiedad sobre un resultado todavía no definido.',hidden:'Volver a una etapa específica del pasado (la infancia, por ejemplo) suele señalar un recurso o cualidad de esa etapa que necesitas recuperar ahora.',question:'Si pudieras llevar algo de esa etapa a tu presente, ¿qué sería?'},
  {keys:['ahogaba','ahogandome','ahogándome','me ahogo','ahogue','ahogué','ahogado','ahogada','ahogarme','ahogarse'],title:'Ahogarse',text:'Soñar que te ahogas suele reflejar una sensación real de sentirte sobrepasado por responsabilidades, emociones o expectativas que no puedes sostener al mismo ritmo.',hidden:'Es una de las pesadillas más comunes en periodos de estrés sostenido; el cuerpo dormido traduce la presión diaria en una imagen física de falta de aire.',question:'¿En qué área de tu vida sientes que te falta aire o margen para respirar?'},
  {keys:['me lanzaron','me lanzo','me lanzó','me empujaron','me arrojaron','me tiraron','me aventaron','me arrastraron'],title:'Ser lanzado o empujado por otro',text:'Que algo o alguien te lance, empuje o arroje dentro del sueño representa sentir que fuiste puesto en una situación difícil sin haberlo elegido tú mismo: la decisión o la fuerza vino de afuera, no de ti.',hidden:'Es distinto a caer por tu cuenta: aquí el origen del movimiento es externo, lo que suele señalar una circunstancia real donde sentiste poco o ningún control sobre cómo llegaste hasta ahí.',question:'¿En qué situación actual sientes que fuiste "lanzado" sin haberlo decidido tú mismo?'},
  {keys:['casa embrujada','casa encantada','casa encantad'],title:'Casa embrujada',text:'Una casa embrujada representa tu mundo interior con partes del pasado sin resolver que todavía generan inquietud al "visitarlas".',hidden:'A diferencia del fantasma como figura específica, aquí todo el espacio interior se siente cargado de asuntos pendientes, no solo un recuerdo puntual.',question:'¿Qué parte de tu historia personal sientes que todavía "hace ruido" sin resolver?'}
];
function normalizeDream(value){return value.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9ñ\s]/gi,' ').replace(/\s+/g,' ').trim()}
function escapeDream(value){return value.replace(/[&<>"']/g,character=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[character]))}
// Exige que la palabra empiece justo después de un espacio (o al inicio), para que "bruja" no haga
// match dentro de "embrujada", "oso" dentro de "osados", etc. — evita falsos positivos por coincidencia parcial.
// Quita terminaciones comunes del español (verbos conjugados, plurales, etc.) para poder
// reconocer "comía", "comiendo" o "comer" como la misma raíz, sin tener que escribir cada
// forma a mano para cada uno de los símbolos del diccionario.
const SPANISH_SUFFIXES=['andonos','iendonos','andome','iendome','andote','iendote','abamos','iamos','ariamos','eriamos','iriamos','aremos','eremos','iremos','arian','erian','irian','arias','erias','irias','aria','eria','iria','asteis','isteis','ieron','aron','arse','erse','irse','ando','iendo','ados','adas','idos','idas','aste','iste','amos','emos','imos','aban','ian','ara','iera','ase','iese','aran','ieran','asen','iesen','ado','ida','ido','aba','ia','ar','er','ir','as','es','an','en','o','a','e','s'].sort((a,b)=>b.length-a.length);
function spanishStem(word){
  for(const suf of SPANISH_SUFFIXES){
    const minLen=suf.length<=1?4:3;
    if(word.length-suf.length>=minLen&&word.endsWith(suf))return word.slice(0,word.length-suf.length);
  }
  return word;
}
function wordStartMatch(normalizedPadded,needle){
  const idx=normalizedPadded.indexOf(needle);
  if(idx===-1)return -1;
  return normalizedPadded[idx-1]===' '?idx:-1;
}
// Detecta matices del relato (color, cualidad, si el soñante controlaba o huía del símbolo)
// que cambian el significado aunque el símbolo base sea el mismo.
const dreamColorMeanings={blanco:'pureza, claridad o un comienzo limpio',blanca:'pureza, claridad o un comienzo limpio',negro:'lo oculto, el misterio o algo que aún no comprendes del todo',negra:'lo oculto, el misterio o algo que aún no comprendes del todo',rojo:'pasión, urgencia o una alerta emocional',roja:'pasión, urgencia o una alerta emocional',dorado:'algo que percibes como valioso o significativo',dorada:'algo que percibes como valioso o significativo',azul:'calma y un tono emocional tranquilo',azul2:'',verde:'crecimiento o renovación',gris:'ambigüedad, algo que todavía no es ni una cosa ni la otra',plateado:'intuición y un matiz más espiritual',plateada:'intuición y un matiz más espiritual',morado:'transformación o un matiz más místico',morada:'transformación o un matiz más místico'};
const dreamQualityMeanings={hermoso:'percibiste esa energía como algo positivo, no amenazante',hermosa:'percibiste esa energía como algo positivo, no amenazante',bello:'percibiste esa energía como algo positivo, no amenazante',bella:'percibiste esa energía como algo positivo, no amenazante',feo:'percibiste esa energía con rechazo o incomodidad',fea:'percibiste esa energía con rechazo o incomodidad',aterrador:'esa energía se sintió abrumadora o fuera de tu control',aterradora:'esa energía se sintió abrumadora o fuera de tu control',horrible:'esa energía se sintió abrumadora o fuera de tu control',gigante:'sentiste esa energía más grande o intensa de lo habitual',enorme:'sentiste esa energía más grande o intensa de lo habitual',pequeño:'sentiste esa energía más manejable de lo que esperabas',pequeña:'sentiste esa energía más manejable de lo que esperabas',diminuto:'sentiste esa energía más manejable de lo que esperabas'};
const dreamAgencyMeanings={montaba:'no solo observabas esa energía: la estabas dirigiendo tú mismo, con control activo',monte:'no solo observabas esa energía: la estabas dirigiendo tú mismo, con control activo',cabalgaba:'no solo observabas esa energía: la estabas dirigiendo tú mismo, con control activo',conducia:'tenías el control directo de hacia dónde iba esa energía',manejaba:'tenías el control directo de hacia dónde iba esa energía',perseguia:'esa energía te perseguía a ti, lo que suele indicar algo de lo que te sientes huyendo en la vida despierta',atacaba:'esa energía se sintió hostil hacia ti, no neutral',acariciaba:'había cercanía y aceptación en el vínculo con esa energía',abrazaba:'había cercanía y aceptación en el vínculo con esa energía',sostenia:'había cercanía y aceptación en el vínculo con esa energía'};
function dreamModifiers(normalized){
  const found=[];
  for(const [word,meaning] of Object.entries(dreamColorMeanings)){if(meaning&&wordStartMatch(normalized,word)!==-1)found.push(meaning)}
  for(const [word,meaning] of Object.entries(dreamQualityMeanings)){if(wordStartMatch(normalized,word)!==-1)found.push(meaning)}
  for(const [word,meaning] of Object.entries(dreamAgencyMeanings)){if(wordStartMatch(normalized,word)!==-1)found.push(meaning)}
  return [...new Set(found)];
}
function interpretDream(raw){
  const normalized=` ${normalizeDream(raw)} `;
  // Palabras sueltas del relato, con su posición y su raíz (sin conjugación), para poder
  // reconocer un símbolo aunque el usuario lo haya escrito en otro tiempo verbal.
  const inputWords=normalized.trim().split(' ').filter(Boolean);
  const inputWordStems=inputWords.map(w=>({word:w,stem:spanishStem(w)}));
  // Busca TODOS los símbolos del diccionario que aparecen en el relato completo, no solo el primero.
  const foundKeys=[];
  for(const item of Object.keys(dreams)){
    const needle=normalizeDream(item);
    let pos=wordStartMatch(normalized,needle);
    if(dreamsExtraExact.has(item)){if(pos!==-1&&normalized[pos+needle.length]!==' ')pos=-1;if(pos===-1)continue}
    if(pos===-1){
      // No hubo coincidencia exacta: probar por raíz (p. ej. "comía" debe reconocer el símbolo "comida").
      const needleStem=spanishStem(needle);
      if(needleStem.length>=3){
        const match=inputWordStems.find(w=>w.stem===needleStem);
        if(match)pos=normalized.indexOf(` ${match.word} `);
      }
    }
    if(pos!==-1&&!foundKeys.includes(item))foundKeys.push({item,pos});
  }
  foundKeys.sort((a,b)=>a.pos-b.pos);
  const symbols=[];for(const {item} of foundKeys){const [title,text,hidden,question]=dreams[item];if(symbols.some(x=>x.title===title))continue;symbols.push({title,text,hidden,question});if(symbols.length>=5)break}
  // También revisa los temas de varias palabras (ex pareja, llegar tarde, etc.) y los agrega si no están ya cubiertos.
  for(const theme of dreamThemes){
    if(symbols.length>=5)break;
    const hit=theme.keys.some(word=>{
      const needle=normalizeDream(word);
      if(wordStartMatch(normalized,needle)!==-1)return true;
      if(!needle.includes(' ')){
        const needleStem=spanishStem(needle);
        if(needleStem.length>=3)return inputWordStems.some(w=>w.stem===needleStem);
      }
      return false;
    });
    if(hit&&!symbols.some(s=>s.title===theme.title)){
      symbols.push({title:theme.title,text:theme.text,hidden:theme.hidden,question:theme.question});
    }
  }
  if(symbols.length>0)return {symbols,known:true,modifiers:dreamModifiers(normalized)};
  const tense=/(miedo|ansiedad|oscuro|oscuridad|llorar|triste|perseguir|peligro|perder|caer|atrap)/.test(normalized);
  const luminous=/(luz|sol|estrella|risa|calma|feliz|volar|celebr|abrazo|amor)/.test(normalized);
  const stop=new Set(['que','con','una','uno','las','los','del','por','para','donde','cuando','muy','mas','más','sin','soñe','sone','soñé','sueño','sueno','estaba','habia','había','era','eran','esta','está']);
  const mainWord=normalized.trim().split(' ').filter(w=>w.length>3&&!stop.has(w))[0]||raw.trim().split(/\s+/)[0]||'esta imagen';
  const title=`Un símbolo propio: «${mainWord}»`;
  const text=tense?`«${mainWord}» no es uno de los símbolos clásicos más documentados, pero el tono de tu relato sugiere una preocupación o emoción incómoda que tu mente está intentando procesar mientras duermes.`:luminous?`«${mainWord}» no es uno de los símbolos clásicos más documentados, pero el tono de tu relato sugiere una energía positiva o un deseo que está buscando espacio para expresarse en tu vida despierta.`:`«${mainWord}» no aparece en los diccionarios de símbolos más consultados, lo cual es normal: la psicología del sueño sostiene que muchas imágenes son personales y nacen de tus propios recuerdos y asociaciones, no de un significado universal fijo.`;
  const hidden=tense?`La neurociencia del sueño llama a esto "procesamiento emocional nocturno": el cerebro revive una preocupación en forma simbólica —en este caso, a través de «${mainWord}»— para intentar digerirla mejor que en estado de vigilia.`:luminous?`Los sueños con tono positivo, como el que describes con «${mainWord}», suelen aparecer cuando una parte de ti ya sabe —aunque el consciente aún lo dude— que una situación está mejorando o que un deseo es alcanzable.`:`Para un símbolo propio como «${mainWord}», la pregunta más útil no es "qué significa" en general, sino "qué asocio yo, personalmente, con eso": esa asociación suele ser más precisa que cualquier diccionario.`;
  const question=tense?`¿Qué preocupación concreta asocias tú con «${mainWord}», más allá del sueño?`:luminous?`¿Qué deseo relacionado con «${mainWord}» sientes que está más cerca de cumplirse de lo que te permites creer?`:`¿Qué es lo primero que piensas, de forma personal, cuando lees la palabra «${mainWord}»?`;
  return {symbols:[{title,text,hidden,question}],known:false,modifiers:dreamModifiers(normalized)};
}
// Clasifica cada símbolo encontrado en una categoría de fondo (amenaza, refugio, transformación, etc.)
// a partir de su propio texto, para poder razonar cómo se conectan entre sí dentro del mismo sueño.
function classifyDreamBucket(sym){
  const t=(sym.text+' '+sym.hidden).toLowerCase();
  const rules=[
    ['amenaza',/amenaza|peligro|miedo|agres|atac|depredador|inquiet/],
    ['perdida',/pérdida|perdida|duelo|cierre|despedida|termina|concluye/],
    ['transformacion',/transformaci|cambio|renova|metamorfosis|proceso de cambio/],
    ['refugio',/hogar|seguridad|protecc|refugio|identidad|espacio (personal|íntimo|propio)/],
    ['deseo',/deseo|esperanza|libertad|aspiraci|posibilidad/],
    ['vinculo',/vínculo|relación|afect|cariño|lealtad|conexión/],
    ['control',/control|poder|autoridad|decisión|dirección|manej/],
    ['comunicacion',/expresi|comunicaci|\bvoz\b|mensaje|escuchad|decir/],
    ['energia',/energía|pasión|intensidad|fuerza vital|vitalidad/],
    ['exposicion',/expuest|vergüenza|juicio|vulnerab/]
  ];
  for(const [name,re] of rules)if(re.test(t))return name;
  return 'personal';
}
const dreamBucketClause={amenaza:'una señal de alerta o tensión',perdida:'el cierre de algo importante',transformacion:'un proceso de cambio en marcha',refugio:'tu espacio personal o tu identidad',deseo:'un deseo o una esperanza que buscas cumplir',vinculo:'una necesidad afectiva o de conexión con alguien',control:'una cuestión de control o poder sobre una situación',comunicacion:'la necesidad de expresar algo que no has dicho del todo',energia:'una energía intensa que busca salida',exposicion:'el miedo a ser juzgado o expuesto',personal:'algo muy propio de tu historia personal'};
const dreamPairInsight={'amenaza|refugio':'sientes que algo que te inquieta se está acercando a un espacio que consideras tuyo o seguro','amenaza|transformacion':'una situación que te genera tensión también está empujando un cambio que, aunque incómodo, podría ser necesario','refugio|transformacion':'una parte importante de tu identidad o tu vida cotidiana está atravesando una transformación real','perdida|vinculo':'estás procesando el cierre de algo relacionado con un vínculo importante para ti','control|deseo':'quieres algo con fuerza, pero sientes que no depende solo de ti conseguirlo','comunicacion|exposicion':'tienes algo que decir, pero temes cómo podría ser recibido por los demás','control|energia':'sientes una energía fuerte que todavía no sabes bien cómo dirigir','perdida|vinculo2':'un vínculo importante está atravesando un cierre o cambio de etapa','deseo|transformacion':'un cambio que deseas ya está, de alguna forma, en marcha','control|exposicion':'te preocupa cómo te perciben los demás frente a una decisión que estás tomando','energia|transformacion':'una energía intensa dentro de ti está impulsando un cambio real','amenaza|perdida':'una preocupación actual está ligada al miedo de perder algo que valoras','refugio|vinculo':'tu sentido de seguridad está muy ligado a una relación importante en este momento','deseo|vinculo':'hay un deseo tuyo que está profundamente conectado con una persona importante','control|refugio':'sientes que necesitas más control sobre tu espacio o tu vida cotidiana','control|personal':'sientes que una situación reciente fue decidida por otros más que por ti mismo, y eso además toca algo muy particular de tu historia personal que vale la pena mirar con más calma'};
function dreamSynthesis(symbols){
  if(symbols.length<2)return '';
  const tagged=symbols.map(s=>({...s,bucket:classifyDreamBucket(s)}));
  const seen=[],chosen=[];
  for(const s of tagged){if(!seen.includes(s.bucket)){seen.push(s.bucket);chosen.push(s)}if(chosen.length===3)break}
  const namesFor=b=>tagged.filter(s=>s.bucket===b).map(s=>s.title).join(' y ');
  const key=chosen.length>1?[chosen[0].bucket,chosen[1].bucket].sort().join('|'):'';
  const insight=chosen.length>1?(dreamPairInsight[key]||`${dreamBucketClause[chosen[0].bucket]} convive, en el mismo sueño, con ${dreamBucketClause[chosen[1].bucket]}`):dreamBucketClause[chosen[0].bucket];
  const clauses=chosen.map(s=>`${dreamBucketClause[s.bucket]} (a través de ${namesFor(s.bucket)})`);
  const combined=clauses.length>1?clauses.slice(0,-1).join(', ')+' y '+clauses[clauses.length-1]:clauses[0];
  return `<div class="dream-question" style="margin-top:0 0 14px"><b>✦ Lectura del conjunto</b><p>Tu relato combina ${combined}. Leyendo estos símbolos juntos, en lugar de por separado, tu sueño parece estar diciendo que ${insight}.</p></div>`;
}
function dreamDepth(symbols){
  const bridge=symbols.length>1?`<p class="dream-lead" style="margin:0 0 14px">Estos símbolos aparecieron juntos en el mismo relato, y eso no suele ser casualidad: en vez de leerlos por separado, conviene pensarlos como partes de una sola historia emocional que tu mente está contando a través de varias imágenes a la vez.</p>`:'';
  const items=symbols.map(s=>`<div class="depth-item"><span>✦ ${escapeDream(s.title).toUpperCase()}</span><p>${s.hidden}</p></div>`).join('');
  const questions=symbols.map(s=>`<p>${s.question}</p>`).join('');
  return `<div class="dream-depth">${bridge}${items}<div class="dream-question"><b>${symbols.length>1?'Preguntas para llevar contigo':'Pregunta para llevar contigo'}</b>${questions}</div></div>`;
}
function dream(){shell(`${head('☾','Significado de sueños','Describe todo lo que recuerdes: símbolos, personas, lugares y emociones.')}<div class="panel"><p style="font-size:12px;line-height:1.55;color:var(--muted);margin:0 0 4px">Esta lectura combina símbolos de la psicología junguiana, los diccionarios de sueños más consultados y lo que la ciencia del sueño sabe hoy sobre por qué soñamos. No predice el futuro: te ayuda a pensar en lo que tu mente podría estar procesando.</p></div><div class="panel"><div class="dream-compose"><textarea id="dreamInput" class="dream-textarea" placeholder="Ej. Soñé que caminaba sobre un lago y una serpiente azul me observaba…" maxlength="1000" aria-label="Descripción del sueño"></textarea><div class="dream-meta"><span>Cuantos más detalles, más precisa será la lectura.</span><b id="dreamCount">0/1000</b></div><button class="primary" id="dreamSearch">✦ Interpretar mi sueño</button></div><div class="chips">${['agua','serpiente','volar','casa','caer','perseguir','examen','dientes'].map(x=>`<button class="chip" data-dream="${x}">${x}</button>`).join('')}</div><div id="dreamResult"><div class="empty">✦<br>Tu interpretación aparecerá aquí</div></div></div>`);
 const input=$('#dreamInput'),count=$('#dreamCount');input.oninput=()=>{count.textContent=`${input.value.length}/1000`};
 const search=()=>{
  const raw=input.value.trim();if(!raw)return toast('Describe tu sueño primero');
  const reading=interpretDream(raw),symbols=reading.symbols;sound('reveal');
  const label=!reading.known?'Lectura personalizada':symbols.length>1?`${symbols.length} símbolos reconocidos`:'Símbolo reconocido';
  const titleStr=symbols.map(s=>escapeDream(s.title)).join(' · ');
  const synthesis=reading.known?dreamSynthesis(symbols):'';
  const leadHtml=symbols.length>1?symbols.map(s=>`<p class="dream-lead"><b>${escapeDream(s.title)}:</b> ${s.text}</p>`).join(''):`<p class="dream-lead">${symbols[0].text}</p>`;
  const modifiersHtml=reading.modifiers&&reading.modifiers.length?`<div class="dream-question"><b>✦ Detalles de tu relato que cambian el matiz</b><p>Además del símbolo en sí, tu relato incluye detalles propios: ${reading.modifiers.join('; ')}. Esto hace que esta lectura sea más tuya que genérica.</p></div>`:'';
  $('#dreamResult').innerHTML=`<div class="result dream-result"><span class="eyebrow">${label}</span><strong>${titleStr}</strong>${synthesis}${leadHtml}${modifiersHtml}${dreamDepth(symbols)}<p class="dream-context"><b>Tu relato:</b> ${escapeDream(raw.slice(0,220))}${raw.length>220?'…':''}</p></div>`;
  log('dream_search',{found:reading.known,symbols:symbols.length,characters:raw.length});
 };
 $('#dreamSearch').onclick=search;document.querySelectorAll('[data-dream]').forEach(b=>b.onclick=()=>{input.value=b.dataset.dream;input.dispatchEvent(new Event('input'));search()});
}

