const allChoirs=angelHierarchy.flatMap(group=>group.choirs);
function angelChoir(name){return allChoirs.find(choir=>choir.name===name)||allChoirs[1]}
function angelReadingMarkup(choir){const v=choir.variants[Math.floor(Math.random()*choir.variants.length)];const guideLead=choir.guide.replace(/\.$/,'');return `<div class="result angel-result"><div class="angel-result-icon">${choir.symbol}</div><span class="eyebrow">Mensaje de ${choir.name}</span><strong>${choir.essence}</strong><p class="angel-message">${guideLead}, este coro te trae lo siguiente: ${v.message}</p><div class="angel-deepen"><b>✺ Una mirada más profunda a ${choir.name}</b><p>${choir.deepen}</p></div><div class="angel-action"><b>✦ Llevarlo a la práctica</b><span>${v.action}</span></div><p class="note">Tómalo como una reflexión simbólica: el significado más importante nace de tu propia experiencia.</p></div>`}
const angelWheelKeyMap={angeles:'Ángeles',serafines:'Serafines',querubines:'Querubines',tronos:'Tronos',dominaciones:'Dominaciones',virtudes:'Virtudes',potestades:'Potestades',principados:'Principados',arcangeles:'Arcángeles'};
let angelWheelListenerAttached=false;
function angelFormatCooldown(ms){
  const totalSeconds=Math.max(0,Math.ceil(ms/1000));
  const h=Math.floor(totalSeconds/3600),m=Math.floor((totalSeconds%3600)/60),s=totalSeconds%60;
  return `${String(h).padStart(2,'0')}:${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`;
}
let angelCooldownInterval=null;
function angelUpdateCooldown(){
  const el=$('#angelCooldown');
  if(!el)return;
  const last=Number(localStorage.getItem('ruedaMisticaLastSpin')||0);
  const remaining=24*60*60*1000-(Date.now()-last);
  if(remaining>0){
    el.innerHTML=`⏳ Tiempo restante para el próximo giro: <b>${angelFormatCooldown(remaining)}</b>`;
    el.classList.add('active');
  } else {
    el.innerHTML=`✺ Ya puedes girar la rueda`;
    el.classList.remove('active');
  }
}
function angels(){state.screen='angels';shell(`${head('✺','Mensajes angelicales','')}<div class="panel angel-intro"><div class="angel-aura">✺</div><h3>El mapa de las alturas</h3></div><div class="angel-wheel-frame"><iframe id="angelWheelFrame" src="rueda-mistica/index.html" title="Rueda mística de los coros angélicos" allow="autoplay" loading="eager"></iframe></div><div class="angel-cooldown" id="angelCooldown"></div><div id="angelResult"><div class="empty">✺<br>Tu mensaje aparecerá aquí</div></div><div class="panel"><p class="note">La jerarquía se inspira libremente en tradiciones angelológicas. No pretende afirmar presencias sobrenaturales ni sustituye apoyo profesional, consejo médico o decisiones informadas.</p></div>`,false,true);
  angelUpdateCooldown();
  if(angelCooldownInterval)clearInterval(angelCooldownInterval);
  angelCooldownInterval=setInterval(()=>{if(state.screen!=='angels'){clearInterval(angelCooldownInterval);return}angelUpdateCooldown()},1000);
  if(!angelWheelListenerAttached){
    angelWheelListenerAttached=true;
    window.addEventListener('message',(event)=>{
      if(!event.data||event.data.type!=='ruedaMisticaResult')return;
      if(state.screen!=='angels')return;
      const name=angelWheelKeyMap[event.data.key];
      const choir=allChoirs.find(c=>c.name===name);
      if(!choir)return;
      state.angelChoir=choir.name;
      const resultEl=$('#angelResult');
      if(!resultEl)return;
      resultEl.innerHTML=angelReadingMarkup(choir);
      resultEl.scrollIntoView({behavior:'smooth',block:'nearest'});
      sound('reveal');
      log('angel_message',{choir:choir.name});
      angelUpdateCooldown();
    });
  }
}

const symbols=['◯','✚','≋','□','☆'];
const symbolNames=['Círculo','Cruz','Ondas','Cuadrado','Estrella'];
function esp(){state.espRound=0;state.espHits=0;state.espHistory=[];state.espTarget=Math.floor(Math.random()*symbols.length);renderEspRound()}
function espGuide(){return `<div class="esp-guide"><div class="esp-guide-title"><span>✦</span><div><b>¿Cómo funciona?</b><small>Un experimento breve para escuchar tu primera impresión.</small></div></div><div class="esp-steps"><div><b>1</b><span><strong>Cierra los ojos</strong><small>Respira y aparta la vista de los símbolos.</small></span></div><div><b>2</b><span><strong>Imagina una forma</strong><small>Con los ojos cerrados, piensa en la que sientas.</small></span></div><div><b>3</b><span><strong>Abre y elige</strong><small>Toca esa opción; después se revela la carta.</small></span></div></div><p class="esp-expectation"><b>Importante:</b> hay 5 símbolos, así que acertar por azar también es posible. No necesitas “tener poderes” ni buscar una respuesta perfecta.</p></div>`}
function renderEspRound(){shell(`${head('✦','Percepción extrasensorial','Cierra los ojos, imagina un símbolo y después comprueba tu elección.')}<div class="panel esp-panel">${espGuide()}<div class="esp-progress"><i style="width:${state.espRound/5*100}%"></i></div><div class="esp-status"><span>RONDA ${state.espRound+1} DE 5</span><b>Aciertos: ${state.espHits}</b></div><div class="esp-target-card"><span>✦ CARTA OCULTA</span><div class="score-orb">?</div><p>La carta ya fue elegida al azar. Cierra los ojos antes de escoger: no cambiará mientras decides.</p></div><div class="zener">${symbols.map((s,i)=>`<button class="choice symbol" data-symbol="${i}" aria-label="Elegir ${symbolNames[i]}"><span>${s}</span><small>${symbolNames[i]}</small></button>`).join('')}</div><p class="esp-prompt">Cuando hayas imaginado tu símbolo con los ojos cerrados, ábrelos y toca una opción.</p><div id="espFeedback" aria-live="polite"></div></div>`);document.querySelectorAll('[data-symbol]').forEach(b=>b.onclick=()=>{const target=state.espTarget,choice=+b.dataset.symbol,hit=choice===target;if(hit)state.espHits++;state.espHistory.push({choice,target,hit});sound(hit?'reveal':'tap');document.querySelectorAll('[data-symbol]').forEach(x=>x.disabled=true);b.classList.add('selected');document.querySelector(`[data-symbol="${target}"]`)?.classList.add('target');$('.score-orb').textContent=symbols[target];$('#espFeedback').innerHTML=`<div class="esp-feedback ${hit?'hit':'miss'}"><div class="esp-reveal-label">${hit?'✦ ¡COINCIDENCIA!':'La carta se revela'}</div><strong>${hit?'Tu primera impresión coincidió':'Esta vez fue otra señal'}</strong><div class="esp-comparison"><span>Tu elección<b>${symbols[choice]} ${symbolNames[choice]}</b></span><i>VS</i><span>Carta oculta<b>${symbols[target]} ${symbolNames[target]}</b></span></div><p>${hit?'Suma un acierto. Observa cómo te sentiste antes de elegir.':'No pasa nada: cada ronda es independiente y el azar forma parte del juego.'}</p><button class="primary" id="nextEsp">${state.espRound===4?'Ver mi lectura':'Siguiente ronda'}</button></div>`;$('#nextEsp').onclick=()=>{sound();state.espRound++;if(state.espRound>=5)espResult();else{state.espTarget=Math.floor(Math.random()*symbols.length);renderEspRound()}}});}
function espLongestStreak(history){let best=0,current=0;for(const round of history){if(round.hit){current++;best=Math.max(best,current)}else current=0}return best}
const espTierContent={
  5:[['Racha perfecta','Acertaste las 5 rondas. Estadísticamente, la probabilidad de lograrlo solo por azar es de apenas 1 en 3,125 — algo real pasó en tu atención esta vez, aunque una sola sesión nunca basta para sacar conclusiones firmes.'],
     ['El azar casi nunca hace esto','5 de 5 es un resultado que el puro azar produce muy rara vez. Vale la pena repetir el test otro día, en otro estado de ánimo, para ver si se repite el patrón.']],
  4:[['Una racha notable','4 de 5 aciertos está muy por encima de lo que el azar produce en promedio (que sería 1 de 5). Presta atención a qué hacías distinto justo antes de acertar.'],
     ['Más allá de la coincidencia','Acertar 4 de 5 veces, al azar puro, pasa menos del 1% de las veces. No es prueba de nada paranormal, pero sí invita a repetir el experimento con curiosidad.']],
  3:[['Intuición radiante','En esta sesión reuniste varias coincidencias por encima del promedio esperado (1 de 5 al azar). Tómalo como una invitación a observar tus corazonadas, no como una prueba definitiva.'],
     ['Una racha que llama la atención','3 aciertos es más del triple de lo que predice el puro azar. Fíjate si hubo algún patrón: ¿acertaste más al principio, al final, con algún símbolo en particular?']],
  2:[['Percepción sensible','Captaste alguna señal entre el azar. La pausa, la atención y jugar sin presión pueden ayudarte a notar cómo decides.'],
     ['Un resultado dentro de lo esperable','2 de 5 está cerca de lo que predice la estadística para cualquier persona jugando al azar — pero eso no le quita lo interesante a la experiencia.']],
  1:[['Percepción sensible','Captaste alguna señal entre el azar. La pausa, la atención y jugar sin presión pueden ayudarte a notar cómo decides.'],
     ['Justo en el promedio','1 de 5 es exactamente lo que predice la probabilidad si eligieras al azar en cada ronda — un resultado perfectamente normal y esperado.']],
  0:[['Mente exploradora','Hoy predominó el azar, y eso también es parte del experimento. Una sesión corta no define tu intuición ni tu capacidad de percibir.'],
     ['Cero no es un mal resultado','Curiosamente, 0 de 5 también es una desviación del promedio esperado (1 de 5) — tan infrecuente estadísticamente como acertar 2. El azar, a veces, también sorprende por abajo.']]
};
function espResult(){
  const [title,desc]=espTierContent[state.espHits][Math.floor(Math.random()*espTierContent[state.espHits].length)];
  const streak=espLongestStreak(state.espHistory);
  const recap=state.espHistory.map((r,i)=>`<div class="esp-recap-row ${r.hit?'hit':'miss'}"><span>Ronda ${i+1}</span><span>${symbols[r.choice]} ${symbolNames[r.choice]}</span><span>${r.hit?'✓ acierto':`✗ era ${symbols[r.target]} ${symbolNames[r.target]}`}</span></div>`).join('');
  shell(`${head('✦','Tu lectura intuitiva','Así terminó este pequeño experimento')}<div class="panel esp-result-panel"><div class="score-orb">${state.espHits}/5</div><div class="result"><strong>${title}</strong><p>${desc}</p></div>${streak>=2?`<div class="esp-score-guide"><h3>✦ Tu mejor racha</h3><div><b>${streak} ${streak===1?'acierto seguido':'aciertos seguidos'}</b><span>${streak>=3?'Una racha así de larga, por puro azar, es poco común — fue el momento más fuerte de tu sesión.':'Dos aciertos seguidos ya es un poco más de lo típico por azar.'}</span></div></div>`:''}<div class="esp-score-guide"><h3>Ronda por ronda</h3>${recap}</div><div class="esp-score-guide"><h3>¿Cómo leer tu puntuación?</h3><div><b>0 de 5</b><span>Suena a mala suerte, pero es tan raro estadísticamente como acertar 2: fallar las 5 por puro azar pasa apenas el 33% de las veces. <b>Tu percepción en esta sesión:</b> tu mente estaba enfocada en otro lugar en este momento exacto — no es un reflejo de que tu intuición sea débil, solo que hoy no se sintonizó durante el juego.</span></div><div><b>1 de 5</b><span>Es el resultado promedio esperado incluso eligiendo al azar (20% de probabilidad por ronda). <b>Tu percepción en esta sesión:</b> se mantuvo en un estado neutral, ni especialmente despierta ni bloqueada — tu punto de partida habitual.</span></div><div><b>2 de 5</b><span>Una sesión con algunas coincidencias, algo que ocurre por azar cerca del 20% de las veces. <b>Tu percepción en esta sesión:</b> tuvo momentos puntuales donde tu primera impresión coincidió con la carta oculta — señal de que, al menos a ratos, estabas bien sintonizado.</span></div><div><b>3 de 5</b><span>Una racha llamativa: ocurre por azar menos de 1 de cada 10 veces. <b>Tu percepción en esta sesión:</b> estuvo más activa de lo habitual — vale la pena notar qué estado mental tenías justo antes de empezar a jugar.</span></div><div><b>4 de 5</b><span>Esto pasa por puro azar menos del 1% de las veces. <b>Tu percepción en esta sesión:</b> estuvo en un punto muy alto de sintonía con tu primer instinto, sea casualidad o un buen momento de conexión contigo mismo.</span></div><div><b>5 de 5</b><span>La probabilidad de lograrlo solo por azar es de 1 en 3,125 — más raro que sacar 11 caras seguidas lanzando una moneda. <b>Tu percepción en esta sesión:</b> estuvo en sintonía perfecta entre tu primera impresión y la realidad, el tipo de momento que recuerda lo presente que puedes estar cuando confías en tu instinto sin pensarlo de más.</span></div></div><div class="esp-score-guide"><h3>✦ El origen de este juego</h3><div><span>Este formato está inspirado en las cartas Zener, creadas en los años 1930 por el psicólogo Karl Zener y usadas por J.B. Rhine en la Universidad de Duke para estudiar la percepción extrasensorial. Con 5 símbolos posibles, el azar puro predice un acierto de cada cinco intentos — la ciencia moderna no ha encontrado evidencia reproducible de percepción extrasensorial real en estos experimentos, pero siguen siendo un juego entretenido para observar tu propia intuición.</span></div></div><button class="primary" id="again">Repetir el test</button><p class="note">Este juego es recreativo: no mide capacidades extrasensoriales de forma científica ni predice decisiones o acontecimientos.</p></div>`);
  sound('reveal');log('esp_complete',{hits:state.espHits,streak});
  $('#again').onclick=()=>{sound();esp()};
}

const rituals={proteccion:[['Círculo de calma','Un vaso con agua · una pizca de sal','Coloca el vaso cerca de una ventana.','Respira tres veces y visualiza un límite luminoso.','Desecha el agua al terminar y agradece el momento.'],['Amuleto de intención','Una cinta azul · papel pequeño','Escribe una palabra que te dé seguridad.','Dobla el papel hacia ti y rodéalo con la cinta.','Guárdalo donde puedas recordarlo.'],['Escudo de sal','Sal · una escoba o cepillo pequeño','Coloca un poco de sal en las esquinas de la habitación.','Visualiza una luz que cubre todo el espacio.','Al día siguiente, barre la sal hacia afuera de la puerta.'],['Espejo que refleja','Un espejo pequeño','Colócalo orientado hacia tu puerta de entrada.','Fija la intención de que lo que no te sirve se quede afuera.','Límpialo una vez por semana con un paño seco.'],['Nudo protector','Un cordón o hilo largo','Haz tres nudos, nombrando en cada uno algo que te preocupa soltar.','Sostén el cordón unos segundos respirando con calma.','Llévalo en el bolsillo o átalo a tu mochila.'],['Vela de frontera','Una vela blanca · un lugar seguro cerca de la entrada','Enciéndela y visualiza un límite cálido alrededor de tu espacio.','Quédate unos minutos en silencio observando la llama.','Apágala con un apagavelas o soplando, nunca la dejes sola.']],abundancia:[['Semilla de propósito','Una semilla · una maceta','Escribe una meta concreta y alcanzable.','Planta la semilla pensando en tu primer paso.','Cuídala mientras registras tus avances.'],['Cuenco de gratitud','Un cuenco · cinco monedas','Nombra algo que ya tienes por cada moneda.','Define una acción generosa para esta semana.','Repite al inicio de cada mes.'],['Billete de intención','Un billete pequeño · un papel','Escribe en el papel una meta financiera concreta.','Dobla el papel alrededor del billete.','Guárdalo en tu billetera hasta cumplir la meta.'],['Planta de la fortuna','Una planta pequeña de interior','Riégala cada lunes pensando en una meta en curso.','Observa su crecimiento como recordatorio de paciencia.','Cuando florezca o crezca, anota qué avanzaste tú también.'],['Frasco de monedas','Un frasco de vidrio · monedas sueltas','Agrega una moneda cada día, agradeciendo algo recibido.','Observa el frasco llenarse poco a poco durante el mes.','Al llenarse, decide un destino consciente para ese dinero.'],['Lista de abundancia','Papel · lápiz','Escribe diez cosas de valor que ya tienes, no materiales.','Léela en voz alta una vez.','Guárdala donde puedas releerla cuando dudes de ti.']],amor:[['Carta de amor propio','Papel · sobre · aroma favorito','Escribe tres cualidades que aprecias de ti.','Añade un compromiso de cuidado personal.','Abre la carta en una semana.'],['Ritual de armonía','Dos flores · recipiente con agua','Asigna a cada flor una voz del vínculo.','Expresa en silencio una necesidad y una gratitud.','Colócalas juntas sin forzar sus tallos.'],['Autoabrazo consciente','Nada, solo tú y un espacio tranquilo','Cruza los brazos sobre el pecho y respira profundo tres veces.','Repite en voz baja una frase amable hacia ti mismo.','Quédate así un minuto antes de continuar tu día.'],['Jardín de vínculos','Una maceta · varias semillas pequeñas','Elige una semilla por cada relación que quieras cuidar.','Plántalas juntas, dejando espacio entre ellas.','Riégalas pensando en nutrir esos vínculos sin ahogarlos.'],['Taza compartida','Dos tazas de té o infusión','Prepara una taza para ti y otra para esa persona.','Comparte una conversación honesta mientras las beben.','Brinden en silencio al terminar, sin necesidad de palabras.'],['Hilo rojo','Un hilo o cordón rojo','Átalo a tu muñeca pensando en una persona importante para ti.','Llévalo puesto mientras dure de forma natural.','Cuando se caiga solo, agradece lo que esa relación te enseñó.']]};
