Object.assign(rituals,{"claridad": [["Mesa despejada", "Una mesa o escritorio · un paño", "Retira de la superficie todo lo que no uses hoy.", "Limpia con el paño mientras piensas en la decisión que necesitas aclarar.", "Deja sobre la mesa solo un papel con la pregunta escrita y reléela al día siguiente."], ["Lista de tres", "Papel · lápiz", "Escribe la decisión que tienes pendiente en la parte superior.", "Anota tres opciones posibles, sin juzgarlas.", "Elige una y escribe el primer paso de 10 minutos que darás hoy."], ["Caminata de preguntas", "Zapatos cómodos · 20 minutos", "Sal a caminar sin música ni teléfono a la vista.", "Formula una sola pregunta en tu mente y repítela al ritmo de los pasos.", "Al volver, escribe lo primero que se te ocurrió, sin corregirlo."], ["Vela de enfoque", "Una vela pequeña · un lugar seguro", "Enciéndela sobre una superficie estable y lejos de cortinas o papeles.", "Mira la llama un minuto y respira lento pensando en lo que quieres ver con claridad.", "Apaga con cuidado y no la dejes encendida sin vigilancia."], ["Agua de la mañana", "Un vaso de agua", "Antes de mirar el teléfono, bebe el agua despacio.", "Con cada trago nombra una prioridad del día.", "Quédate solo con las tres que nombraste y deja el resto para después."]], "descanso": [["Cierre del día", "Papel · lápiz · luz tenue", "Escribe todo lo que quedó pendiente, hasta vaciar la mente.", "Dobla el papel y guárdalo lejos de la cama.", "Respira lento cuatro veces y repite: \"Lo retomo mañana.\""], ["Infusión de pausa", "Una infusión suave (manzanilla, tila) · una taza", "Prepara la infusión sin prisa y sin pantallas.", "Sostén la taza con ambas manos y siente el calor.", "Bébela despacio; si tienes dudas sobre alguna planta, consulta con tu médico."], ["Respiración 4-6", "Un lugar cómodo", "Inhala contando cuatro segundos por la nariz.", "Exhala lentamente contando seis.", "Repite diez ciclos y deja los ojos cerrados un minuto más."], ["Luz baja", "Lámpara tenue", "Una hora antes de dormir, baja las luces de la casa.", "Aleja el teléfono de la cama y déjalo cargando en otro sitio.", "Anota una cosa buena del día antes de apagar la luz."], ["Almohada de gratitud", "Tu almohada · 2 minutos", "Acuéstate y repasa mentalmente tres cosas por las que estás agradecido.", "Siente cómo el cuerpo se afloja de pies a cabeza.", "Si surgen preocupaciones, di en silencio: \"Mañana lo veo.\""]], "soltar": [["Carta que no se envía", "Papel · lápiz", "Escribe una carta a la persona o situación que quieres soltar, sin filtros.", "Léela en voz baja una vez.", "Rómpela en trozos pequeños y deséchala, respirando hondo al hacerlo."], ["Cajón liberado", "Un cajón o caja · bolsa", "Elige un solo cajón y vacíalo por completo.", "Separa lo que sirve, lo que se dona y lo que se tira.", "Deja el cajón vacío unos días y observa cómo te sientes."], ["Hoja en el agua", "Una hoja de árbol · un lugar con agua corriente o un recipiente", "Sostén la hoja y piensa en lo que quieres dejar ir.", "Colócala sobre el agua y obsérvala alejarse.", "Cuando desaparezca, respira profundo y di: \"Gracias, ya puedo continuar.\""], ["Limpieza de contactos", "Tu teléfono · 10 minutos", "Revisa chats, fotos o contactos que ya no te hacen bien.", "Archiva o borra lo que sientas que pesa.", "Termina eligiendo una foto o mensaje que sí te haga sonreír."], ["Sacudida de cuerpo", "Música a tu gusto · un espacio libre", "Pon una canción y mueve el cuerpo sin pensar en cómo se ve.", "Sacude brazos, hombros y piernas hasta cansarte un poco.", "Termina en silencio, con la mano en el pecho, respirando."]], "sanar": [["Mano en el corazón", "Un lugar tranquilo", "Coloca una mano en el pecho y otra en el abdomen.", "Respira sintiendo el ritmo y nombra la emoción que estás sintiendo.", "Dite algo amable, como lo dirías a un buen amigo."], ["Baño de calma", "Agua tibia · sal marina (opcional)", "Prepara un baño o ducha con luz baja.", "Mientras el agua cae, imagina que arrastra la tensión del día.", "Sécate con calma y ponte ropa cómoda."], ["Diario de tres líneas", "Cuaderno · lápiz", "Anota cómo te sientes hoy en una línea.", "Escribe qué lo provocó en la segunda.", "Termina con qué necesitas en la tercera. Si el malestar persiste, busca apoyo profesional."], ["Agradecimiento a tu cuerpo", "5 minutos de silencio", "Recorre mentalmente tu cuerpo, de los pies a la cabeza.", "Agradece a cada parte lo que hace por ti.", "Termina estirándote suavemente y bebiendo un vaso de agua."], ["Llamada pendiente", "Tu teléfono", "Piensa en alguien que te hace bien y a quien no escribes hace tiempo.", "Envíale un mensaje breve, solo para saludarle.", "Observa cómo te sientes después de conectar."]], "nuevo ciclo": [["Intención de luna nueva", "Papel · lápiz", "En luna nueva (o el primer día del mes), escribe tres intenciones en presente.", "Léelas en voz alta una vez.", "Guárdalas en un lugar visible y revísalas en la luna llena."], ["Primer paso", "Una agenda o calendario", "Elige un proyecto que quieras empezar.", "Define el primer paso concreto y ponle fecha.", "Hazlo hoy aunque sea pequeño; empezar es la parte más difícil."], ["Espacio nuevo", "Un rincón de tu casa", "Elige un rincón y límpialo por completo.", "Colócale un objeto que simbolice lo que quieres atraer (una planta, una foto, una frase).", "Cada mañana dedícale un minuto de atención."], ["Cumpleaños propio", "Papel · lápiz", "Cada año, en tu cumpleaños, escribe lo que quieres vivir y lo que quieres soltar.", "Guarda la hoja en un sobre.", "Ábrelo un año después y observa lo que se cumplió."], ["Semilla de lunes", "Una semilla o planta pequeña", "Elige un lunes para sembrar o replantar algo.", "Mientras lo haces, nombra el hábito que quieres cultivar.", "Riégala con constancia y toma una foto cada semana para ver el avance."]]});
function ritual(){shell(`${head('✧','Hechizos y rituales','Pequeñas prácticas para enfocar tu atención e intención.')}<div class="tabs">${Object.keys(rituals).map(k=>`<button class="choice ${state.ritual===k?'selected':''}" data-tab="${k}">${k==='proteccion'?'Protección':k[0].toUpperCase()+k.slice(1)}</button>`).join('')}</div><div id="rituals">${rituals[state.ritual].map(r=>`<article class="panel ritual-card"><h3>${r[0]}</h3><p class="eyebrow">Necesitas · ${r[1]}</p><ol class="steps"><li>${r[2]}</li><li>${r[3]}</li><li>${r[4]}</li></ol></article>`).join('')}</div><div class="panel"><p class="note">Prácticas simbólicas de bienestar. No sustituyen ayuda profesional. No ingieras ingredientes; si incorporas velas por tu cuenta, nunca las dejes sin supervisión.</p></div>`);document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{sound();state.ritual=b.dataset.tab;ritual()})}

