const zodiacProfiles={Aries:{qualities:['iniciativa y valentía','decisiones rápidas','entusiasmo por comenzar'],challenges:['la impaciencia puede parecer brusquedad','la competencia puede convertir un acuerdo en una lucha']},Tauro:{qualities:['lealtad y constancia','placer por lo sencillo y sensorial','necesidad de seguridad'],challenges:['la terquedad puede bloquear cambios','uno de los dos puede aferrarse a su manera de hacer las cosas']},'Géminis':{qualities:['curiosidad y conversación','facilidad para aprender','humor y movimiento'],challenges:['la dispersión puede frustrar','cambiar de opinión puede sentirse como falta de compromiso']},'Cáncer':{qualities:['cuidado y sensibilidad','memoria afectiva','importancia del hogar y la confianza'],challenges:['el silencio puede acumular resentimiento','la susceptibilidad puede hacer que todo se sienta personal']},Leo:{qualities:['calidez y generosidad','orgullo por lo que construyen','deseo de celebrar la vida'],challenges:['la necesidad de reconocimiento puede competir','el orgullo puede dificultar pedir disculpas']},Virgo:{qualities:['atención a los detalles','sentido práctico','deseo de mejorar lo que comparten'],challenges:['la crítica puede apagar la espontaneidad','la preocupación por hacerlo bien puede traer tensión']},Libra:{qualities:['diplomacia y búsqueda de armonía','gusto por compartir','capacidad de ver varios puntos de vista'],challenges:['evitar el conflicto puede dejar temas sin resolver','la indecisión puede cansar a quien espera una respuesta']},Escorpio:{qualities:['intensidad y profundidad','lealtad cuando existe confianza','intuición para leer lo que no se dice'],challenges:['los celos o el control pueden cerrar el diálogo','guardar demasiado puede crear distancia']},Sagitario:{qualities:['optimismo y aventura','honestidad directa','deseo de crecer y explorar'],challenges:['la franqueza puede herir sin intención','la necesidad de libertad puede parecer falta de presencia']},Capricornio:{qualities:['responsabilidad y perseverancia','metas a largo plazo','respeto por el esfuerzo'],challenges:['la seriedad puede dejar poco espacio al juego','priorizar resultados puede hacer que olviden expresar afecto']},Acuario:{qualities:['ideas originales','independencia y apertura','interés por lo diferente'],challenges:['la distancia emocional puede confundirse con desinterés','la necesidad de autonomía puede chocar con demandas de cercanía']},Piscis:{qualities:['empatía e imaginación','sensibilidad artística','capacidad de acompañar'],challenges:['absorber el ambiente puede generar confusión','evitar límites claros puede dejar necesidades sin decir']}};
const elementPairReadings={
  'Aire|Fuego':{common:['comparten curiosidad, entusiasmo y ganas de experimentar','las ideas del Aire encuentran impulso en el Fuego','pueden motivarse con planes, viajes, conversación y proyectos creativos'],friction:['el Fuego quiere actuar ya y el Aire necesita cambiar ideas antes de decidir','la intensidad de Fuego puede sentirse dominante; la ligereza de Aire, poco constante'],bridge:'Definan una meta concreta y dejen un espacio para que cada persona avance a su propio ritmo. La emoción necesita escucha y la libertad necesita acuerdos.'},
  'Agua|Fuego':{common:['ambos viven la relación con intensidad y pasión','el Fuego aporta iniciativa y el Agua aporta sensibilidad','pueden inspirarse, protegerse y crear un vínculo muy expresivo'],friction:['la impulsividad del Fuego puede herir la sensibilidad del Agua','el Agua puede replegarse mientras el Fuego siente que no recibe una respuesta clara'],bridge:'Bajen la velocidad durante una discusión: primero nombren la emoción, después expresen la petición y por último busquen una acción concreta.'},
  'Agua|Tierra':{common:['comparten deseo de construir confianza y estabilidad','la Tierra ofrece estructura y el Agua aporta cuidado emocional','pueden disfrutar del hogar, las rutinas afectivas y los proyectos duraderos'],friction:['la Tierra puede intentar resolver lo que el Agua solo necesita sentir','el Agua puede percibir frialdad donde la Tierra está demostrando compromiso con hechos'],bridge:'Combinen palabras afectuosas con soluciones prácticas. Preguntar “¿necesitas que te escuche o que te ayude?” evita muchos malentendidos.'},
  'Aire|Tierra':{common:['ambos pueden aprender mucho de la mirada del otro','Aire aporta ideas y Tierra convierte algunas en realidad','pueden complementarse en organización, estudio y proyectos útiles'],friction:['Tierra puede ver inconstancia en la exploración de Aire','Aire puede sentir que las reglas, rutinas o cautelas de Tierra limitan demasiado'],bridge:'Acuerden qué aspectos son flexibles y cuáles necesitan estructura. Una idea nueva merece una prueba pequeña antes de ser descartada.'},
  'Aire|Agua':{common:['comparten imaginación, curiosidad y sensibilidad ante el entorno','Aire ayuda a poner palabras; Agua ayuda a conectar con lo que se siente','pueden disfrutar de arte, música, conversación íntima y nuevas perspectivas'],friction:['Aire puede analizar una emoción cuando Agua necesita contención','Agua puede vivir como distancia lo que Aire entiende como necesidad de espacio'],bridge:'No intenten adivinar: expresen la necesidad directamente y respeten tanto el silencio reparador como el diálogo.'}
};
const sameElementReadings={Fuego:{common:['entusiasmo, iniciativa y una energía expresiva','gusto por actuar, celebrar y perseguir retos','necesidad de sentir que la relación está viva'],friction:['pueden competir por tener la razón o el protagonismo','la prisa de ambos puede dejar poco espacio para escuchar'],bridge:'Turnarse para liderar y celebrar los logros del otro mantiene la chispa sin convertirla en rivalidad.'},Tierra:{common:['constancia, realismo y deseo de seguridad','preferencia por demostrar el cariño con hechos','paciencia para construir algo que dure'],friction:['pueden quedarse demasiado tiempo en la rutina','la resistencia al cambio puede volver rígidas las decisiones'],bridge:'Introduzcan novedades pequeñas y hablen de lo que sienten, no solo de lo que hay que resolver.'},Aire:{common:['curiosidad, conversación y necesidad de estímulo mental','flexibilidad para conocer ideas distintas','humor y facilidad para compartir planes'],friction:['pueden saltar de un tema a otro sin cerrar acuerdos','la búsqueda de libertad puede hacerles evitar conversaciones incómodas'],bridge:'Pongan por escrito los acuerdos importantes y reserven momentos sin pantallas para escucharse.'},Agua:{common:['sensibilidad, intuición y profundidad emocional','gran importancia de la confianza y la cercanía','capacidad de acompañarse en momentos difíciles'],friction:['pueden absorber el estado de ánimo del otro','el silencio y las suposiciones pueden agrandar una herida pequeña'],bridge:'Hablen antes de interpretar. Los límites claros protegen la cercanía en lugar de romperla.'}};
function zodiacReading(a,b,ea,eb){if(a===b){const profile=zodiacProfiles[a];return {common:[...profile.qualities,'reconocen con facilidad sus ritmos y necesidades'],friction:profile.challenges,bridge:`${a} y ${b} pueden sentirse muy comprendidos, pero también reflejarse los mismos puntos ciegos. Repartan las responsabilidades y permitan que cada uno tenga una forma propia de hacer las cosas.`}}if(ea===eb)return sameElementReadings[ea];return elementPairReadings[[ea,eb].sort().join('|')]||{common:['cada uno aporta una perspectiva distinta','pueden aprender nuevas formas de sentir, pensar y actuar','la curiosidad por sus diferencias puede convertirse en un punto de unión'],friction:['sus ritmos pueden no coincidir','lo que para uno es natural puede resultar difícil de entender para el otro'],bridge:'La compatibilidad aquí nace de los acuerdos: expliquen sus necesidades, no den por hecho que la otra persona las adivinará y conviertan las diferencias en conversaciones.'}}
function zodiac(){shell(`${head('♊','Compatibilidad zodiacal','Combina dos energías y descubre qué comparten, dónde chocan y cómo pueden entenderse.')}<div class="panel"><div class="selectors">${signSelect('z1','Persona A')}<div class="vs">✦</div>${signSelect('z2','Persona B',6)}</div><button class="primary" id="compat">Ver compatibilidad</button><div id="zResult"></div></div><div class="panel"><p class="note">La astrología es un lenguaje simbólico. Los vínculos reales dependen de comunicación, respeto y experiencias compartidas.</p></div>`);$('#compat').onclick=()=>{let a=$('#z1').value,b=$('#z2').value,ea=elements[a],eb=elements[b];let score=62,text='Sus ritmos son distintos: la curiosidad y los acuerdos claros pueden convertir el contraste en crecimiento.';if(a===b){score=84;text='Comparten un lenguaje natural y se reconocen con facilidad. Cuiden de no reforzar mutuamente los mismos puntos ciegos.'}else if(ea===eb){score=88;text=`La afinidad de ${ea.toLowerCase()} crea comprensión espontánea. Su reto es dejar espacio a formas distintas de sentir y actuar.`}else if((ea==='Fuego'&&eb==='Aire')||(ea==='Aire'&&eb==='Fuego')){score=91;text='Aire aviva al Fuego: hay entusiasmo, ideas y movimiento. Conviene equilibrar impulso con escucha.'}else if((ea==='Agua'&&eb==='Tierra')||(ea==='Tierra'&&eb==='Agua')){score=89;text='Tierra contiene al Agua y Agua nutre a Tierra. Pueden construir seguridad emocional con mucha ternura.'}else if((ea==='Fuego'&&eb==='Agua')||(ea==='Agua'&&eb==='Fuego')){score=58;text='Intensidad y sensibilidad se encuentran. Funciona mejor cuando uno modera el impulso y el otro expresa lo que necesita.'}score+=((signs.indexOf(a)*7+signs.indexOf(b)*3)%7)-3;const details=zodiacReading(a,b,ea,eb);const list=items=>`<ul>${items.map(item=>`<li>${item}</li>`).join('')}</ul>`;sound('reveal');$('#zResult').innerHTML=`<div class="result zodiac-result"><div class="pair">${emoji[a]} + ${emoji[b]}</div><strong>${score}% · ${a} y ${b}</strong><div class="compat-meter"><i style="width:${score}%"></i></div><p>${text}</p><div class="zodiac-details"><section class="compat-section common"><h3>✦ Lo que tienen en común</h3>${list(details.common)}</section><section class="compat-section friction"><h3>△ Lo que puede no ser compatible</h3>${list(details.friction)}</section><section class="compat-section bridge"><h3>☾ Cómo pueden complementarse</h3><p>${details.bridge}</p></section></div></div>`;log('zodiac_match',{a,b,score})}}
function signSelect(id,label,selected=0){return `<label class="select-group"><span>${label}</span><select class="field" id="${id}">${signs.map((s,i)=>`<option ${i===selected?'selected':''}>${s}</option>`).join('')}</select></label>`}

const animals=['Rata','Buey','Tigre','Conejo','Dragón','Serpiente','Caballo','Cabra','Mono','Gallo','Perro','Cerdo'];
const animalIcon={Rata:'🐀',Buey:'🐂',Tigre:'🐅',Conejo:'🐇','Dragón':'🐉',Serpiente:'🐍',Caballo:'🐎',Cabra:'🐐',Mono:'🐒',Gallo:'🐓',Perro:'🐕',Cerdo:'🐖'};
function chineseSign(y){return animals[((y-1900)%12+12)%12]}
function chinese(){const now=new Date().getFullYear();shell(`${head('◉','Padres e hijos','Descubre sus animales del zodiaco chino y cómo se complementan.')}<div class="panel"><div class="selectors"><label class="select-group"><span>Padre / madre</span><input class="field" id="parentYear" type="number" inputmode="numeric" min="1920" max="${now}" value="1988"></label><div class="vs">✦</div><label class="select-group"><span>Hijo / hija</span><input class="field" id="childYear" type="number" inputmode="numeric" min="1920" max="${now}" value="2018"></label></div><button class="primary" id="china">Leer vínculo</button><div id="cResult"></div></div><div class="panel"><h3>Nota lunar</h3><p>El año chino comienza entre enero y febrero. Si el nacimiento fue en esas fechas, el signo exacto puede corresponder al año anterior.</p></div>`);$('#china').onclick=()=>{let py=+$('#parentYear').value,cy=+$('#childYear').value;if(py<1920||cy<1920||py>now||cy>now)return toast('Revisa los años ingresados');let p=chineseSign(py),c=chineseSign(cy),dist=Math.min((animals.indexOf(p)-animals.indexOf(c)+12)%12,(animals.indexOf(c)-animals.indexOf(p)+12)%12);let title,text;if(p===c){title='Espejo de temperamentos';text='Se comprenden por semejanza y comparten impulsos naturales. El adulto puede guiar mejor cuando evita proyectar su propia historia.'}else if(dist===4){title='Tríada de gran afinidad';text='Sus energías tradicionales forman una alianza fluida. Hay facilidad para motivarse y aprender uno del otro.'}else if(dist===6){title='Maestros del contraste';text='Tienen enfoques opuestos que pueden generar fricción, pero también grandes aprendizajes si se escuchan sin imponer ritmos.'}else{title='Vínculo complementario';text='Cada animal aporta una mirada diferente. Las rutinas claras y la curiosidad por sus diferencias fortalecen la conexión.'}sound('reveal');$('#cResult').innerHTML=`<div class="result"><div class="pair">${animalIcon[p]} + ${animalIcon[c]}</div><strong>${title}</strong><p><b>${p}</b> (${py}) y <b>${c}</b> (${cy}). ${text}</p></div>`;log('chinese_match',{parent:p,child:c})}}

const chineseProfiles={Rata:{rep:'ingenio, adaptación y capacidad de encontrar oportunidades',parent:'suele proteger anticipándose a los problemas y organizando cada detalle',child:'necesita sentirse escuchado y tener pequeños espacios para explorar por su cuenta',challenge:'la preocupación y el exceso de preguntas pueden sentirse como control'},Buey:{rep:'paciencia, esfuerzo constante y sentido de responsabilidad',parent:'suele enseñar con el ejemplo, la rutina y la perseverancia',child:'necesita tiempo para confiar y valorar que se reconozca su esfuerzo',challenge:'la rigidez o la prisa por obtener resultados pueden apagar su iniciativa'},Tigre:{rep:'valentía, independencia y deseo de defender lo que considera justo',parent:'suele impulsar a enfrentar retos y a probar la propia fuerza',child:'necesita límites firmes pero también libertad para tomar decisiones',challenge:'los choques de voluntad pueden convertirse en discusiones de poder'},Conejo:{rep:'sensibilidad, diplomacia y búsqueda de armonía',parent:'suele cuidar el ambiente emocional y evitar que los conflictos crezcan',child:'necesita un hogar tranquilo, palabras amables y seguridad afectiva',challenge:'evitar toda conversación difícil puede dejar necesidades sin expresar'},Dragón:{rep:'ambición, creatividad y una presencia inspiradora',parent:'suele motivar con grandes sueños y expectativas de crecimiento',child:'necesita admiración sincera, pero también permiso para avanzar a su ritmo',challenge:'las expectativas demasiado altas pueden hacerle sentir que nunca es suficiente'},Serpiente:{rep:'intuición, profundidad y capacidad de observar antes de actuar',parent:'suele guiar con consejos sutiles y leer lo que no se dice',child:'necesita confianza, privacidad y conversaciones sin juicios',challenge:'los silencios o secretos pueden confundirse con distancia emocional'},Caballo:{rep:'libertad, entusiasmo y necesidad de movimiento',parent:'suele animar a vivir experiencias y aprender haciendo',child:'necesita actividad, autonomía y acuerdos que no se sientan como una jaula',challenge:'la inconstancia o el exceso de reglas pueden provocar rechazo'},Cabra:{rep:'empatía, imaginación y sensibilidad artística',parent:'suele acompañar con ternura y priorizar el bienestar emocional',child:'necesita validación, paciencia y un espacio donde crear sin miedo a equivocarse',challenge:'la sobreprotección puede dificultar que desarrolle seguridad propia'},Mono:{rep:'ingenio, humor y curiosidad para resolver problemas',parent:'suele enseñar jugando, conversando y buscando soluciones creativas',child:'necesita estímulo mental y límites explicados con claridad',challenge:'las bromas o la dispersión pueden hacer que los acuerdos parezcan poco importantes'},Gallo:{rep:'claridad, observación y deseo de hacer las cosas correctamente',parent:'suele cuidar mediante consejos concretos y expectativas claras',child:'necesita saber qué se espera de él o ella sin sentirse juzgado continuamente',challenge:'la crítica frecuente puede convertirse en vergüenza o defensividad'},Perro:{rep:'lealtad, honestidad y un fuerte sentido de protección',parent:'suele estar presente, defender y enseñar el valor de la confianza',child:'necesita coherencia, afecto demostrable y promesas que se cumplan',challenge:'la vigilancia o la preocupación constante pueden limitar su confianza'},Cerdo:{rep:'generosidad, calidez y disfrute de los vínculos cercanos',parent:'suele expresar amor compartiendo tiempo, cuidados y recursos',child:'necesita cariño directo y aprender a poner límites sin culpa',challenge:'dar demasiado por evitar conflictos puede crear desequilibrios'} };
function chineseRelation(p,c,dist){const pp=chineseProfiles[p],cp=chineseProfiles[c];let title,summary,common,friction,bridge;if(p===c){title='Espejo de temperamentos';summary=`Ambos expresan la energía del ${p}: ${pp.rep}. Esta semejanza puede crear reconocimiento inmediato, porque el padre o la madre entiende desde dentro muchos impulsos del hijo o hija.`;common=[`Comparten ${pp.rep}.`,`El adulto puede reconocer con facilidad cuándo el hijo necesita apoyo, autonomía o estímulo.`,`Pueden disfrutar actividades relacionadas con esa energía: conversar y resolver retos (Rata, Mono), crear y descansar en calma (Conejo, Cabra, Cerdo), moverse y explorar (Tigre, Dragón, Caballo) o construir rutinas (Buey, Gallo, Perro, Serpiente).`];friction=[pp.challenge,'Al parecerse, pueden proyectar la propia historia: lo que el adulto superó o valoró no tiene por qué ser el mismo camino del hijo.'];bridge=`La clave es no confundir semejanza con obligación. ${pp.parent.charAt(0).toUpperCase()+pp.parent.slice(1)}; ${pp.child}.`; }else if(dist===4){title='Tríada de gran afinidad';summary=`El ${p} y el ${c} forman una combinación tradicionalmente fluida. El adulto puede ofrecer dirección desde ${pp.rep}, mientras el hijo aporta ${cp.rep}.`;common=[`Se complementan entre ${pp.rep} y ${cp.rep}.`,'Pueden motivarse sin perder la sensación de confianza: uno activa una cualidad y el otro la amplía.','Suelen funcionar bien los proyectos compartidos, las conversaciones sobre metas y las actividades donde ambos aprendan algo nuevo.'];friction=[`El padre o la madre puede esperar que el hijo responda con el mismo estilo de ${p}.`,`La afinidad puede llevarles a hacer demasiadas cosas juntos y dejar poco espacio para que el hijo encuentre su propia voz.`];bridge=`Usen la afinidad como puente, no como molde. Pregunta qué necesita el hijo antes de ofrecer una solución y celebra su manera particular de expresarse.`;}else if(dist===6){title='Maestros del contraste';summary=`El ${p} y el ${c} representan ritmos muy diferentes. Esa distancia puede producir roces, pero también enseñar al adulto a flexibilizarse y al hijo a comprender otras formas de actuar.`;common=['Comparten el vínculo y la posibilidad de aprender mutuamente, aunque no demuestren el cariño de la misma manera.','Pueden equilibrarse: una energía aporta lo que la otra tiende a olvidar.','Cuando tienen una meta clara, sus diferencias pueden repartir bien los papeles.'];friction=[`${pp.challenge}.`,`El hijo puede interpretar la guía del adulto como presión, mientras el adulto puede leer su reacción como desinterés o desafío.`,`Las discusiones pueden repetirse si cada uno intenta que el otro adopte su propio ritmo.`];bridge=`Describe la conducta sin etiquetar al niño o niña: “necesito que lleguemos a un acuerdo” funciona mejor que “eres demasiado...”. Ofrece dos opciones razonables y deja espacio para que el hijo participe en la solución.`;}else{title='Vínculo complementario';summary=`El ${p} aporta ${pp.rep}; el ${c} aporta ${cp.rep}. No necesitan parecerse para crear una relación cercana: su aprendizaje está en traducir esas diferencias con paciencia.`;common=['Comparten la oportunidad de construir confianza a través de experiencias cotidianas.','El adulto puede ofrecer una base y el hijo aportar una mirada nueva.','La curiosidad por sus animales representativos puede convertirse en una forma amable de hablar de necesidades reales.'];friction=[`${pp.challenge}.`,`El adulto puede demostrar cariño de una forma que el hijo no reconoce como afecto.`,`Las diferencias de energía, orden, sensibilidad o necesidad de libertad pueden causar malentendidos.`];bridge=`Convierte la diferencia en una pregunta: “¿qué te ayuda cuando estás preocupado?” y “¿cómo prefieres que te acompañe?”. Los acuerdos claros, el tiempo compartido y la escucha suelen ser más importantes que cualquier signo.`;}return {title,summary,common,friction,bridge,pp,cp}}
function chineseEnhanced(){const now=new Date().getFullYear();shell(`${head('◉','Padres e hijos','Explora qué representan sus animales y cómo se expresa el vínculo en la vida cotidiana.')}<div class="panel"><div class="selectors"><label class="select-group"><span>Padre / madre</span><input class="field" id="parentYear" type="number" inputmode="numeric" min="1920" max="${now}" value="1988"></label><div class="vs">✦</div><label class="select-group"><span>Hijo / hija</span><input class="field" id="childYear" type="number" inputmode="numeric" min="1920" max="${now}" value="2018"></label></div><button class="primary" id="china">Leer vínculo</button><div id="cResult"></div></div><div class="panel"><h3>¿Qué representan los animales?</h3><p>En esta lectura simbólica, cada animal describe una energía o tendencia: no define la personalidad de una persona ni determina cómo será la relación. Sirve como punto de partida para conversar sobre cuidados, límites, libertad y formas de demostrar cariño.</p></div><div class="panel"><h3>Nota lunar</h3><p>El año chino comienza entre enero y febrero. Si el nacimiento fue en esas fechas, el signo exacto puede corresponder al año anterior.</p></div>`);$('#china').onclick=()=>{let py=+$('#parentYear').value,cy=+$('#childYear').value;if(py<1920||cy<1920||py>now||cy>now)return toast('Revisa los años ingresados');let p=chineseSign(py),c=chineseSign(cy),dist=Math.min((animals.indexOf(p)-animals.indexOf(c)+12)%12,(animals.indexOf(c)-animals.indexOf(p)+12)%12),reading=chineseRelation(p,c,dist),list=items=>`<ul>${items.map(item=>`<li>${item}</li>`).join('')}</ul>`;sound('reveal');$('#cResult').innerHTML=`<div class="result chinese-result"><div class="pair">${animalIcon[p]} + ${animalIcon[c]}</div><strong>${reading.title}</strong><p>${reading.summary}</p><div class="animal-cards"><div><span>${animalIcon[p]}</span><b>Padre / madre · ${p}</b><small>${reading.pp.rep}</small></div><div><span>${animalIcon[c]}</span><b>Hijo / hija · ${c}</b><small>${reading.cp.rep}</small></div></div><div class="zodiac-details"><section class="compat-section common"><h3>✦ Lo que pueden compartir</h3>${list(reading.common)}</section><section class="compat-section friction"><h3>△ Dónde pueden chocar</h3>${list(reading.friction)}</section><section class="compat-section bridge"><h3>☾ Cómo acompañarse mejor</h3><p>${reading.bridge}</p></section></div></div>`;log('chinese_match',{parent:p,child:c})}}
const routes={dream,esp,ritual,zodiac,chinese:chineseEnhanced,angels,guardian:()=>{var u=new URL('../angel-de-la-guarda.html',location.href).href;try{var t=window.top;if(t!==window&&t.PortalMusic&&t.PortalMusic.go){t.PortalMusic.go(u);return}t.location.href=u}catch(e){location.href='../angel-de-la-guarda.html'}}};
